  --accent: #0066cc;
  --accent-hover: #0071e3;
  --accent-line: #0066cc;
  --accent-soft: rgba(0, 102, 204, 0.12);
  --accent-wash: rgba(0, 102, 204, 0.05);
  --on-accent: #ffffff;
  --ember: #0066cc;

  --live: #34c759;
  --live-ink: #248a3d;
