/* ------------------------------------------------------------- popovers
   Origin-aware: a popover belongs to its trigger, so it grows from it. */

.plus-menu {
  position: absolute;
  bottom: calc(100% - 4px);
  left: 24px;
  z-index: 30;
  width: 272px;
  padding: 5px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-lg);
  background: var(--glass);
  backdrop-filter: blur(16px);
  box-shadow: var(--lift);
  transform-origin: bottom left;
  animation: pop-in var(--menu) var(--ease-out);
}

@keyframes pop-in {
  from { opacity: 0; transform: scale(0.96) translate3d(0, 6px, 0); }
}

.plus-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--r-sm);
  text-align: left;
  font-size: 13.5px;
  color: var(--text-dim);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out),
              transform var(--press) var(--ease-out);
  opacity: 0;
  animation: rise 240ms var(--ease-out) forwards;
  animation-delay: calc(var(--i, 0) * 24ms);
}

@media (hover: hover) and (pointer: fine) {
  .plus-item:hover { background: rgb(var(--tint) / 0.06); color: var(--text); }
}
.plus-item:active { transform: scale(0.985); }
.plus-item svg { flex: none; opacity: 0.65; }
.plus-item .plus-tail { margin-left: auto; display: flex; align-items: center; gap: 7px; color: var(--text-faint); }
.plus-item .plus-count { font-size: var(--text-2xs); }

.plus-sep { height: 1px; margin: 5px 8px; background: var(--hairline); }
.plus-scroll { max-height: 296px; overflow-y: auto; }

.plus-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px 6px;
  font-size: var(--text-xs);
  color: var(--text-faint);
}

.plus-back { color: var(--text-faint); line-height: 0; transition: color var(--press) var(--ease-out); }
.plus-back:hover { color: var(--text); }
.plus-empty { padding: 14px 11px; font-size: 12.5px; color: var(--text-faint); line-height: 1.55; }

.plus-toggle {
  width: 24px;
  height: 14px;
  border-radius: 99px;
  background: rgb(var(--tint) / 0.1);
  position: relative;
  flex: none;
  transition: background var(--pop) var(--ease-out);
}

.plus-toggle::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 2px;
  width: 10px;
  height: 10px;
  border-radius: 99px;
  background: var(--text-faint);
  transition: transform var(--pop) var(--ease-drawer), background var(--pop) var(--ease-out);
}

.plus-toggle.on { background: var(--live-soft); }
.plus-toggle.on::after { transform: translate3d(10px, 0, 0); background: var(--live); }

.ac-menu {
  position: absolute;
  bottom: calc(100% - 4px);
  left: 24px;
  right: 24px;
  z-index: 30;
  padding: 5px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-lg);
  background: var(--glass);
  backdrop-filter: blur(16px);
  box-shadow: var(--lift);
  transform-origin: bottom left;
  animation: pop-in var(--pop) var(--ease-out);
}

.ac-item {
  display: flex;
  align-items: baseline;
  gap: 11px;
  width: 100%;
  padding: 8px 10px;
  border-radius: var(--r-sm);
  text-align: left;
  transition: background var(--press) var(--ease-out);
}

.ac-item.active, .ac-item:hover { background: rgb(var(--tint) / 0.06); }
.ac-name { font-family: var(--font-mono); font-size: 12.5px; color: var(--text); }
.ac-desc { font-size: 12.5px; color: var(--text-faint); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ------------------------------------------------------------- messages */

/* Two speakers, told apart by shape rather than by a name over each turn. The
   question is a bubble that stops short of the left margin and sits against the
   right; the answer runs the full width as prose. Nothing else in the column
   does either of those things, so no label is needed to say which is which. */
@keyframes msgEnter {
  from {
    opacity: 0;
    transform: translate3d(0, 5px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

.msg {
  display: grid;
  gap: 7px;
  min-width: 0;
  animation: msgEnter 0.22s cubic-bezier(0.16, 1, 0.3, 1) both;
}

.msg-user { justify-items: end; }
.msg-user .msg-body { max-width: min(78%, 62ch); }

/* Held out of the reading line until asked for. Opacity only -- these sit in a
   grid row of their own, so nothing reflows when they arrive. */
.msg-actions {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: -2px;
  opacity: 0;
  transition: opacity var(--menu) var(--ease-out);
}
.msg:hover .msg-actions,
.msg-actions:focus-within { opacity: 1; }

/* A pinned message keeps its controls visible: the pin is a state, and a state
   you can only see by hovering is one you will forget you set. */
.msg.is-pinned .msg-actions { opacity: 1; }

@media (pointer: coarse) {
  .msg-actions { opacity: 1; }
}

/* Who is speaking is metadata about the message, not part of it, so it is set
   the way every other machine fact in this interface is set: mono, small, ash,
   lowercase. It should be readable without ever being read. */
.msg-role {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  color: var(--text-faint);
}

/* The answer is the longest continuous prose in the interface and the only
   thing here that is properly read rather than scanned, so it gets the size and
   the measure that implies: 15.5px over 1.72, and a hard stop at 72 characters.
   Without the measure a reply ran the full 780px of the column -- about 100
   characters -- which is past the width at which the eye reliably finds the
   start of the next line. */
.msg-body {
  word-break: break-word;
  font-size: calc(15.5px * var(--text-scale, 1));
  line-height: 1.72;
  /* 62ch, not 72: `ch` measures a zero, which is wider than the average
     lowercase letter, so 72ch came out at about 90 characters of actual prose
     -- past the point where the eye reliably finds the next line. This lands
     near 75. */
  max-width: 62ch;
  letter-spacing: -0.003em;
}
.msg-body--plain { white-space: pre-wrap; }

.msg-user {
  justify-items: end;
  width: 100%;
}

.msg-user-row {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  justify-content: flex-end;
  width: 100%;
}

.msg-user-content {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
  min-width: 0;
  max-width: min(84%, 62ch);
}

.msg-user-avatar {
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  margin-top: 2px;
  cursor: pointer;
}

.msg-user .msg-body {
  padding: 10px 16px;
  border: 1px solid var(--hairline);
  border-radius: 18px;
  background: var(--surface-2);
  color: var(--text);
  text-align: left;
  font-size: calc(14.5px * var(--text-scale, 1));
  line-height: 1.55;
  width: fit-content;
  min-width: fit-content;
  max-width: 100%;
  word-break: normal;
  overflow-wrap: break-word;
  white-space: pre-wrap;
  box-sizing: border-box;
}
.msg-user-meta {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  margin-top: 4px;
  font-size: 11px;
  color: var(--text-faint);
  opacity: 0.85;
}
.msg-user-meta .msg-time {
  font-size: 11px;
  color: var(--text-faint);
  margin-right: 2px;
}
.msg-user-meta .msg-action-btn {
  background: transparent;
  border: none;
  color: var(--text-faint);
  cursor: pointer;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: var(--r-sm, 8px);
  transition: color var(--press) var(--ease-out), background-color var(--press) var(--ease-out);
}
.msg-user-meta .msg-action-btn:hover {
  color: var(--text);
  background: rgb(var(--tint) / 0.06);
}

.msg-assistant .msg-body { color: var(--text); }

/* Quoted prose is the one place inside a reply that is being read rather than
   scanned, so it is the one place the serif appears. */
.msg-body blockquote {
  margin: 10px 0;
  padding: 2px 0 2px 16px;
  border-left: 1px solid var(--hairline-strong);
  font-family: var(--font-serif);
  font-size: 17px;
  line-height: 1.5;
  color: var(--text-dim);
}

.msg-reasoning {
  display: grid;
  gap: 5px;
  padding: 10px 14px;
  border-left: 1px solid var(--hairline-strong);
  color: var(--text-faint);
  font-size: 12.5px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.msg-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px 14px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  font-size: 12.5px;
  color: var(--text-dim);
  line-height: 1.55;
}

.msg-note svg { flex: none; margin-top: 2px; opacity: 0.8; }
.msg-note--guard { border-color: var(--confirm-line); background: var(--confirm-soft); color: var(--confirm); }
.msg-note--error { border-color: var(--stop-line); background: var(--stop-soft); color: var(--stop); }
.msg-note--warning { border-color: var(--hairline-strong); background: rgb(var(--tint) / 0.025); }

/* The way out of a failed turn, in the card that reports it. Pushed to the far
   end so the sentence reads first and the button is where the eye lands after
   it. */
.msg-note-action {
  flex: none;
  margin: -3px 0 -3px auto;
  border-color: currentColor;
  color: inherit;
}

.tele-cursor::after {
  content: '';
  display: inline-block;
  width: 2px;
  height: 1.05em;
  margin-left: 3px;
  vertical-align: text-bottom;
  background: var(--ember);
  border-radius: 1px;
  animation: blink 1s steps(2, start) infinite;
}

/* Each block of a streaming answer fades up as it lands, rather than the whole
   reply snapping a paragraph taller every few tokens. `.md` is a grid, so a new
   child is a new row and the ones above it never move -- which is what makes
   this safe to animate at all. Opacity and transform only.

   Scoped to the live message: replaying it on every settled block would mean
   the whole transcript re-animating every time a token lands. */
.msg-assistant .tele-cursor ~ *,
.msg-assistant .md > * {
  animation: block-in 240ms var(--ease-out) both;
}

@keyframes block-in {
  from { opacity: 0; transform: translate3d(0, 4px, 0); }
  to { opacity: 1; transform: none; }
}

/* Once the turn has settled there is nothing arriving, so nothing animates. */
.msg-assistant:not(.is-live) .md > * { animation: none; }

@media (prefers-reduced-motion: reduce) {
  .msg-assistant .md > * { animation: none; }
}

@keyframes blink { 50% { opacity: 0; } }


/* ------------------------------------------------------- artifact panel */

/* What the agent wrote, in the panel beside what it said. The backend has
   streamed these since `create_artifact` shipped; this is the first thing on
   the front end that listens. */

.wb-panel-tabs {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 var(--space-lg) var(--space-sm);
  border-bottom: 1px solid var(--hairline);
}

.wb-panel-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: var(--r-md);
  font-size: var(--text-xs);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}
.wb-panel-tab.is-active { color: var(--text); background: rgb(var(--tint) / 0.06); }

@media (hover: hover) and (pointer: fine) {
  .wb-panel-tab:hover { color: var(--text-dim); }
}

.wb-panel-tab-count {
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  color: var(--text-faint);
}

.artifact {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  gap: var(--space-sm);
}

/* The head, the switch and the footer are chrome: they are the width of the
   panel and never the width of the document inside it. */
.artifact-head,
.artifact-tabs,
.artifact-foot { min-width: 0; max-width: 100%; }

.artifact-head { display: flex; align-items: center; gap: 8px; }

.artifact-switch {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  flex: 1 1 0;
  min-width: 0;
  padding: 4px 6px;
  border-radius: var(--r-md);
  color: var(--text);
  font-size: var(--text-sm);
  transition: background var(--press) var(--ease-out);
}
.artifact-switch:disabled { cursor: default; }

@media (hover: hover) and (pointer: fine) {
  .artifact-switch:not(:disabled):hover { background: rgb(var(--tint) / 0.06); }
}

.artifact-switch svg { flex: none; color: var(--text-faint); }
.artifact-title { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.artifact-of {
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  color: var(--text-faint);
}
.artifact-switch-caret { transition: transform var(--menu) var(--ease-out); }
.artifact-switch.is-open .artifact-switch-caret { transform: rotate(90deg); }

/* A version is a machine fact about a file, so it is set like one. */
.artifact-version {
  flex: none;
  padding: 1px 5px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  color: var(--text-faint);
}

.artifact-list {
  display: grid;
  gap: 1px;
  padding: 4px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas-deep);
  overflow: hidden;
}

.artifact-list-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px 8px;
  border-radius: var(--r-sm);
  font-size: var(--text-xs);
  color: var(--text-dim);
  text-align: left;
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.artifact-list-row svg { flex: none; color: var(--text-faint); }
.artifact-list-name { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.artifact-list-row.is-active { background: rgb(var(--tint) / 0.07); color: var(--text); }

@media (hover: hover) and (pointer: fine) {
  .artifact-list-row:hover { background: rgb(var(--tint) / 0.05); color: var(--text); }
}

/* The toolbar: which view, which document, what you can do with it. */
.artifact-views {
  display: flex;
  align-items: center;
  gap: 2px;
  flex: none;
  padding: 2px;
  border-radius: var(--r-md);
  background: rgb(var(--tint) / 0.05);
}

.artifact-view-btn {
  position: relative;
  display: grid;
  place-items: center;
  width: 26px;
  height: 24px;
  border-radius: var(--r-sm);
  color: color-mix(in srgb, var(--text) 62%, transparent);
  transition: color var(--press) var(--ease-out);
}
.artifact-view-btn.is-active { color: var(--on-accent); }

@media (hover: hover) and (pointer: fine) {
  .artifact-view-btn:not(.is-active):hover { color: var(--text); }
}

/* One pill, moved between the two by `layoutId`. */
.artifact-view-pill {
  position: absolute;
  inset: 0;
  border-radius: var(--r-sm);
  background: var(--accent);
}
.artifact-view-icon { position: relative; }

.artifact-actions { display: flex; align-items: center; gap: 1px; flex: none; margin-left: auto; }

.artifact-act {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: var(--r-sm);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}
.artifact-act.is-on { color: var(--text); background: rgb(var(--tint) / 0.08); }

@media (hover: hover) and (pointer: fine) {
  .artifact-act:hover { color: var(--text); background: rgb(var(--tint) / 0.06); }
}

.artifact-kind {
  flex: none;
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  color: var(--text-faint);
}

.artifact-bytes { flex: none; font-variant-numeric: tabular-nums; color: var(--text-faint); }

/* The view being crossfaded has to fill the box it sits in, or the code gutter
   loses its sticky column. */
.artifact-view { min-height: 100%; min-width: 0; flex: 1; display: flex; flex-direction: column; }
.artifact-view:has(.artifact-preview--frame) { min-height: 0; height: 100%; }

.artifact-meta {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  color: var(--text-faint);
}
.artifact-writing { display: inline-flex; align-items: center; color: var(--confirm); }

.artifact-body {
  flex: 1;
  min-height: 0;
  /* The one element allowed to scroll sideways, and only inside itself. */
  min-width: 0;
  overflow: auto;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas-deep);
  scrollbar-width: none;
  display: flex;
  flex-direction: column;
}
.artifact-body::-webkit-scrollbar { display: none; }
/* When showing HTML preview, fill height instead of scrolling */
.artifact-body:has(.artifact-preview--frame) { overflow: hidden; }

/* Source view: a gutter of numbers that cannot drift out of step with the text
   beside it, because both are one `pre` sharing a line height and neither is
   allowed to wrap. */
.artifact-code { display: flex; align-items: flex-start; min-width: min-content; }

.artifact-code-gutter,
.artifact-code-text {
  padding: var(--space-md) 0;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  line-height: 1.65;
  tab-size: 2;
}

.artifact-code-gutter {
  position: sticky;
  left: 0;
  padding-inline: var(--space-md) var(--space-sm);
  text-align: right;
  color: var(--text-faint);
  background: var(--canvas-deep);
  user-select: none;
  font-variant-numeric: tabular-nums;
}

.artifact-code-text {
  padding-right: var(--space-md);
  color: var(--text);
  white-space: pre;
}

/* The document being typed. A block caret sitting after the last character,
   riding the text as it arrives -- it is inline, so it moves with the content
   for free and nothing has to be positioned per frame. */
.artifact-caret {
  display: inline-block;
  width: 7px;
  height: 1.05em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background: var(--ember);
  border-radius: 1px;
  animation: artifact-caret 1s steps(2, start) infinite;
}
@keyframes artifact-caret { 50% { opacity: 0; } }

/* A hairline in the accent while the file is open for writing, so the panel
   says "live" without a badge. Border colour only -- no shadow to repaint. */
.artifact-body.is-writing { border-color: color-mix(in srgb, var(--ember) 45%, var(--hairline)); }

@media (prefers-reduced-motion: reduce) {
  .artifact-caret { animation: none; }
}

.artifact-preview { padding: 0; height: 100%; }
.artifact-preview--doc { font-size: var(--text-md); padding: var(--space-lg); }
.artifact-preview--frame {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
}
.artifact-preview--image { color: var(--text-dim); padding: var(--space-lg); }

.artifact-note {
  display: flex;
  align-items: flex-start;
  gap: 7px;
  padding: 8px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  font-size: var(--text-2xs);
  color: var(--text-dim);
}
.artifact-note svg { flex: none; margin-top: 1px; }
.artifact-note--bad { border-color: var(--stop-line); background: var(--stop-soft); color: var(--stop); }

.artifact-foot {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: var(--text-3xs);
}
.artifact-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-faint);
}
.artifact-copy {
  flex: none;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: var(--r-sm);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .artifact-copy:hover { color: var(--text); background: rgb(var(--tint) / 0.06); }
}



/* ----------------------------------------------------------- turn rail */

/* One tick per turn down the right edge of the transcript, so a long
   conversation has landmarks instead of a uniform scrollbar. Sits over the
   column rather than in it -- it must not take width off the reading measure --
   and stays out of the way until pointed at. */

.rail {
  position: absolute;
  top: 50%;
  right: 6px;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  /* Real padding, so the pointer is inside the rail well before it is on a
     tick. Approaching from the text side used to mean crossing a 2px-tall
     target with nothing around it. */
  padding: 6px 10px;
  transform: translateY(-50%);
  opacity: 0.62;
  transition: opacity var(--menu) var(--ease-out);
}

.chat-main:hover .rail { opacity: 0.85; }
.rail:hover,
.rail:focus-within { opacity: 1; }

@media (pointer: coarse), (max-width: 900px) {
  .rail { display: none; }
}

@media (min-width: 901px) {
  .chat-scroll {
    padding-right: 64px;
  }
}

.rail-step {
  display: grid;
  place-items: center;
  width: 26px;
  height: 22px;
  border-radius: var(--r-sm);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}
.rail-step:disabled { opacity: 0.3; cursor: default; }
.rail-step-up { transform: rotate(-90deg); }
.rail-step-down { transform: rotate(90deg); }

@media (hover: hover) and (pointer: fine) {
  .rail-step:not(:disabled):hover { color: var(--text); background: rgb(var(--tint) / 0.07); }
}

.rail-ticks {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0;
}

/* The button is the hit area and the bar inside it is the mark. A 2px-tall
   target with a 5px gap either side asked for pixel-accurate aim; the row is
   16px tall now with no gap between rows, so the whole rail is one continuous
   strip of targets and the bar is only what you see. */
.rail-tick {
  position: relative;
  display: block;
  width: 26px;
  height: 16px;
  background: none;
  border: 0;
}

.rail-tick::before {
  content: '';
  position: absolute;
  top: 50%;
  right: 0;
  width: calc(9px + var(--len, 1) * 4px);
  height: 3px;
  margin-top: -1.5px;
  border-radius: 2px;
  background: var(--text-faint);
  opacity: 0.55;
  transform-origin: right center;
  transition: transform var(--press) var(--ease-out), opacity var(--press) var(--ease-out),
              background var(--press) var(--ease-out);
}

.rail-tick--user::before { background: var(--text-dim); opacity: 0.75; }

.rail-tick.is-current::before {
  background: var(--ember);
  opacity: 1;
  transform: scaleX(1.3);
}

@media (hover: hover) and (pointer: fine) {
  .rail-tick:hover::before { opacity: 1; transform: scaleX(1.3); }
}

.rail-tick:focus-visible { outline: none; }
.rail-tick:focus-visible::before { opacity: 1; transform: scaleX(1.3); background: var(--ember); }

/* Anchored off the hovered tick by percentage, so moving between ticks is a
   transform on one element rather than a reflow. */
.rail-peek {
  position: absolute;
  top: var(--at, 50%);
  right: calc(100% + 12px);
  width: 230px;
  display: grid;
  gap: 3px;
  padding: 9px 11px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--glass);
  backdrop-filter: blur(8px);
  box-shadow: var(--lift);
  transform: translateY(-50%);
  pointer-events: none;
  animation: rail-peek-in 160ms var(--ease-out);
}

@keyframes rail-peek-in {
  from { opacity: 0; transform: translateY(-50%) translateX(4px); }
  to { opacity: 1; transform: translateY(-50%) translateX(0); }
}

.rail-peek-who {
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  color: var(--text-faint);
}
.rail-peek-text {
  font-size: var(--text-xs);
  line-height: 1.45;
  color: var(--text);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .rail-peek { animation: none; }
  .rail-tick { transition: none; }
}

/* ------------------------------------------------------------- motion

   One rule governs everything below: only `transform` and `opacity` are
   animated, plus `grid-template-rows` where a real height change is needed --
   that one is a layout property, but it is the single cheap way to animate to
   and from an unknown height without measuring, and it runs once per open
   rather than per frame.

   Durations are short and the curve is the same throughout, so the surface
   feels like one object rather than a set of separately-tuned parts. Anything
   a person triggers a hundred times a day (hover, press) stays under 140ms;
   anything that describes something arriving gets 200-280ms.

   Every block here is switched off wholesale under `prefers-reduced-motion` at
   the end of the section. */

/* Opening a fold: the track grows, the contents fade. No height is measured
   and nothing above the element moves. */
.trace-fold {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--menu) var(--ease-out);
}
.trace-fold.is-open { grid-template-rows: 1fr; }

.trace-fold-inner {
  overflow: hidden;
  min-height: 0;
  opacity: 0;
  transition: opacity 120ms var(--ease-out);
}
.trace-fold.is-open .trace-fold-inner { opacity: 1; transition-delay: 60ms; }

/* Trace rows assemble in sequence when the trace is opened, capped so a turn
   with forty steps does not take four seconds to draw. */
.trace-row-slot {
  animation: trace-row-in 260ms var(--ease-out) both;
  animation-delay: calc(var(--i, 0) * 26ms);
}

@keyframes trace-row-in {
  from { opacity: 0; transform: translate3d(-4px, 0, 0); }
  to { opacity: 1; transform: none; }
}

/* The caret that opens a fold turns to point down. */
.trace-row .trace-icon { transition: transform var(--menu) var(--ease-out); }
.trace-row.is-open .trace-icon { transform: scale(1.08); }

.trace-summary-caret { transform: rotate(0deg); }
.trace.is-open .trace-summary-caret { transform: rotate(90deg); }

/* A message arriving. The turn is the unit, so the whole block rises once
   rather than each of its parts moving independently. */
.stream-item { min-width: 0; animation: turn-in 280ms var(--ease-out) both; }

@keyframes turn-in {
  from { opacity: 0; transform: translate3d(0, 8px, 0); }
  to { opacity: 1; transform: none; }
}

/* Replaying that on a conversation being read back would animate forty turns
   at once on open, so history arrives already settled -- the class is added by
   the view once its first paint is done. */
.chat-stream.is-settled .stream-item { animation: none; }

/* The user's own message should feel like it was sent: it comes in from the
   side it lives on rather than straight up. */
.stream-item:has(.msg-user) { animation-name: turn-in-user; }

@keyframes turn-in-user {
  from { opacity: 0; transform: translate3d(10px, 4px, 0); }
  to { opacity: 1; transform: none; }
}

/* Banners and notes push the conversation down when they arrive, so they get
   the same entrance as a turn rather than appearing between frames. */
.chat-banner { animation: turn-in 240ms var(--ease-out) both; }

/* Pressing things. Every control answers the press with the same amount of
   give, which is what makes a surface feel like one material. */
.trace-line,
.trace-summary,
.trace-fold-btn,
.artifact-tab,
.artifact-switch,
.artifact-list-row,
.rail-tick,
.rail-step,
.hero-hint,
.menu-more { transition-property: color, background, border-color, opacity, transform; }

.trace-line:active,
.trace-summary:active,
.artifact-list-row:active { transform: scale(0.995); }

.trace-artifact:active { transform: scale(0.99) translate3d(0, 0, 0); }

/* The send button, which is the one control that completes something. */
.composer-send { will-change: transform; }
.composer-send:not(:disabled):active { transform: scale(0.9); }
.composer-send > svg { transition: transform var(--pop) var(--ease-out); }

@media (hover: hover) and (pointer: fine) {
  .composer-send:not(:disabled):hover > svg { transform: translate3d(1px, -1px, 0); }
}

/* The jump-to-latest button, which appears and disappears with the scroll. */
.jump-latest { animation: pop-in var(--pop) var(--ease-out) both; }

@media (prefers-reduced-motion: reduce) {
  .trace-fold { transition: none; }
  .trace-fold-inner { transition: none; }
  .trace-row-slot,
  .stream-item,
  .chat-banner,
  .jump-latest { animation: none; }
  .composer-send > svg { transition: none; }
}

/* ---- menus, panel and composer -----------------------------------------

   The same curve and the same distances as everything above, so a menu opening
   and a message arriving feel like the same surface moving. */

/* A menu row's chevron leans toward what it opens. */
.menu-row .menu-caret { transition: transform var(--menu) var(--ease-out), opacity var(--press) var(--ease-out); }
.menu-row.active .menu-caret { transform: translate3d(2px, 0, 0); opacity: 0.9; }

/* The switch in a connector row. Thumb travels; nothing else moves. */
.switch > span { transition: transform var(--pop) var(--ease-out); }

/* The side panel arriving. `panelIn` handles the column; this is the document
   inside it, which changes without the column changing. */
.artifact { animation: artifact-in 260ms var(--ease-out) both; }

@keyframes artifact-in {
  from { opacity: 0; transform: translate3d(0, 6px, 0); }
  to { opacity: 1; transform: none; }
}

/* The document switcher's caret, and the byte count that changes under it. */
.artifact-meta { transition: color var(--menu) var(--ease-out); }
.artifact-body { transition: border-color var(--menu) var(--ease-out); }

/* The composer's own controls. The mode toggle is the one place a filled
   selection moves between two positions, so it gets the same treatment the
   artifact tabs do -- but in CSS, since there are only ever two. */
.mode { transition: color var(--press) var(--ease-out), background var(--pop) var(--ease-out); }
.composer-chip-count { transition: color var(--press) var(--ease-out); }

/* The count on the + chip changes when a connector is switched. A short pulse
   is what says "that number is different now" without moving the row. */
.composer-chip-count { animation: count-pulse 320ms var(--ease-out); }

@keyframes count-pulse {
  0% { transform: scale(1); }
  40% { transform: scale(1.22); }
  100% { transform: scale(1); }
}

/* Attachment chips, which arrive one at a time as files upload. */
.file-chip { animation: pop-in var(--pop) var(--ease-out) both; }

/* The autocomplete list under the composer. */
.ac-menu { animation: menu-in var(--menu) var(--ease-out) both; }
.ac-item { transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out); }

@media (prefers-reduced-motion: reduce) {
  .artifact,
  .file-chip,
  .ac-menu,
  .composer-chip-count { animation: none; }
  .menu-row .menu-caret,
  .switch > span,
  .artifact-body { transition: none; }
}

/* ---------------------------------------------------------- turn trace */

/* What the agent did, one sentence per action. Replaces the stack of bordered
   tool cards that used to sit between a question and its answer -- no card, no
   badge, no border; a column of lines with an icon in the margin, which is what
   a list of actions actually is. */

/* `min-width: 0` on every level, all the way down.

   A grid or flex item defaults to `min-width: auto`, which means "never narrower
   than my contents". So a single 13,000-character `gh` command in an expanded
   trace pushed this whole chain wider than the window -- the chat column
   measured 13,809px against an 847px viewport, and the conversation scrolled
   sideways off the screen. The ellipsis on `.trace-subject` never engaged,
   because by the time it was asked to fit, its parent had already grown to
   accommodate the string.

   Nothing here can be dropped: the chain is `.stream-item > .msg > .trace >
   .trace-rows > .trace-row > .trace-line`, and one `auto` anywhere in it lets
   the content win again. */
.trace {
  display: grid;
  gap: 2px;
  min-width: 0;
  margin-bottom: var(--space-sm);
}

.trace-rows { display: grid; gap: 1px; min-width: 0; }

.trace-row { display: grid; min-width: 0; }
.trace-row-slot { min-width: 0; }

.trace-line {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  min-width: 0;
  padding: 4px 6px;
  margin-left: -6px;
  border-radius: var(--r-sm);
  text-align: left;
  font-size: var(--text-sm);
  color: var(--text-dim);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.trace-line--static { cursor: default; }

@media (hover: hover) and (pointer: fine) {
  .trace-line:hover { background: rgb(var(--tint) / 0.05); color: var(--text); }
}

.trace-icon { flex: none; color: var(--text-faint); }
.trace-row.is-error .trace-icon { color: var(--stop); }
.trace-label { flex: none; }

/* The object of the sentence -- a URL, a filename, a query. Mono because it is
   a machine string quoted inside prose, and it is the part that gives, since
   the verb is short and fixed and the object is neither. */
.trace-subject {
  /* The element that gives. `flex: 1` with a zero floor makes this the thing
     that shrinks when the row runs out of room, which is what the verb beside
     it can never be. */
  flex: 1 1 0;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-2xs);
  color: var(--text-faint);
}

.trace-live { color: var(--confirm); }

.trace-detail {
  display: grid;
  gap: var(--space-sm);
  margin: 2px 0 6px 22px;
  padding-left: var(--space-md);
  border-left: 1px solid var(--hairline);
}

.trace-detail-call { display: grid; gap: 4px; }

.trace-thought {
  font-size: var(--text-xs);
  line-height: 1.7;
  color: var(--text-faint);
  white-space: pre-wrap;
}
.trace-detail-name {
  font-size: var(--text-3xs);
  color: var(--text-faint);
}

.trace-json {
  max-height: 260px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  line-height: 1.6;
  color: var(--text-dim);
  white-space: pre-wrap;
  word-break: break-word;
}
.trace-json.is-error { color: var(--stop); background: var(--stop-soft); }

/* A document the turn produced. The one thing in a trace that is an outcome
   rather than a step, so it is the one thing that gets a box. */
.trace-artifact {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  max-width: 380px;
  padding: 10px 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--surface);
  text-align: left;
  transition: border-color var(--press) var(--ease-out), background var(--press) var(--ease-out),
              transform var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .trace-artifact:hover {
    border-color: var(--hairline-strong);
    background: var(--canvas);
    transform: translate3d(0, -1px, 0);
  }
  .trace-artifact:hover .trace-artifact-caret { transform: translate3d(2px, 0, 0); }
}

.trace-artifact.is-error { border-color: var(--stop-line); background: var(--stop-soft); }
.trace-artifact-icon { flex: none; color: var(--text-faint); }
.trace-artifact.is-error .trace-artifact-icon { color: var(--stop); }
.trace-artifact-text { flex: 1; min-width: 0; display: grid; gap: 1px; }

.trace-artifact-name {
  font-size: var(--text-sm);
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.trace-artifact-sub {
  font-family: var(--font-sans);
  font-size: 11.5px;
  color: var(--text-faint);
  line-height: 1.3;
}
.trace-artifact-caret {
  flex: none;
  color: var(--text-faint);
  transition: transform var(--press) var(--ease-out);
}

.trace-artifact-save {
  flex: none;
  padding: 3px 8px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-xs, 6px);
  font-family: var(--font-sans);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-dim);
  background: var(--surface-2);
  cursor: pointer;
  transition: color var(--press) var(--ease-out), border-color var(--press) var(--ease-out),
              background var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .trace-artifact-save:hover {
    color: var(--text);
    background: var(--surface-3);
    border-color: var(--hairline-strong);
  }
}
.trace-artifact-save:active { transform: scale(0.97); }

/* The folded form. A finished turn's machinery is one line you can open, not a
   column you scroll past. */
.trace-summary {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 3px 6px;
  margin-left: -6px;
  border-radius: var(--r-sm);
  font-size: var(--text-xs);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .trace-summary:hover { color: var(--text-dim); background: rgb(var(--tint) / 0.05); }
}

.trace-summary-caret { transition: transform var(--menu) var(--ease-out); }
.trace-summary-detail { font-family: var(--font-mono); font-size: var(--text-3xs); }

.trace-foot {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 3px 0 0 6px;
  margin-left: -6px;
  font-size: var(--text-xs);
  color: var(--text-faint);
}

/* Transform only, so the spinner costs nothing per frame. */
.trace-spin { animation: trace-spin 1.4s linear infinite; }
@keyframes trace-spin { to { transform: rotate(360deg); } }

.trace-fold {
  justify-self: start;
  padding: 3px 6px;
  margin-left: -6px;
  border-radius: var(--r-sm);
  font-size: var(--text-2xs);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out);
}
@media (hover: hover) and (pointer: fine) {
  .trace-fold:hover { color: var(--text-dim); }
}

@media (prefers-reduced-motion: reduce) {
  .trace-spin { animation: none; }
}

/* ------------------------------------------------------------- Worked pill & tool tree */
.trace-worked-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  margin: 6px 0 12px 0;
  width: 100%;
}

.trace-worked-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 12px;
  border-radius: 9999px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  font-size: var(--text-2xs);
  color: var(--text-dim);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease, opacity 0.15s ease, filter 0.15s ease;
  user-select: none;
}
.trace-worked-pill:hover {
  border-color: var(--hairline-strong);
  color: var(--text);
  background: rgb(var(--tint) / 0.08);
}

.trace-worked-icon {
  color: var(--text-faint);
}

.trace-worked-title {
  font-weight: 600;
  color: var(--text);
}

.trace-worked-sep {
  color: var(--text-faint);
  opacity: 0.7;
}

.trace-worked-stats {
  color: var(--text-faint);
}

.trace-worked-caret {
  color: var(--text-faint);
  transition: transform 0.2s ease;
  margin-left: 2px;
}
.trace-worked-caret.is-open {
  transform: rotate(180deg);
}

/* Tree container with SVG bracket on the left */
.trace-tree-container {
  position: relative;
  display: flex;
  width: 100%;
  margin-top: 6px;
  padding-left: 32px;
}

.trace-tree-bracket-svg {
  position: absolute;
  left: 14px;
  top: 0;
  bottom: 8px;
  width: 12px;
  height: calc(100% - 8px);
  color: rgb(var(--tint) / 0.2);
  pointer-events: none;
}

.trace-tree-items {
  display: flex;
  flex-direction: column;
  gap: 3px;
  width: 100%;
  min-width: 0;
}

/* Tool execution item */
.trace-item {
  display: flex;
  flex-direction: column;
  width: 100%;
  min-width: 0;
}

.trace-item-line {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 5px 8px;
  border-radius: var(--r-sm);
  background: transparent;
  border: none;
  font-size: var(--text-xs);
  color: var(--text-dim);
  cursor: pointer;
  text-align: left;
  transition: background 0.12s ease;
}
.trace-item-line:hover {
  background: rgb(var(--tint) / 0.05);
}

.trace-item-line--static {
  cursor: default;
}

.trace-tool-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 65px;
  flex: none;
  font-size: var(--text-xs);
  font-weight: 500;
  color: var(--text);
}

.trace-tool-icon {
  color: var(--text-faint);
}

.trace-tool-subject {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  color: var(--text-faint);
}

.trace-tool-meta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-left: auto;
  flex: none;
}

.trace-tool-count {
  font-size: var(--text-2xs);
  color: var(--text-faint);
}

.trace-tool-chevron {
  color: var(--text-faint);
  transition: transform 0.18s ease;
}
.trace-tool-chevron.is-open {
  transform: rotate(90deg);
}

/* Inset JSON Card */
.trace-item-fold {
  padding: 4px 0 8px 0;
  width: 100%;
}

.trace-inset-card {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  padding: 14px 18px;
  max-height: 280px;
  overflow: auto;
}

.trace-inset-card pre.trace-json {
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  line-height: 1.55;
  color: var(--text-dim);
}

/* Latest badge inside inset card (Screenshot 2) */
.trace-latest-badge {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 9999px;
  background: rgb(var(--tint) / 0.08);
  border: 1px solid var(--hairline);
  font-size: 11px;
  font-weight: 500;
  color: var(--text-dim);
  letter-spacing: 0.01em;
}

/* ------------------------------------------------------------ tool card */

.tool-card { border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface); }

.tool-card-head {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 9px 13px;
  font-size: var(--text-xs);
  color: var(--text-dim);
  transition: background var(--press) var(--ease-out);
}

.tool-card-head:hover { background: rgb(var(--tint) / 0.03); }
.tool-card-head svg { opacity: 0.55; transition: transform var(--pop) var(--ease-out); }
/* A tool name is a callable identifier, not a label -- same face as the file
   paths and model ids it sits between. */
.tool-name { font-family: var(--font-mono); font-size: var(--text-2xs); color: var(--text); }
.tool-card-head .badge { margin-left: auto; }

/* Height without animating height: the grid track does the work. */
.tool-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows var(--menu) var(--ease-out); }
.tool-body.open { grid-template-rows: 1fr; }
.tool-body > div { overflow: hidden; min-height: 0; }

.tool-block { display: grid; gap: 6px; padding: 2px 13px 12px; }

.tool-block-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-xs);
  color: var(--text-faint);
}

.tool-json {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas-deep);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.6;
  color: var(--text-dim);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 300px;
  overflow-y: auto;
}

.tool-json--error {
  color: rgba(255, 90, 90, 0.9);
  background: rgba(255, 90, 90, 0.05);
  border-color: rgba(255, 90, 90, 0.15);
}

.tool-result--error { color: var(--stop); }

.model-strip {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 24px;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-faint);
  flex-wrap: wrap;
}

/* --------------------------------------------------------------- lists */

.server-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 16px;
  border-radius: var(--r-lg);
  flex-wrap: wrap;
  transition: background var(--press) var(--ease-out);
}

.server-row:hover { background: rgb(var(--tint) / 0.02); }
.server-row > .led { margin-top: 7px; }
.server-row > div:nth-child(2) { flex: 1; min-width: 0; }
.server-name { font-size: 14px; color: var(--text); }
.server-target { font-family: var(--font-mono); font-size: 10.5px; color: var(--text-faint); margin-top: 3px; overflow-wrap: anywhere; }
.server-actions { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }

/* Memory facts: a list, not a set of padded rows. The fact is the whole
   content of the row — 14px of padding per fact on a page of forty of them
   was more wall than list, and the Forget buttons drifted out of any column.
   Hairline-separated, one line of breathing room per fact. */
.mem-facts .server-row {
  align-items: flex-start;
  gap: 14px;
  padding: 10px 6px;
  border-radius: 0;
  border-top: 1px solid var(--hairline);
}

.mem-facts .server-row:first-of-type { border-top: 0; }

.mem-facts .server-name {
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
}

.mem-facts .server-target { font-size: var(--text-2xs); margin-top: 4px; }

/* ------------------------------------------------- sign-in status cards

   One card per sign-in, in whatever state it is actually in. This used to be a
   single amber strip listing every "waiting" flow as a link, which was wrong in
   two ways: it offered links whose state had expired -- clicking one produced
   the provider's "Invalid or expired OAuth state parameter" -- and it had
   nothing to say about a sign-in that finished, failed, or was cancelled.

   The accent is the state, so the colour is never decoration: amber is waiting
   on you, green landed, red needs another go. */

.auth-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 20px;
}

.auth-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 15px;
  border: 1px solid var(--hairline);
  border-left: 2px solid var(--accent);
  border-radius: var(--r-lg);
  background: var(--surface);
  font-size: 13px;
  color: var(--text-dim);
  animation: auth-in var(--pop) var(--ease-out) both;
}

@keyframes auth-in {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .auth-banner { animation: none; }
}

.auth-banner--waiting   { --accent: var(--confirm); --tint: var(--confirm-soft); }
.auth-banner--done      { --accent: var(--live);    --tint: var(--live-soft); }
.auth-banner--failed,
.auth-banner--expired   { --accent: var(--stop);    --tint: var(--stop-soft); }
.auth-banner--cancelled { --accent: var(--text-faint); --tint: rgb(var(--tint) / 0.03); }

/* Fixed box so a spinner swapping for a tick cannot shift the text beside it. */
.auth-banner-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  color: var(--accent);
}

.auth-banner-body { min-width: 0; flex: 1; }

.auth-banner-title {
  color: var(--text);
  font-weight: 500;
  letter-spacing: -0.005em;
}

.auth-banner-note {
  margin-top: 2px;
  color: var(--text-dim);
  font-size: 12.5px;
  line-height: 1.45;
  overflow-wrap: anywhere;
  /* A provider's own guidance arrives as several lines -- GitHub's "register an
     app once" is five -- so the breaks it was written with are kept. */
  white-space: pre-wrap;
}

/* The device code, which the user has to reproduce by hand at the provider.
   Monospaced and spaced out because a code is read character by character, and
   `1`/`l` and `0`/`O` are exactly where that goes wrong. */
.auth-code {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
  padding: 7px 11px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  color: var(--text);
  cursor: pointer;
  transition: border-color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}

.auth-code:hover { border-color: var(--accent); background: var(--surface); }
.auth-code:focus-visible { outline: none; box-shadow: var(--focus); }

.auth-code-value {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.16em;
  /* The trailing letter-space would otherwise sit inside the border. */
  margin-right: -0.16em;
}

.auth-banner-meta {
  color: var(--text-faint);
  font-variant-numeric: tabular-nums;
}

.auth-banner-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.auth-spinner {
  width: 13px;
  height: 13px;
  border: 1.5px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: auth-spin 720ms linear infinite;
}

@keyframes auth-spin { to { transform: rotate(360deg); } }

@media (prefers-reduced-motion: reduce) {
  .auth-spinner { animation-duration: 2.4s; }
}

/* Below this the actions cannot sit beside the text without truncating it. */
@media (max-width: 560px) {
  .auth-banner { flex-wrap: wrap; }
  .auth-banner-body { flex-basis: 100%; }
  .auth-banner-actions { width: 100%; }
  .auth-banner-actions .btn { flex: 1; justify-content: center; }
}

/* ----------------------------------------------------------- mcp tiles */

.mcp-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(258px, 1fr)); gap: 12px; }

/* Shadow lives on a pseudo-element so hover only animates its opacity. */
.mcp-tile, .skill-card, .module-row, .stat {
  position: relative;
  isolation: isolate;
}

.mcp-tile::after, .skill-card::after, .module-row::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  box-shadow: 0 14px 30px -20px rgb(var(--shade) / 0.9);
  opacity: 0;
  transition: opacity var(--menu) var(--ease-out);
  pointer-events: none;
  z-index: -1;
}

@media (hover: hover) and (pointer: fine) {
  .mcp-tile:hover::after, .skill-card:hover::after, .module-row:hover::after { opacity: 1; }
}

.mcp-tile {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 20px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-xl);
  background: var(--surface);
  transition: border-color var(--menu) var(--ease-out), transform var(--menu) var(--ease-out), background-color var(--menu) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .mcp-tile:hover { border-color: var(--hairline-strong); transform: translate3d(0, -2px, 0); }
}

.mcp-tile-head { display: flex; align-items: center; gap: 9px; }
.mcp-tile-title { font-size: 14.5px; }
.mcp-tile-desc { font-size: 12.5px; color: var(--text-faint); line-height: 1.6; }
.mcp-tile-meta { display: flex; flex-wrap: wrap; gap: 5px; }
.mcp-tile-foot { display: flex; align-items: center; gap: 11px; margin-top: auto; padding-top: 4px; }

.mcp-tile-home {
  margin-left: auto;
  font-size: var(--text-2xs);
  color: var(--text-faint);
  text-decoration: none;
  border-bottom: 1px solid var(--hairline);
  transition: color var(--press) var(--ease-out);
}
.mcp-tile-home:hover { color: var(--text); }

.skill-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(270px, 1fr)); gap: 12px; }

.skill-card {
  display: grid;
  gap: 8px;
  padding: 20px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-xl);
  background: var(--surface);
  transition: border-color var(--menu) var(--ease-out), transform var(--menu) var(--ease-out), background-color var(--menu) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .skill-card:hover { border-color: var(--hairline-strong); transform: translate3d(0, -2px, 0); }
}

.skill-name { display: flex; align-items: center; gap: 8px; font-size: 14.5px; }
.skill-desc { font-size: 12.5px; color: var(--text-faint); line-height: 1.6; }
.skill-path { font-family: var(--font-mono); font-size: 10px; color: var(--text-faint); overflow-wrap: anywhere; }

/* --------------------------------------------------------------- stats */

.dash-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; align-items: start; }

@media (max-width: 860px) { .dash-grid { grid-template-columns: 1fr; } }

.stat-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }

@media (max-width: 480px) { .stat-grid { grid-template-columns: 1fr; } }

.stat { padding: 20px; border: 1px solid var(--hairline); border-radius: var(--r-xl); background: var(--surface); transition: background-color var(--menu) var(--ease-out), border-color var(--menu) var(--ease-out), color var(--menu) var(--ease-out); }

.stat-num {
  font-family: var(--font-display);
  font-size: clamp(24px, 4vw, 36px);
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: var(--text-xs);
  color: var(--text-faint);
  margin-top: 11px;
}

.stat-sub { display: flex; align-items: center; gap: 6px; margin-top: 7px; font-size: 12px; color: var(--text-faint); }

.tele { border: 1px solid var(--hairline); border-radius: var(--r-lg); background: var(--surface); overflow: hidden; transition: background-color var(--menu) var(--ease-out), border-color var(--menu) var(--ease-out); }

.tele-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 15px;
  border-bottom: 1px solid var(--hairline);
  font-size: var(--text-xs);
  color: var(--text-faint);
}

.tele-body { padding: 14px; overflow-x: auto; font-family: var(--font-mono); font-size: 11.5px; color: var(--text-dim); }
.tele-line { white-space: pre-wrap; word-break: break-word; line-height: 1.9; }
.tele-line .t-time { color: var(--text-faint); }
.tele-line .t-tag { color: var(--text); }
.tele-line .t-tag-ok { color: var(--live); }
.tele-line .t-tag-bad { color: var(--stop); }
.tele-line .t-tag-info { color: var(--text-dim); }

.dash-tiers { margin-top: 18px; }

.dash-modules { display: grid; gap: 6px; margin-top: 22px; }

.module-row {
  display: flex;
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 16px 18px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: rgb(var(--tint) / 0.01);
  text-align: left;
  transition: border-color var(--menu) var(--ease-out), transform var(--menu) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .module-row:hover { border-color: var(--hairline-strong); transform: translate3d(2px, 0, 0); }
}
.module-row:active { transform: scale(0.995); }

.module-icon {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: var(--r-sm);
  border: 1px solid var(--hairline);
  color: var(--text-dim);
  flex: none;
}

.module-name { font-size: 14px; }
.module-desc { font-size: 12.5px; color: var(--text-faint); margin-top: 2px; }
.module-meta { margin-left: auto; font-size: var(--text-2xs); color: var(--text-faint); flex: none; }

@media (max-width: 640px) { .module-meta { display: none; } }

/* ----------------------------------------------------------------- logs */

.log-table { width: 100%; border-collapse: collapse; font-size: 12.5px; }

.log-table th {
  text-align: left;
  padding: 10px 11px;
  border-bottom: 1px solid var(--hairline-strong);
  font-size: var(--text-xs);
  color: var(--text-dim);
  font-weight: 500;
}

.log-table td { padding: 10px 11px; border-bottom: 1px solid var(--hairline); color: var(--text-dim); vertical-align: top; }
.log-table tr:hover td { background: rgb(var(--tint) / 0.018); }

/* Two lines, then ellipsis. A single long argument used to stretch its row to
   several hundred pixels, which made the table unscannable — the one thing an
   audit log has to be. The full value stays in the title attribute. */
.log-args, .log-result {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  line-height: 1.5;
  color: var(--text-faint);
  max-width: 100%;
  overflow-wrap: anywhere;
}

.log-table { table-layout: fixed; }
.log-table th:nth-child(1) { width: 74px; }
.log-table th:nth-child(2) { width: 23%; }
.log-table th:nth-child(3) { width: 62px; }
.log-table th:nth-child(4) { width: 82px; }
.log-table th:nth-child(5) { width: 116px; }
.log-table th:nth-child(6) { width: 52px; }
.log-table th:nth-child(7) { width: 21%; }
.log-table th:nth-child(8) { width: 21%; }
.log-table td { overflow: hidden; }

/* A long composite tool key must not run into the next column. */
.log-tool {
  font-family: var(--font-mono);
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.log-result--error { color: var(--stop); }
.log-when { white-space: nowrap; color: var(--text-faint); }
.log-dim { color: var(--text-faint); }
.log-decision { color: var(--text-dim); }
.log-denied { color: var(--stop); }

/* The table scrolls inside its own card. `max-height` rather than letting the
   page grow: the header and the lenses have to stay reachable while reading
   five hundred rows. */
.log-table-wrap { overflow: auto; max-height: calc(100vh - 300px); }

/* ---- the log, below the breakpoint ---------------------------------------

   Eight columns do not survive a phone, and a table that scrolls sideways is a
   table nobody reads the right-hand half of. Same fields, stacked, with the
   two that carry the judgement — risk and decision — on the lines the eye
   reaches first. */

.log-cards { display: grid; gap: var(--space-sm); }

.log-card {
  padding: var(--space-md) var(--space-md) var(--space-sm);
  border: 1px solid var(--hairline);
  border-left: 2px solid var(--hairline-strong);
  border-radius: var(--r-lg);
  background: var(--raised);
}

.log-card--failed { border-left-color: var(--stop); }

.log-card-head {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  width: 100%;
  text-align: left;
}

.log-card-tool {
  flex: 1;
  min-width: 0;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  color: var(--text);
  overflow-wrap: anywhere;
}

.log-card-caret { flex: none; color: var(--text-faint); transition: transform var(--pop) var(--ease-out); }
.log-card-head[aria-expanded='true'] .log-card-caret { transform: rotate(90deg); }

.log-card-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-sm);
  margin-top: var(--space-xs);
  font-size: var(--text-2xs);
  color: var(--text-faint);
}
.log-card-meta > span + span::before { content: '·'; margin-right: var(--space-sm); }

/* Three lines, then ellipsis — the same rule the table's cells follow, for the
   same reason: one tool that returned six hundred words of page text must not
   be the only row on the screen. Expanding the card shows the arguments; the
   result in full is a desk-sized question. */
.log-card-result {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-top: var(--space-xs);
  font-size: var(--text-xs);
  line-height: var(--leading-normal);
  color: var(--text-dim);
  overflow-wrap: anywhere;
}

.log-card[data-open='true'] .log-card-result {
  -webkit-line-clamp: unset;
  line-clamp: unset;
  max-height: 40vh;
  overflow: auto;
}

.log-card-args { margin-top: var(--space-sm); display: grid; gap: var(--space-xs); justify-items: start; }
.log-card-args .tool-json { max-height: 220px; overflow: auto; }

.log-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-lg);
}
.log-count { font-size: var(--text-2xs); color: var(--text-faint); margin-left: auto; }

.log-lenses {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  margin-bottom: var(--space-md);
}

/* ---- two controls the whole application can reuse ----------------------- */

/* A filter that says what it filters, instead of a bare box with placeholder
   text. Used by the log; the other views' hand-styled inputs should move to
   it rather than each inventing its own padding again. */
.inline-search {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  flex: 1 1 220px;
  min-width: 0;
  max-width: 340px;
  padding: 0 var(--space-sm);
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  color: var(--text-faint);
  transition: border-color var(--pop) var(--ease-out);
}
.inline-search:focus-within { border-color: var(--hairline-strong); }
.inline-search input {
  flex: 1;
  min-width: 0;
  padding: 7px 0;
  border: none;
  background: none;
  outline: none;
  color: var(--text);
  font-size: var(--text-sm);
}
.inline-search input::placeholder { color: var(--text-faint); }
.inline-search .icon-btn { width: 20px; height: 20px; min-width: 20px; min-height: 20px; }

.inline-select {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: var(--text-xs);
  color: var(--text-faint);
}
.inline-select select {
  padding: 6px 8px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  color: var(--text-dim);
  font-size: var(--text-xs);
  letter-spacing: 0;
  text-transform: none;
}

/* A toggle that reads as a filter rather than as a button: pressed is a state
   you are in, not an action you took. */
.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 6px 11px;
  border: 1px solid transparent;
  border-radius: var(--r-sm);
  background: rgb(148 151 169 / 0.1);
  font-size: var(--text-xs);
  font-weight: 500;
  color: var(--text-dim);
  transition: color var(--press) var(--ease-out), border-color var(--press) var(--ease-out),
              background-color var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .chip:hover { color: var(--text); background: rgb(148 151 169 / 0.18); }
}

/* On is the brand at 16%, which is Kraken's own subtle-button fill. The old
   "on" was a 7% grey wash on a grey chip -- a four-percent difference, which
   is to say a filter you could not tell was applied. */
.chip.is-on {
  color: var(--accent);
  border-color: transparent;
  background: var(--accent-soft);
}

.chip-count {
  font-size: var(--text-2xs);
  color: var(--text-faint);
}
.chip.is-on .chip-count { color: var(--accent); opacity: 0.75; }

/* --------------------------------------------------------- entrances
   Set by motion.js on mount; the animation itself never touches JS. */

[data-enter].enter {
  opacity: 0;
  animation: rise 380ms var(--ease-out) forwards;
  /* Capped; see the note on .damon-web-item. */
  animation-delay: min(calc(var(--i, 0) * 40ms), 240ms);
}

.view-swap { animation: swap 220ms var(--ease-out); }

/* Defined once, next to the only selector that plays it. A second
   `@keyframes swap` used to sit at the end of the file and silently win on
   source order, so the distance written here was never the distance the view
   actually travelled. */
@keyframes swap {
  from { opacity: 0; transform: translate3d(0, 4px, 0) scale(0.997); }
}

/* Reduced motion means gentler, not absent: opacity stays, movement goes. */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  .hero > *, [data-enter].enter { opacity: 1; transform: none; }
}

/* ------------------------------------------------------------- keyboard */

.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border: 1px solid var(--hairline);
  border-bottom: 2px solid var(--hairline-strong);
  border-radius: var(--r-sm);
  background: linear-gradient(180deg, rgb(var(--tint) / 0.05), rgb(var(--tint) / 0.02));
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  line-height: 1;
  color: var(--text-dim);
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: var(--r-pill);
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .icon-btn:hover { color: var(--text); background: rgb(var(--tint) / 0.05); }
}
.icon-btn:active { transform: scale(0.94); }

/* Chat stays mounted while another view is on screen, so a turn in flight is
   not torn down by navigating away from it. */
.wb-main > .main:not(.main--hidden) {
  animation: mainFadeIn 0.2s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes mainFadeIn {
  from {
    opacity: 0;
    transform: translate3d(0, 3px, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

.wb-main > .main.main--hidden,
.main--hidden { display: none !important; }

/* --------------------------------------------- inside AMETHYST's own window */

/* One rule, and it buys back every frame the blurs were costing.

   Scoped to `[data-native]` so a browser tab keeps the design as drawn: this is
   a concession to one renderer, not a change of mind about how it should look.
   The surfaces underneath already carry their own background colour, so they
   stay legible -- they simply stop sampling everything behind them 60 times a
   second. */
[data-native] .modal-overlay,
[data-native] .toast,
[data-native] .plus-menu,
[data-native] .ac-menu,
[data-native] .rail-peek,
[data-native] .rail-scrim,
[data-native] [class*="-backdrop"],
[data-native] [class*="-popover"],
[data-native] [class*="-menu"] {
  backdrop-filter: none;
}

/* The bar is a frameless window of its own. The card inside paints its own
   rounded corners, and the window's ground (set from `create_window`) is the
   same tone as the card's surface, so the corners read as the card's edge
   rather than as the window showing through. 10px of margin keeps the corner
   arcs off the window's own edges; `easy_drag` still works anywhere on the
   card, and the empty margin is not a dead zone for it because dragging the
   band drags nothing -- the window is the drag target. */
/* `.palette.palette--bar` below is two classes; this was `[data-native]
   .palette--bar`, which is also two. Equal specificity is decided by source
   order, and that rule comes later -- so for the whole life of this file the
   native window took *its* width, height and radius and this block's `margin`.
   100% width with a 12px margin on each side is 24px wider than the window,
   which is exactly the horizontal scrollbar nobody could place; 100vh with a
   12px margin top and bottom is the vertical one; and the 20px radius below
   was never the radius, the 14px one was.

   One class more, so it wins outright rather than by being further down. */
[data-native] .palette.palette--bar {
  margin: 12px;
  /* Deliberately not `calc(100% - 24px)`: `inset: 0` with a margin lets the
     box work its own size out from the window, so there is no arithmetic here
     to disagree with the margin if either changes. */
  width: auto;
  height: auto;
  inset: 0;
  position: fixed;
  max-width: none;
  max-height: none;
  /* A radius this size on a window this size is what a floating card looks
     like on every modern desktop: the corner arc is visible at a glance, not
     something to squint for. On Wayland the window behind it is transparent,
     so this arc is the whole silhouette -- there is no band and no square
     ground for it to be cut out of. */
  border-radius: 22px;
  background: var(--raised);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: 0 24px 64px -12px rgb(0 0 0 / 0.45), 0 0 0 1px rgb(255 255 255 / 0.06);
  border-color: transparent;
}

/* ------------------------------------------------------- command palette */

/* The floating bar is its own frameless window, so the card *is* the page --
   full bleed, and its corners are the window's corners.

   Compound on purpose: `.palette` below sets width and max-height, and a
   same-specificity selector that appears earlier in the file loses to it --
   which is how the bar opened as a 640px card floating in the corner of its
   own 760px window, with the window's ground showing on two sides of it. */
.palette.palette--bar {
  width: 100%;
  max-width: none;
  height: 100vh;
  max-height: none;
  border-radius: 14px;
}

/* The page paints nothing behind the card; the *window* is the ground, and
   what that means depends on the display server (`_corners_are_free` in
   backend/desktop.py has the why).

   On Wayland the window is transparent, so there is nothing behind the card
   at all and its rounded silhouette is the window's own edge -- true corners,
   the way every spotlight on the machine looks. On X11 the window stays
   opaque, because an RGBA visual there costs WebKitGTK its accelerated
   compositing path, and its `background_color` paints the same dark band this
   rule used to paint in CSS.

   One rule for both: painting a ground here would put a squared-off blob
   behind the card on the very platform that had just been given real corners. */
html:has(.palette--bar) body {
  background: transparent;
}

/* Nothing in a spotlight window scrolls. It is a fixed-size card in a
   fixed-size window, so a scrollbar there is always a layout mistake showing
   through rather than content a person wants to reach -- the list inside the
   card does its own scrolling, and that is the only scrolling there should be.
   Stated on both elements because either one can be the scroll container. */
html:has(.palette--bar),
html:has(.palette--bar) body {
  overflow: hidden;
  overscroll-behavior: none;
}

/* The bar's own scale. These sizes were tuned for the palette over a browser
   page at full width; alone in a small frameless window the same numbers read
   as a tooltip -- rows too small to hit, hints too small to read. Everything
   that was 13.5px-class grows one step, and the rows get the padding to make
   each a real target. */
.palette--bar .palette-input { padding: 16px 18px; }
.palette--bar .palette-input input { font-size: 16.5px; }
/* Said once, above the results, and only when the search fell through to
   Wikipedia with no provider configured. Quiet on purpose: it is an
   explanation, not an error -- the results below it are real and usable.

   The comment used to sit between `.palette--bar` and this selector, which is
   not a comment in a selector list -- it is whitespace. The rule silently
   became `.palette--bar .damon-mixed-note`, so the one sentence explaining why
   the results are encyclopaedia articles was invisible in the in-app palette,
   which is exactly where people were left wondering. */
.damon-mixed-note {
  margin: 0 0 8px;
  padding: 7px 10px;
  border-radius: 10px;
  background: rgb(var(--tint) / 0.07);
  color: var(--text-faint);
  font-size: 12px;
  line-height: 1.45;
}

.palette-list { padding: 8px; }
.palette--bar .palette-group { padding: 12px 12px 5px; }
.palette--bar .palette-item { padding: 11px 12px; gap: 12px; }
.palette--bar .palette-label { font-size: var(--text-md); }
.palette--bar .palette-hint { font-size: 12.5px; margin-top: 3px; }
.palette--bar .palette-empty { font-size: var(--text-md); padding: 30px 16px; }
.palette--bar .palette-flash { font-size: 12.5px; }

.palette-flash {
  flex: none;
  font-size: 12px;
  color: var(--text-faint);
  white-space: nowrap;
}

.palette-overlay { align-items: flex-start; padding-top: 10vh; }
.damon-overlay {
  backdrop-filter: blur(16px);
  background: color-mix(in srgb, var(--scrim) 85%, transparent);
  animation: damon-fade 100ms ease-out forwards;
}

/* Same clock as the card: the scrim leaves with the card, not after it. */
.damon-overlay[data-closing] {
  animation: damon-fade-out 80ms ease-out forwards;
  pointer-events: none;
}

@keyframes damon-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes damon-spring-in {
  0% {
    opacity: 0;
    filter: blur(16px);
    transform: scale(0.96) translateY(-10px);
  }
  100% {
    opacity: 1;
    filter: blur(0px);
    transform: scale(1) translateY(0);
  }
}

.palette {
  width: min(680px, calc(100vw - 32px));
  max-height: min(640px, 82vh);
  display: flex;
  flex-direction: column;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-xl, 16px);
  background: color-mix(in srgb, var(--raised) 92%, transparent);
  backdrop-filter: blur(28px) saturate(180%);
  -webkit-backdrop-filter: blur(28px) saturate(180%);
  box-shadow: var(--lift);
  overflow: hidden;
  animation: damon-spring-in 180ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  transform-origin: top center;
}

/* Going out is faster than coming in: 80ms, opacity only. The spring is for
   arrival — the thing the user is waiting on — and the exit should be out of
   the way before they have looked back at the page behind it. Nothing scales
   on the way out; shrinking away is the one animation that reads as a
   mistake on a card this large.
   
   Both halves were cut by a third. A spotlight is summoned mid-thought and the
   animation is pure cost between the keystroke and the cursor: long enough to
   read as motion rather than a jump, short enough not to be waited on. */
.palette[data-closing] {
  animation: damon-fade-out 100ms cubic-bezier(0.23, 1, 0.32, 1) forwards;
  pointer-events: none;
}

@keyframes damon-fade-out {
  0% {
    opacity: 1;
    filter: blur(0px);
    transform: scale(1) translateY(0);
  }
  100% {
    opacity: 0;
    filter: blur(12px);
    transform: scale(0.98) translateY(6px);
  }
}

.palette-input {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 20px;
  border-bottom: 1px solid var(--hairline);
  color: var(--text-faint);
  background: transparent;
}

.damon-header {
  position: relative;
  z-index: 2;
}

.damon-input-leading {
  display: flex;
  align-items: center;
  flex: none;
}

.damon-search-icon {
  color: var(--text-faint);
  transition: color 140ms ease;
}

.palette-input:focus-within .damon-search-icon {
  color: var(--accent);
}

.damon-badge-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px;
  border-radius: var(--r-pill);
  font-size: 12px;
  font-weight: 500;
  border: 1px solid transparent;
  cursor: pointer;
  transition: opacity 120ms ease;
}
.damon-badge-tag:hover { opacity: 0.85; }
.damon-badge-tag--yt { background: #fee2e2; color: #dc2626; border-color: #fca5a5; }
.damon-badge-tag--web { background: #e0e7ff; color: #4338ca; border-color: #c7d2fe; }
.damon-badge-tag--img { background: #f3e8ff; color: #7e22ce; border-color: #e9d5ff; }
.damon-badge-tag--cmd { background: #fef3c7; color: #b45309; border-color: #fde68a; }
.damon-badge-tag--lib { background: #ecfdf5; color: #047857; border-color: #a7f3d0; }
.damon-badge-tag--task { background: #e0f2fe; color: #0369a1; border-color: #bae6fd; }
.damon-badge-tag--gh { background: #f1f5f9; color: #334155; border-color: #cbd5e1; }

[data-theme="dark"] .damon-badge-tag--yt { background: rgba(220, 38, 38, 0.2); color: #f87171; border-color: rgba(220, 38, 38, 0.35); }
[data-theme="dark"] .damon-badge-tag--web { background: rgba(99, 102, 241, 0.2); color: #a5b4fc; border-color: rgba(99, 102, 241, 0.35); }
[data-theme="dark"] .damon-badge-tag--img { background: rgba(168, 85, 247, 0.2); color: #d8b4fe; border-color: rgba(168, 85, 247, 0.35); }
[data-theme="dark"] .damon-badge-tag--cmd { background: rgba(217, 119, 6, 0.2); color: #fcd34d; border-color: rgba(217, 119, 6, 0.35); }
[data-theme="dark"] .damon-badge-tag--lib { background: rgba(16, 185, 129, 0.2); color: #6ee7b7; border-color: rgba(16, 185, 129, 0.35); }
[data-theme="dark"] .damon-badge-tag--task { background: rgba(14, 165, 233, 0.2); color: #7dd3fc; border-color: rgba(14, 165, 233, 0.35); }
[data-theme="dark"] .damon-badge-tag--gh { background: rgba(148, 163, 184, 0.2); color: #cbd5e1; border-color: rgba(148, 163, 184, 0.35); }

.palette-input input {
  flex: 1;
  min-width: 0;
  background: none;
  border: none;
  outline: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.4;
}

.palette-input input::placeholder { color: var(--text-faint); }

.damon-header-trailing {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: none;
}

.damon-clear-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: var(--r-pill);
  color: var(--text-faint);
  border: none;
  background: transparent;
  cursor: pointer;
  transition: color var(--press) var(--ease-out), background-color var(--press) var(--ease-out);
}
.damon-clear-btn:hover { background: var(--surface-hover); color: var(--text); }

.damon-flash {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--accent);
  background: var(--accent-wash);
  padding: 3px 8px;
  border-radius: var(--r-sm);
  border: 1px solid var(--accent-line);
}

/* Mode Filter Pills */
.damon-modes {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--hairline);
  background: color-mix(in srgb, var(--surface-2) 75%, transparent);
  overflow-x: auto;
  scrollbar-width: none;
}
.damon-modes::-webkit-scrollbar { display: none; }

.damon-mode-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: var(--r-pill);
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-dim);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition: color var(--press) var(--ease-out), background-color var(--press) var(--ease-out), border-color var(--press) var(--ease-out);
}
.damon-mode-pill:hover { background: var(--surface-3); color: var(--text); }
.damon-mode-pill.is-active {
  background: var(--raised);
  color: var(--accent);
  border-color: var(--hairline);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06);
}
.damon-mode-pill:active { transform: scale(0.96); }

/* Mode switches fade into the new list: the container is re-keyed per mode,
   so this plays once on every switch, a short opacity rise that makes the
   change feel like a page turning rather than a repaint. */
.damon-list-swap { animation: damon-rise 180ms var(--ease-out); }

/* Content List Container */
.palette-list {
  flex: 1;
  overflow-y: auto;
  padding: 10px;
}

/* A scrollbar riding the card's rounded edge is the first thing the eye
   meets in the spotlight, and a 9px gutter with a permanent thumb is a
   frame around the content. The overlay-scroll treatment instead: no
   gutter, a thin thumb that exists only while the pointer is over the
   list, and nothing at all otherwise. Both palettes get it, so the bar and
   the browser overlay feel like one thing. */
.palette-list {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.palette-list::-webkit-scrollbar { width: 6px; background: transparent; }
.palette-list::-webkit-scrollbar-thumb {
  border-radius: 9999px;
  background: transparent;
  transition: background 160ms ease-out;
}
.palette-list:hover { scrollbar-color: rgb(var(--tint) / 0.18) transparent; }
.palette-list:hover::-webkit-scrollbar-thumb { background: rgb(var(--tint) / 0.18); }

.palette-group {
  padding: 10px 10px 4px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-faint);
}

.palette-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 14px;
  border-radius: var(--r-md);
  text-align: left;
  color: var(--text);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: background 100ms ease;
}

.palette-item:hover,
.palette-item.active {
  background: var(--surface-hover);
  color: var(--text);
}

.palette-label {
  flex: 1;
  min-width: 0;
  font-size: 14px;
  font-weight: 500;
}

.palette-hint {
  display: block;
  margin-top: 2px;
  font-size: 12px;
  font-weight: 400;
  color: var(--text-dim);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.palette-keys { display: flex; gap: 4px; flex: none; }

/* Empty & Loading States */
.damon-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  text-align: center;
  color: var(--text-dim);
  gap: 8px;
}
.damon-empty-state p { margin: 0; font-size: 14px; font-weight: 500; color: var(--text); }
.damon-empty-hint { font-size: 12px; color: var(--text-faint); }
.damon-empty-hint code {
  background: var(--surface-2);
  padding: 2px 5px;
  border-radius: var(--r-xs);
  border: 1px solid var(--hairline);
  font-family: var(--font-mono);
}

.damon-loading-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 48px 20px;
  color: var(--text-dim);
  font-size: 13.5px;
}

/* The infinite-scroll sentinel row: a quiet "loading more" strip at the foot of
   a result list. Full width even inside the YouTube grid. */
.damon-load-more {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  min-height: 24px;
  color: var(--text-dim);
  font-size: 12.5px;
}

.damon-spinner {
  width: 18px;
  height: 18px;
  border: 2px solid var(--hairline-strong);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: damon-spin 0.6s linear infinite;
}
@keyframes damon-spin {
  to { transform: rotate(360deg); }
}

.damon-fallback-actions {
  margin-top: 8px;
}

.damon-primary-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: var(--r-pill);
  background: var(--accent);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(113, 50, 245, 0.28);
  transition: transform 120ms ease, opacity 120ms ease;
}
.damon-primary-action-btn:hover {
  opacity: 0.92;
  transform: translateY(-1px);
}

/* Web Results Layout */
.damon-web-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

/* The answer card sits above the article list: one held thought — kicker,
   two-to-four sentences, the domains that backed it — inside a wash of the
   brand colour so it reads as the point of the page rather than one more
   result. */
/* One row per kind of evidence under a universal-mode answer: a strip of
   three web links, two videos, a contact sheet of image thumbs. Each strip
   is headed by its kind and a quiet way to open the full grid for it, and
   each enters a beat after the one above it, so the answer lands first and
   the evidence cascades in behind it. */
.damon-mixed {
  display: grid;
  gap: 4px;
  padding: 2px 8px 8px;
}

.damon-mixed-row {
  display: grid;
  gap: 4px;
  opacity: 0;
  animation: damon-rise 240ms var(--ease-out) forwards;
}
.damon-mixed-row[data-kind="web"] { animation-delay: 40ms; }
.damon-mixed-row[data-kind="youtube"] { animation-delay: 90ms; }
.damon-mixed-row[data-kind="images"] { animation-delay: 140ms; }

@keyframes damon-rise {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

.damon-mixed-head {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 4px 6px;
  color: var(--text-faint);
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.damon-mixed-head svg { color: var(--text-dim); }

.damon-mixed-head button {
  margin-left: auto;
  border: 0;
  padding: 2px 6px;
  background: none;
  color: var(--text-faint);
  font: inherit;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
  cursor: pointer;
  border-radius: var(--r-xs);
  transition: color var(--press) var(--ease-out), background-color var(--press) var(--ease-out);
}
@media (hover: hover) and (pointer: fine) {
  .damon-mixed-head button:hover { color: var(--text); background: rgb(var(--tint) / 0.05); }
}

.damon-mixed-row ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }

.damon-mixed-row li button {
  display: flex;
  align-items: baseline;
  gap: 10px;
  width: 100%;
  padding: 7px 8px;
  border: 0;
  border-radius: var(--r-sm);
  background: none;
  text-align: left;
  cursor: pointer;
  transition: background-color var(--press) var(--ease-out);
}
@media (hover: hover) and (pointer: fine) {
  .damon-mixed-row li button:hover { background: rgb(var(--tint) / 0.05); }
}

.damon-mixed-title {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--text);
}

.damon-mixed-domain { flex: none; font-size: 11px; color: var(--text-faint); }

.damon-mixed-images {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
  padding: 2px 6px;
}

.damon-mixed-thumb {
  overflow: hidden;
  padding: 0;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: var(--surface-2);
  cursor: pointer;
  aspect-ratio: 1;
  transition: transform 160ms var(--ease-out), border-color 160ms var(--ease-out);
}
.damon-mixed-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
@media (hover: hover) and (pointer: fine) {
  .damon-mixed-thumb:hover { transform: scale(1.04); border-color: var(--hairline-strong); }
}

.damon-answer {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 10px;
  padding: 14px 16px;
  border: 1px solid color-mix(in srgb, var(--accent) 24%, transparent);
  border-radius: var(--r-lg);
  background: color-mix(in srgb, var(--accent) 7%, transparent);
  /* The answer arrives after the request that carries it, never with the
     page: it rises in as a thing that was just thought of, which is what
     happened. */
  animation: damon-rise 280ms var(--ease-out);
}

.damon-answer--loading {
  flex-direction: row;
  align-items: center;
  gap: 10px;
  border-color: var(--hairline);
  background: none;
  color: var(--text-faint);
  font-size: 12.5px;
}

.damon-answer-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
}

.damon-answer-kicker {
  font-size: var(--text-3xs);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.damon-answer-body {
  margin: 0;
  font-size: var(--text-md);
  line-height: var(--leading-relaxed);
  color: var(--text);
}

.damon-answer-sources {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.damon-answer-source {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-xs);
  background: var(--surface-2);
  color: var(--text-dim);
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  transition: color var(--press) var(--ease-out), border-color var(--press) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .damon-answer-source:hover { color: var(--text); border-color: var(--hairline-strong); }
}

.damon-answer-source--copy { color: var(--accent); }

.damon-web-item {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  padding: 12px 14px;
  border-radius: var(--r-md);
  border: 1px solid transparent;
  cursor: pointer;
  /* Entrance: each result rises in a beat after the one above it, so a page
     of results arrives as a list and not as one slab. Hover lifts, because
     a row that answers the pointer feels chosen rather than merely
     repainted. */
  opacity: 0;
  animation: damon-rise 220ms var(--ease-out) forwards;
  /* Capped. `--i` is the index in the whole list, not the page, so by the
     fourth page of infinite scroll this was a three-second delay on a row that
     starts at opacity 0 -- results arrived and stayed invisible, which reads
     exactly like scrolling having stopped loading anything. */
  animation-delay: min(calc(var(--i, 0) * 30ms), 240ms);
  transition: transform 160ms var(--ease-out), background-color 160ms var(--ease-out),
              border-color 160ms var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .damon-web-item:hover { transform: translateY(-1px); }
}

.damon-web-item:hover,
.damon-web-item.is-active {
  background: var(--surface-hover);
  border-color: var(--hairline);
}

.damon-web-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.damon-web-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11.5px;
  color: var(--text-faint);
}

.damon-web-domain {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-weight: 500;
  color: var(--text-dim);
}

.damon-favicon {
  width: 14px;
  height: 14px;
  border-radius: 2px;
}

.damon-web-url {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 320px;
}

.damon-web-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}

.damon-web-snippet {
  margin: 0;
  font-size: 12.5px;
  color: var(--text-dim);
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.damon-web-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: none;
}

.damon-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: var(--r-sm);
  border: 1px solid var(--hairline);
  background: var(--canvas);
  color: var(--text-dim);
  cursor: pointer;
  transition: color var(--press) var(--ease-out), background-color var(--press) var(--ease-out), border-color var(--press) var(--ease-out);
}
.damon-action-btn:hover {
  background: var(--surface-2);
  color: var(--text);
  border-color: var(--hairline-strong);
}

/* YouTube Bento Grid */
.damon-youtube-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
  padding: 4px;
}

.damon-yt-card {
  display: flex;
  flex-direction: column;
  border-radius: var(--r-md);
  border: 1px solid var(--hairline);
  background: var(--surface-2);
  overflow: hidden;
  cursor: pointer;
  position: relative;
  opacity: 0;
  animation: damon-rise 240ms var(--ease-out) forwards;
  /* Capped; see the note on .damon-web-item. */
  animation-delay: min(calc(var(--i, 0) * 40ms), 240ms);
  transition: transform 160ms var(--ease-out), border-color 160ms var(--ease-out), box-shadow 160ms var(--ease-out);
}

.damon-yt-card:hover,
.damon-yt-card.is-active {
  border-color: var(--accent);
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
}

.damon-yt-thumb-wrap {
  position: relative;
  aspect-ratio: 16/9;
  background: #000;
  overflow: hidden;
}

.damon-yt-thumb {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 200ms ease;
}
.damon-yt-card:hover .damon-yt-thumb { transform: scale(1.04); }

.damon-yt-duration {
  position: absolute;
  bottom: 6px;
  right: 6px;
  background: rgba(0, 0, 0, 0.8);
  color: #fff;
  font-size: 10.5px;
  font-weight: 600;
  padding: 2px 5px;
  border-radius: 4px;
}

.damon-yt-play-overlay {
  position: absolute;
  inset: 0;
  background: rgba(0, 0, 0, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  opacity: 0;
  transition: opacity 160ms ease;
}
.damon-yt-card:hover .damon-yt-play-overlay { opacity: 1; }

.damon-yt-info {
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
}

.damon-yt-title {
  margin: 0;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text);
  line-height: 1.35;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.damon-yt-channel {
  font-size: 11px;
  color: var(--text-dim);
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.damon-yt-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10.5px;
  color: var(--text-faint);
  margin-top: 2px;
}

.damon-yt-card-actions {
  position: absolute;
  top: 6px;
  right: 6px;
  opacity: 0;
  transition: opacity 140ms ease;
}
.damon-yt-card:hover .damon-yt-card-actions { opacity: 1; }

/* Image Grid */
.damon-image-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
  padding: 4px;
}

.damon-image-card {
