/* GitHub Repository List */
.damon-github-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.damon-gh-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 14px;
  border-radius: var(--r-md);
  border: 1px solid transparent;
  cursor: pointer;
  opacity: 0;
  animation: damon-rise 220ms var(--ease-out) forwards;
  /* Capped. `--i` is the index in the whole list, not the page, so by the
     fourth page of infinite scroll this was a three-second delay on a row that
     starts at opacity 0 -- results arrived and stayed invisible, which reads
     exactly like scrolling having stopped loading anything. */
  animation-delay: min(calc(var(--i, 0) * 30ms), 240ms);
  transition: transform 160ms var(--ease-out), background-color 160ms var(--ease-out), border-color 160ms var(--ease-out);
