  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 7px 12px;
  border-radius: 8px;
  font-size: 12.5px;
  font-weight: 550;
  cursor: pointer;
  border: none;
  transition: all 140ms ease;
}

.pm-btn--primary {
  background: var(--accent);
