}

.pm-item-busy {
  font-size: 12px;
  color: var(--text-dim);
}

.pm-flyout-footer {
  padding-top: 6px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.pm-footer-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-dim);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: color 120ms ease;
}

.pm-footer-link:hover {
  color: var(--text);
}

.pm-tool-group {
  margin-bottom: 8px;
}

.pm-tool-group-name {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-faint);
  padding: 4px 6px;
}

.pm-tool-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 6px;
  font-size: 12px;
  color: var(--text-dim);
}

.pm-tool-name {
  font-family: var(--font-mono);
  font-size: 11.5px;
  color: var(--text);
}

.pm-tool-risk {
  font-size: 10px;
  font-weight: 600;
  padding: 1px 5px;
