  color: #6fe0ae;
}
.pm-tool-risk--medium,
.pm-tool-risk--high {
  background: rgba(233, 180, 81, 0.15);
  color: #e9b451;
}
.pm-tool-risk--danger {
  background: rgba(255, 107, 125, 0.15);
  color: #ff6b7d;
}

.pm-empty-text {
