/* Row 2: Apple-style New Chat + Search Square Buttons */
.sb-header-actions-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
}

.sb-new-chat-btn,
.sb-new-chat-pill {
  flex: 1;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 36px;
  padding: 0 12px;
