}

.sb-search-btn-square,
.sb-search-btn-round {
  width: 36px;
  height: 36px;
  border-radius: var(--r-sm, 8px);
  display: grid;
  place-items: center;
  background: var(--surface);
  border: 1px solid var(--hairline);
  color: var(--text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color 0.16s var(--ease-out), border-color 0.16s var(--ease-out), color 0.16s var(--ease-out), transform 0.12s ease;
}

.sb-search-btn-square:hover,
.sb-search-btn-square.is-active,
.sb-search-btn-round:hover,
.sb-search-btn-round.is-active {
