}

.sb-icon-btn {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: var(--radius-md);
  color: var(--text-faint);
  background: transparent;
  border: 1px solid transparent;
  cursor: pointer;
  transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), background 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.sb-icon-btn:hover {
  color: var(--text);
  background: var(--surface-2);
  border-color: color-mix(in srgb, var(--hairline) 50%, transparent);
}

.sb-icon-btn:active {
  transform: scale(0.97);
}

.sb-icon-btn.is-active {
  color: var(--text);
  background: var(--surface-2);
  border-color: var(--hairline);
}

/* Search bar & Skiper106 Smooth Caret */
.sb-search-wrapper {
  padding: 12px 14px 4px;
  flex: none;
  overflow: hidden;
}

.sb-search-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  height: 36px;
  border-radius: var(--r-pill);
  background: var(--surface);
  border: 1px solid var(--hairline);
  transition: border-color 150ms cubic-bezier(0.4, 0, 0.2, 1), box-shadow 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

.sb-search-bar:focus-within {
  border-color: var(--text);
  box-shadow: 0 0 0 1px var(--text);
}

.sb-search-icon {
