  color: var(--text);
  font-size: 11px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--press) var(--ease-out), border-color var(--press) var(--ease-out), color var(--press) var(--ease-out), box-shadow var(--press) var(--ease-out), transform var(--press) var(--ease-out), opacity var(--press) var(--ease-out), filter var(--press) var(--ease-out);
}

.lib-resource-link:hover {
