/* ---- 16 Animated loader keyframes & classes --------------------------- */
/* 1. Pixels: 2x3 dot grid flashing */
.ld-pixels {
  display: grid;
  grid-template-columns: repeat(3, 4px);
  gap: 2.5px;
}
.ld-pixels i {
  width: 4px;
  height: 4px;
  border-radius: 1px;
  background: currentColor;
  animation: ld-px-flash 0.9s ease-in-out infinite;
}
.ld-pixels i:nth-child(1) { animation-delay: 0s; }
.ld-pixels i:nth-child(2) { animation-delay: 0.15s; }
.ld-pixels i:nth-child(3) { animation-delay: 0.3s; }
.ld-pixels i:nth-child(4) { animation-delay: 0.45s; }
.ld-pixels i:nth-child(5) { animation-delay: 0.6s; }
.ld-pixels i:nth-child(6) { animation-delay: 0.75s; }
@keyframes ld-px-flash {
  0%, 100% { opacity: 0.2; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.1); }
}

/* 2. Halo: spinning ring with bottom gap */
.ld-halo {
  width: 17px;
  height: 17px;
  border: 2px solid currentColor;
  border-bottom-color: transparent;
  border-radius: 50%;
  animation: ld-rotate 0.85s linear infinite;
  display: inline-block;
  box-sizing: border-box;
}
@keyframes ld-rotate {
  to { transform: rotate(360deg); }
}

/* 3. Orbit: 3 orbiting dots around center */
.ld-orbit {
  position: relative;
  width: 18px;
  height: 18px;
  animation: ld-rotate 1.6s linear infinite;
}
.ld-orbit i {
  position: absolute;
  width: 3.5px;
  height: 3.5px;
  border-radius: 50%;
  background: currentColor;
}
.ld-orbit i:nth-child(1) { top: 0; left: calc(50% - 1.75px); }
.ld-orbit i:nth-child(2) { bottom: 1px; left: 1px; }
.ld-orbit i:nth-child(3) { bottom: 1px; right: 1px; }

/* 4. Wake: 3 dots pulsating */
.ld-wake {
  display: flex;
  gap: 3px;
  align-items: center;
}
.ld-wake i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  animation: ld-wake-dot 1.1s ease-in-out infinite;
}
.ld-wake i:nth-child(2) { animation-delay: 0.2s; }
.ld-wake i:nth-child(3) { animation-delay: 0.4s; }
@keyframes ld-wake-dot {
  0%, 100% { opacity: 0.25; transform: translateY(0); }
  50% { opacity: 1; transform: translateY(-3px); }
}

/* 5. Pulse: vertical audio bars */
.ld-pulse {
  display: flex;
  gap: 2.5px;
  align-items: center;
  height: 16px;
}
.ld-pulse i {
  width: 2.5px;
  height: 8px;
  border-radius: 1.5px;
  background: currentColor;
  animation: ld-bar-grow 0.7s ease-in-out infinite alternate;
}
.ld-pulse i:nth-child(1) { animation-delay: 0s; }
.ld-pulse i:nth-child(2) { animation-delay: 0.2s; }
.ld-pulse i:nth-child(3) { animation-delay: 0.4s; }
.ld-pulse i:nth-child(4) { animation-delay: 0.1s; }
@keyframes ld-bar-grow {
  0% { transform: scaleY(0.4); }
  100% { transform: scaleY(1.4); }
}

/* 6. Shift: square sliding back and forth */
.ld-shift {
  position: relative;
  width: 18px;
  height: 12px;
  display: flex;
  align-items: center;
}
.ld-shift i {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  background: currentColor;
  animation: ld-shift-motion 1.1s ease-in-out infinite alternate;
}
@keyframes ld-shift-motion {
  0% { transform: translateX(0); }
  100% { transform: translateX(10px); }
}

/* 7. Ellipsis: 3 dots */
.ld-ellipsis {
  display: flex;
  gap: 3px;
  align-items: center;
}
.ld-ellipsis i {
  width: 3.5px;
  height: 3.5px;
  border-radius: 50%;
  background: currentColor;
  animation: ld-ellipsis-pop 1s ease-in-out infinite;
}
.ld-ellipsis i:nth-child(2) { animation-delay: 0.18s; }
.ld-ellipsis i:nth-child(3) { animation-delay: 0.36s; }
@keyframes ld-ellipsis-pop {
  0%, 80%, 100% { transform: scale(0.6); opacity: 0.3; }
  40% { transform: scale(1.15); opacity: 1; }
}

/* 8. Ripple: concentric expanding circles */
.ld-ripple {
  position: relative;
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ld-ripple i {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 1.5px solid currentColor;
  border-radius: 50%;
  animation: ld-ripple-out 1.2s cubic-bezier(0.1, 0.2, 0.3, 1) infinite;
}
.ld-ripple i:nth-child(2) { animation-delay: 0.5s; }
@keyframes ld-ripple-out {
  0% { transform: scale(0.2); opacity: 1; }
  100% { transform: scale(1.2); opacity: 0; }
}

/* 9. Clock: clock face with rotating hand */
.ld-clock {
  position: relative;
  width: 16px;
  height: 16px;
  border: 1.8px solid currentColor;
  border-radius: 50%;
  box-sizing: border-box;
}
.ld-clock i {
  position: absolute;
  top: 2px;
  left: calc(50% - 0.9px);
  width: 1.8px;
  height: 6px;
  border-radius: 1px;
  background: currentColor;
  transform-origin: bottom center;
  animation: ld-rotate 2s linear infinite;
}

/* 10. Drop: falling droplet */
.ld-drop {
  position: relative;
  width: 12px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ld-drop i {
  width: 5px;
  height: 5px;
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  background: currentColor;
  animation: ld-drop-anim 1s ease-in infinite;
}
@keyframes ld-drop-anim {
  0% { transform: translateY(-7px); opacity: 0; }
  40% { opacity: 1; }
  85% { transform: translateY(6px); opacity: 1; }
  100% { transform: translateY(7px); opacity: 0; }
}

/* 11. Scanner: scanning beam line */
.ld-scanner {
  position: relative;
  width: 18px;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.15);
  overflow: hidden;
}
.ld-scanner i {
  position: absolute;
  top: 0;
  width: 7px;
  height: 100%;
  border-radius: 2px;
  background: currentColor;
  animation: ld-scan-motion 1s ease-in-out infinite alternate;
}
@keyframes ld-scan-motion {
  0% { left: 0; }
  100% { left: calc(100% - 7px); }
}

/* 12. Card: 3D flipping card */
.ld-card {
  perspective: 60px;
  width: 14px;
  height: 10px;
}
.ld-card i {
  display: block;
  width: 100%;
  height: 100%;
  border: 1.5px solid currentColor;
  border-radius: 2px;
  box-sizing: border-box;
  animation: ld-card-flip 1.4s ease-in-out infinite;
}
@keyframes ld-card-flip {
  0%, 100% { transform: rotateY(0deg); }
  50% { transform: rotateY(180deg); }
}

/* 13. Dial: dashed spinning dial */
.ld-dial {
  width: 16px;
  height: 16px;
  border: 2px dashed currentColor;
  border-radius: 50%;
  animation: ld-rotate 2.4s linear infinite;
  box-sizing: border-box;
}

/* 14. Beacon: radar beacon ping */
.ld-beacon {
  position: relative;
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ld-beacon i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  animation: ld-beacon-pulse 1.3s ease-out infinite;
}
@keyframes ld-beacon-pulse {
  0% { box-shadow: 0 0 0 0 currentColor; }
  70% { box-shadow: 0 0 0 7px transparent; }
  100% { box-shadow: 0 0 0 0 transparent; }
}

/* 15. Duet: two bouncing dots */
.ld-duet {
  display: flex;
  gap: 4px;
  align-items: center;
}
.ld-duet i {
  width: 4.5px;
  height: 4.5px;
  border-radius: 50%;
  background: currentColor;
  animation: ld-duet-bounce 0.7s ease-in-out infinite alternate;
}
.ld-duet i:nth-child(2) {
  animation-delay: 0.35s;
}
@keyframes ld-duet-bounce {
  0% { transform: translateY(3px); }
  100% { transform: translateY(-3px); }
}

/* 16. Tumble: tumbling rolling square */
.ld-tumble {
  width: 12px;
  height: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.ld-tumble i {
  width: 8px;
  height: 8px;
  border: 1.5px solid currentColor;
  border-radius: 2px;
  box-sizing: border-box;
  animation: ld-tumble-turn 1.2s cubic-bezier(0.68, -0.55, 0.27, 1.55) infinite;
}
@keyframes ld-tumble-turn {
  0% { transform: rotate(0deg); }
  50% { transform: rotate(180deg) scale(0.85); }
  100% { transform: rotate(360deg); }
}

