  padding: 16px;
  cursor: pointer;
  transition: background-color 0.18s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.18s cubic-bezier(0.16, 1, 0.3, 1), color 0.18s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.18s cubic-bezier(0.16, 1, 0.3, 1), transform 0.18s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.18s cubic-bezier(0.16, 1, 0.3, 1), filter 0.18s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
  position: relative;
  box-shadow: var(--shadow-micro);
}

.guard-card:hover {
  border-color: var(--hairline-strong);
  transform: translateY(-1px);
}

.guard-card:active {
  transform: scale(0.98);
}

.guard-card.is-active {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent), 0 4px 16px var(--accent-wash);
}

.guard-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.guard-card-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text);
}

.guard-card-desc {
  font-size: 11.5px;
  color: var(--text-dim);
  line-height: 1.4;
}

.guard-card-badge {
  font-size: 10.5px;
  font-weight: 600;
  padding: 2px 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--text) 6%, transparent);
  color: var(--text-dim);
}

.guard-card.is-active .guard-card-badge {
  background: var(--accent-soft);
  color: var(--accent);
}

/* About View Modern Cards */
.about-header-box {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
}

.about-app-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--r-lg, 12px);
  background: var(--surface-3);
  border: 1px solid var(--hairline-strong);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  flex-shrink: 0;
}

.about-runtime-table {
  width: 100%;
  border-collapse: collapse;
}

.about-runtime-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-bottom: 1px solid var(--hairline);
  font-size: 12.5px;
}

.about-runtime-row:last-child {
  border-bottom: none;
}

.about-runtime-name {
  font-weight: 500;
  color: var(--text);
}

.about-runtime-val {
  color: var(--text-dim);
  font-family: var(--font-mono);
  font-size: 12px;
}

.about-path-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 18px;
  border-bottom: 1px solid var(--hairline);
  font-size: 12.5px;
}

.about-path-row:last-child {
  border-bottom: none;
}

/* ---- Interactive Bottom Terminal Drawer ----------------------------- */
.terminal-drawer {
  position: relative;
  width: 100%;
  height: var(--term-h, 280px);
  background: #09090b;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  z-index: 40;
  box-shadow: 0 -8px 30px rgba(0, 0, 0, 0.55);
}

.terminal-drawer.is-minimized {
  height: 36px !important;
}

.terminal-resize-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 6px;
  cursor: ns-resize;
  z-index: 50;
  background: transparent;
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
  transition: background 0.15s;
}

.terminal-resize-bar:hover,
.terminal-drawer.is-resizing .terminal-resize-bar {
