}

.terminal-header {
  height: 36px;
  min-height: 36px;
  padding: 0 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #0c0c0e;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
