}

.terminal-menu-item {
  width: 100%;
  text-align: left;
  background: transparent;
  border: none;
  color: #e4e4e7;
  padding: 6px 10px;
  border-radius: 5px;
  font-size: 12px;
  cursor: pointer;
  font-family: var(--font-mono, monospace);
