}

.terminal-body {
  flex: 1;
  min-height: 0;
  display: flex;
  background: #09090b;
  overflow: hidden;
}

.terminal-viewport-wrap {
  flex: 1;
  min-width: 0;
  min-height: 0;
  position: relative;
  padding: 4px 8px;
  background: #09090b;
}

.terminal-screen-slot {
  width: 100%;
  height: 100%;
}

.terminal-screen-slot.is-hidden {
  display: none !important;
}

.terminal-screen-slot.is-active {
  display: block;
}

.terminal-screen-slot .xterm {
  height: 100%;
  padding: 2px;
}

.terminal-screen-slot .xterm-viewport {
  background-color: transparent !important;
}

.terminal-screen-slot .xterm-viewport::-webkit-scrollbar {
  width: 6px;
}

.terminal-screen-slot .xterm-viewport::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 3px;
}

.terminal-sessions-panel {
  width: 120px;
  min-width: 120px;
  max-width: 130px;
  border-left: 1px solid rgba(255, 255, 255, 0.08);
  background: #09090b;
  padding: 4px;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.terminal-sessions-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.terminal-session-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 11px;
  font-family: var(--font-mono, JetBrains Mono, monospace);
  color: #71717a;
  cursor: pointer;
  user-select: none;
  overflow: hidden;
  transition: color 0.15s;
}

.terminal-session-item:hover {
  color: #d4d4d8;
}

.terminal-session-item.is-active {
  color: #ffffff;
  font-weight: 500;
}

.terminal-session-active-indicator {
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 4px;
  z-index: 0;
}

.terminal-session-label {
  position: relative;
  z-index: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.terminal-session-close-btn {
  position: relative;
  z-index: 1;
  background: transparent;
  border: none;
  color: #71717a;
  padding: 2px;
  border-radius: 3px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.15s, background 0.15s;
  margin-left: 4px;
}

.terminal-session-close-btn:hover {
  color: #f4f4f5;
  background: rgba(255, 255, 255, 0.15);
}


/* ── Remote control ───────────────────────────────────────────────────────
   The phone's page. Sized for a thumb rather than a pointer: the tap targets
   are 44px, the thread scrolls under a composer pinned to the bottom, and the
   whole thing assumes one hand and no keyboard. */

.rc {
  display: flex;
  flex-direction: column;
  height: 100%;
  max-width: 720px;
  margin: 0 auto;
  padding: 0 16px;
  gap: 12px;
}

.rc-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding-top: 18px;
}

.rc-head h1 { font-size: 1.35rem; margin: 0; }

.rc-sub {
  margin: 2px 0 0;
  font-size: 0.82rem;
  color: var(--text-dim);
}

.rc-tabs {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
}
.rc-tabs::-webkit-scrollbar { display: none; }

.rc-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  min-height: 36px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: inherit;
  font-size: 0.85rem;
  max-width: 60vw;
}
.rc-tab span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rc-tab.is-active { background: var(--accent); border-color: transparent; color: #fff; }

.rc-thread {
  flex: 1 1 auto;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 4px 0 8px;
}

.rc-msg { display: flex; flex-direction: column; gap: 4px; }

.rc-role {
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
}

.rc-body { white-space: pre-wrap; word-break: break-word; line-height: 1.55; }

.rc-msg--user .rc-body {
  align-self: flex-end;
  background: var(--accent);
  color: #fff;
  padding: 10px 13px;
  border-radius: 14px 14px 4px 14px;
}

.rc-msg--phase .rc-body,
.rc-msg--queued .rc-body { color: var(--text-dim); font-style: italic; }

.rc-composer {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  padding: 10px 0 max(16px, env(safe-area-inset-bottom));
  border-top: 1px solid var(--hairline);
}

.rc-input {
  flex: 1 1 auto;
  resize: none;
  border-radius: 12px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: inherit;
  padding: 10px 12px;
  /* 16px or iOS zooms the page on focus, which on a phone reads as a bug. */
  font: inherit;
  font-size: 16px;
}

.rc-send {
  flex: 0 0 auto;
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
}
.rc-send:disabled { opacity: 0.4; }

.rc-empty {
  margin: auto;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  max-width: 34ch;
  color: var(--text-dim);
}
.rc-empty h2 { margin: 0; font-size: 1.05rem; color: inherit; }
.rc-empty code { font-size: 0.85em; }

/* The pairing code, grouped in fours so it can be typed on a phone without a
   typo in the middle of thirty-two characters. */
.rc-code {
  font-size: 15px;
  letter-spacing: 0.06em;
  word-spacing: 0.25em;
  line-height: 1.7;
  word-break: break-word;
}

/* ── Pairing ──────────────────────────────────────────────────────────────
   The first screen on a device with no backend. One column, thumb-sized
   targets, and 16px inputs so iOS does not zoom the page on focus. */

.pair {
  min-height: 100dvh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px max(24px, env(safe-area-inset-bottom));
  background: var(--canvas-deep);
}

.pair-card {
  width: 100%;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  /* A surface, in the same terms every other card in this interface uses. It
     had none -- no background, no border, no radius -- which left the whole
     screen as unstyled text floating on the canvas. */
  background: var(--raised);
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  padding: 22px 20px;
  box-shadow: var(--shadow-micro);
}

.pair-card > svg { color: var(--accent); }
.pair-card h1 { color: var(--text); }

.pair-card h1 { margin: 4px 0 0; font-size: 1.4rem; }

.pair-sub {
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.55;
  color: var(--text-dim);
}

.pair-steps {
  margin: 4px 0 8px;
  padding-left: 20px;
  font-size: 0.88rem;
  line-height: 1.85;
  color: var(--text-dim);
}
.pair-steps code {
  font-size: 0.85em;
  padding: 1px 5px;
  border-radius: 5px;
  background: var(--hairline);
  color: var(--fg, #e8e8ea);
}

.pair-label {
  font-size: 0.72rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-dim);
  margin-top: 4px;
}

.pair-input {
  width: 100%;
  min-height: 48px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: inherit;
  font: inherit;
  font-size: 16px;   /* below this, iOS zooms on focus */
}
.pair-input:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
.pair-input--code { letter-spacing: 0.12em; text-transform: uppercase; }

.pair-steps li { color: var(--text-dim); }
.pair-steps strong { color: var(--text); font-weight: 600; }

.pair-go {
  min-height: 50px;
  margin-top: 8px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-size: 1rem;
  font-weight: 600;
}
.pair-go:disabled { opacity: 0.4; }

.pair-error {
  margin: 0;
  font-size: 0.85rem;
  color: var(--stop, #ff6b6b);
  line-height: 1.5;
}

/* The phone's frame: no rail, no panel, no drawer — just the remote view and
   the notch to stay out of. */
.remote-only {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  padding-top: env(safe-area-inset-top);
  background: var(--canvas-deep);
}
.remote-only > * { flex: 1 1 auto; min-height: 0; }

.boot-remote { margin-top: 8px; }
.rc-actions { display: flex; align-items: center; gap: 8px; }
.rc-unpair {
  min-height: 44px;
  padding: 0 12px;
  border-radius: 12px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  font-size: 0.82rem;
}


/* ── Pairing: the states, the scanner, the code ───────────────────────────
   Added with the QR flow. The layout rules above still hold -- one column,
   100dvh, safe-area insets, 44px targets, 16px inputs -- and these are the
   pieces that flow needed: a screen per outcome instead of one form with an
   error line under it, and somewhere to put a camera. */

/* One outcome, centred. Every phase uses this so the card does not resize
   between "pairing" and "paired" and make the page jump. */
.pair-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 10px;
  padding: 18px 0;
  min-height: 210px;
  justify-content: center;
}
.pair-state h1 { margin: 0; font-size: 1.25rem; }
.pair-state .pair-sub { max-width: 34ch; }
.pair-state--ok { color: var(--live); }
.pair-state--bad { color: var(--stop); }
/* The heading and body go back to normal text; only the icon carries the
   colour, because a whole card of red reads as a crash rather than an answer. */
.pair-state--ok h1,
.pair-state--bad h1 { color: var(--text); }
.pair-state--ok .pair-sub,
.pair-state--bad .pair-sub { color: var(--text-dim); }
.pair-state .pair-go { margin-top: 6px; min-width: 200px; }

.pair-spinner {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 2px solid var(--hairline);
  border-top-color: var(--accent);
  animation: pair-spin 0.8s linear infinite;
}
@keyframes pair-spin { to { transform: rotate(360deg); } }
/* Someone who has asked for less motion still needs to know it is working, so
   the spinner stops turning and pulses instead of disappearing. */
@media (prefers-reduced-motion: reduce) {
  .pair-spinner { animation: pair-pulse 1.6s ease-in-out infinite; }
  @keyframes pair-pulse { 50% { opacity: 0.35; } }
}

.pair-manual { display: contents; }

/* The quieter of the two actions: typing the code, cancelling a scan, leaving
   for the desktop interface. Still 44px, because it is still a thumb. */
.pair-secondary {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 12px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  padding: 0 14px;
}

.pair-escape,
.rc-escape {
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  bottom: max(10px, env(safe-area-inset-bottom));
  border: none;
  background: transparent;
  color: var(--text-dim);
  font: inherit;
  font-size: 0.78rem;
  text-decoration: underline;
  text-underline-offset: 3px;
  min-height: 44px;
  padding: 0 12px;
}

/* ── The scanner ─────────────────────────────────────────────────────────── */

.qr-scan {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.qr-scan-frame {
  position: relative;
  width: 100%;
  /* Square, and capped so it cannot push the hint and the cancel button off a
     short screen in landscape. */
  aspect-ratio: 1;
  max-height: 60dvh;
  border-radius: 16px;
  overflow: hidden;
  background: #000;
}

.qr-scan-video {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Corners rather than a full box: it says where to aim without covering the
   thing being aimed at. */
.qr-scan-reticle {
  position: absolute;
  inset: 14%;
  border-radius: 12px;
  box-shadow: 0 0 0 100vmax rgba(0, 0, 0, 0.45);
  outline: 2px solid rgba(255, 255, 255, 0.9);
  outline-offset: -1px;
}

.qr-scan-hint {
  margin: 0;
  text-align: center;
  font-size: 0.85rem;
  color: var(--text-dim);
  max-width: 32ch;
}

/* ── Remote: stopping a turn, and the way back out ───────────────────────── */

.rc-stop {
  margin-left: 10px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  vertical-align: middle;
  border: 1px solid var(--hairline);
  border-radius: 8px;
  background: transparent;
  color: var(--stop);
  font: inherit;
  font-size: 0.75rem;
  font-style: normal;
  padding: 4px 9px;
  /* Smaller than 44px on purpose: it sits inline in a status line, and the
     surrounding row is the target. Kept reachable by the padding. */
  min-height: 32px;
}

/* The composer is pinned; the escape hatch must not sit on top of it. */
.rc-escape { position: static; transform: none; margin: 0 auto 4px; }

/* ── The pairing code, on the machine showing it ─────────────────────────── */

/* White, in every theme, and not negotiable: a QR code inverted to light
   modules on a dark background is one a good half of scanners will not read.
   The card is what guarantees the quiet zone and the contrast, whatever theme
   the interface is in. */
.qr-card {
  background: #fff;
  border-radius: 14px;
  padding: 14px;
  width: min(232px, 62vw);
  align-self: center;
  line-height: 0;
}
.qr-card svg { width: 100%; height: auto; display: block; }

.pair-invite {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
}
.pair-invite-hint {
  margin: 0;
  text-align: center;
  font-size: 0.82rem;
  color: var(--text-dim);
}


/* ══ Responsive: tablet and below ═════════════════════════════════════════
 *
 * One block, at the end, on purpose. The rules above were written per-surface
 * over time and use eleven different breakpoints between 480px and 1280px; this
 * does not try to rewrite them. It fixes the surfaces that actually overflow a
 * 390px viewport, at the two widths that change the shape of the application.
 *
 * The scale, so the next person adds to it rather than inventing a twelfth:
 *
 *   --bp-phone   599.98px   below this it is a handheld  (see `usePhone`)
 *   --bp-tablet  899.98px   below this there is no room for a second column
 *   --bp-desktop 1279.98px  below this the panel competes with the stage
 *
 * `COMPACT_QUERY` in `hooks/useMediaQuery.js` (859.98px) is the one the
 * JavaScript also reads -- it decides whether the rail is a drawer -- and is
 * deliberately left where it is rather than moved onto this scale, because
 * changing it changes behaviour and not only appearance.
 *
 * Custom properties cannot be used in a media query, so these are documentation
 * rather than machinery. That is what they are for here.
 */
:root {
  --bp-phone: 599.98px;
  --bp-tablet: 899.98px;
  --bp-desktop: 1279.98px;
}

@media (max-width: 899.98px) {
  /* Nothing may scroll the page sideways. A single element wider than the
     viewport makes every other fix here invisible, so this is first. */
  html, body { max-width: 100%; overflow-x: hidden; }

  /* ── Settings ──────────────────────────────────────────────────────────
     A 236px fixed nav column beside the content left 154px for the content on
     a 390px screen. Below tablet the nav becomes a horizontal strip above it,
     which is the same information in the shape that fits. */
  .settings-view { flex-direction: column !important; }

  .settings-view .set-nav {
    width: 100% !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 4px !important;
    overflow-x: auto !important;
    overflow-y: hidden !important;
    border-right: none !important;
    border-bottom: 1px solid var(--hairline) !important;
    padding: 8px 12px !important;
    scrollbar-width: none;
  }
  .settings-view .set-nav::-webkit-scrollbar { display: none; }

  /* The groups are vertical stacks with labels, which is the wrong shape in a
     strip: the labels become headings between buttons in a row. */
  .settings-view .set-nav-group { display: contents !important; }
  .settings-view .set-nav-group-label { display: none !important; }

  /* An earlier rule at this width turns the nav into a 56px icon-only rail and
     hides these. It has been dead since `.settings-view .set-nav` took a
     `width: 236px !important` -- which is the whole reason settings overflowed
     a phone rather than falling back to icons. The strip has room for words,
     so they come back. */
  .settings-view .set-nav .set-nav-label {
    display: inline !important;
    overflow: visible;
    text-overflow: clip;
  }
  /* The header is a title with a rule under it in the vertical layout. In a
     strip that rule becomes a vertical line in the middle of the row. */
  .settings-view .set-nav-header {
    flex: 0 0 auto;
    margin-bottom: 0 !important;
    padding: 0 8px 0 0 !important;
    border-bottom: none !important;
  }

  /* `width: auto` is the one that matters. The vertical layout sets
     `width: 100% !important`, and in a row that made every item as wide as the
     viewport -- ten sections at 366px each, one visible at a time, behind
     3600px of horizontal scrolling. `flex: 0 0 auto` alone does not undo it,
     because the basis resolves to that width. */
  .settings-view .set-nav-item {
    width: auto !important;
    flex: 0 0 auto !important;
    white-space: nowrap;
    min-height: 40px;
    height: auto !important;
    padding: 0 12px !important;
  }

  /* A row is a label beside a control. Below tablet there is not width for
     both, so it becomes a label above a control. This is also what neutralises
     the fixed `minWidth` inline styles in Settings.jsx -- they are the reason
     several of these rows overflowed rather than wrapped, and a rule here
     reaches all twelve of them without touching a 3800-line file. */
  .settings-view .set-box-row {
    flex-wrap: wrap;
    align-items: flex-start;
  }
  .settings-view .set-box-row > * { min-width: 0 !important; max-width: 100%; }
  .settings-view .set-row-text { flex: 1 1 100%; min-width: 0; }
  .set-input { width: 100%; box-sizing: border-box; }

  /* ── The workbench ─────────────────────────────────────────────────────
     The detail panel is a fourth column on a screen with room for one and a
     half. The rail already becomes a drawer on its own at 860px. */
  .wb-panel { display: none !important; }
  .wb-main { min-width: 0; }

  /* ── Overlays ──────────────────────────────────────────────────────────
     Each of these was sized for a desktop window and centred, so on a narrow
     screen they hung off both edges. */
  .palette, .modal, .modal-card {
    width: min(100%, calc(100vw - 24px)) !important;
    max-width: calc(100vw - 24px) !important;
    box-sizing: border-box;
  }

  /* The terminal is a developer tool on a device with no keyboard to speak of.
     It keeps working; it just does not open onto most of the screen. */
  .terminal-drawer { max-height: 60dvh; }
}

@media (max-width: 599.98px) {
  /* Full height that accounts for the browser's own chrome. `100vh` on iOS is
     taller than the visible area, which put every pinned composer under the
     address bar. */
  .settings-view, .wb, .app { min-height: 100dvh; }

  /* 16px, or iOS zooms the page when a field takes focus -- which on a phone
     reads as the layout breaking. */
  input, textarea, select { font-size: 16px; }

  .settings-view .set-panel-frame { padding: 14px 14px 20px !important; }
  .settings-view .set-panel { max-width: 100% !important; }

  /* The notch, and the home indicator. */
  .wb-bar { padding-top: max(0px, env(safe-area-inset-top)); }
}

/* A pointer that cannot hover is a finger, and a finger needs somewhere to
   land. Keyed on the input rather than the width so it also covers a touch
   laptop, and scoped to controls that were sized for a mouse. */
@media (pointer: coarse) {
  .set-btn-sm,
  .set-nav-item,
  .rc-tab,
  .sb-place-item,
  .sb-conv-item,
  .wb-bar button {
    min-height: 44px;
  }
}
/* AMETHYST — an instrument panel for an agent with root on this machine.

   The brief, stated so it can be argued with. AMETHYST is a shell you keep
   open all day beside a terminal. It used to be dressed as an Apple store
   page: paper grounds, ink-on-paper buttons, no brand colour at all. That
   reads as calm in a screenshot and as undifferentiated in use — with no hue
   carrying "this is the thing you press", every control had to be told apart
   by its border, and a page of bordered rectangles is what the interface
   became.

   This file now speaks the Kraken system (UIInspirations/DESIGN-kraken.md).
   One commanding brand colour — Kraken Purple #7132f5 — owns every primary
   action, every link, every selected state, and nothing else. The neutral
   scale underneath it is cool blue-grey rather than warm parchment, because a
   warm neutral under a violet accent turns the accent muddy. IBM Plex Sans is
   the documented stand-in for the two proprietary Kraken faces and does both
   jobs here: 700 with negative tracking for display, 400/500 for the UI.

   Radii are the part people notice without knowing they noticed. Kraken caps
   buttons at 12px — no pills, ever — and containers at 16px. Pill radius
   survives in this file only for things that are genuinely capsules: toggles,
   avatars, tag chips.

   Elevation is a whisper, not a drop. Kraken separates a card from the page
   with a hairline and 3%-black at 24px of blur; the only things that get real
   shadow are the things that float over the page — menus, modals, toasts.

   Three semantic colours, and they mean liveness or risk, nothing else. A
   connector that is actually running is green. Something about to touch your
   files is amber. Something destructive is coral. Purple is never a status.

   Motion follows Emil Kowalski's rules, unchanged: strong custom curves,
   nothing over 300ms, transform and opacity only, transitions rather than
   keyframes wherever a thing can be re-triggered mid-flight, and no animation
   at all on the things a person hits a hundred times a day. */

:root {
  /* ---- the Kraken scale, raw ------------------------------------------
     Named here once so the semantic layer below can be re-pointed without
     hunting hex through 12,000 lines, and so a reviewer can check this block
     against DESIGN-kraken.md line by line. Nothing outside this file's token
     blocks should reference a --k- name; use the semantic token. */
  --k-purple: #7132f5;        /* primary CTA, brand accent, links */
  --k-purple-dark: #5741d8;   /* outlined-button borders */
  --k-purple-deep: #5b1ecf;   /* deepest — pressed and hover fills */
  --k-purple-lift: #855bfb;   /* the base of the 16% subtle fill */
  --k-ink: #101114;           /* primary text */
  --k-gray: #374151;          /* primary neutral - high contrast */
  --k-silver: #64748b;        /* secondary text - crisp WCAG AA */
  --k-border: #dedee5;        /* divider borders */
  --k-green: #149e61;         /* positive */
  --k-green-deep: #026b3f;    /* badge text on a green wash */

  /* ---- grounds ---------------------------------------------------------
     Two, not five. `--canvas` is what a card is made of; `--canvas-deep` is
     the page it sits on. Everything else is a mix of the two and exists only
     because some component asked for a third step. */
  --canvas: #ffffff;
  --canvas-deep: #f6f6f9;
  --raised: #ffffff;
  --surface: #f2f2f6;
  --surface-2: #f8f8fb;
  --surface-3: #ebebf1;

  /* Aliases for the handful of selectors that reached for these names before
     anything defined them. Without these they resolved to nothing (an invalid
     `background: var(--bg)`) or to a hardcoded dark fallback that lit up in
     light mode — which is most of what "dark mode is unstable" meant. */
  --bg: var(--canvas);
  --surface-raised: var(--raised);
  --surface-overlay: var(--raised);
  --surface-hover: rgb(var(--tint) / 0.05);
  --border: var(--hairline);

  /* Every hover, divider and wash in the file is mixed from these two, so a
     theme flip is one pair of numbers rather than four hundred declarations. */
  --tint: 16 17 20;
  --shade: 16 17 20;

  --hairline: var(--k-border);
  --hairline-strong: #c5c5d1;

  --text: var(--k-ink);
  --text-dim: var(--k-gray);
  --text-faint: var(--k-silver);

  /* ---- the one brand colour -------------------------------------------
     `--accent` fills things, `--ember` writes things. They are the same hue
     in light because #7132f5 is legible both ways on white; they diverge in
     dark, where a fill can be darker than text is allowed to be. */
  --accent: var(--k-purple);
  --accent-hover: var(--k-purple-deep);
  --accent-line: var(--k-purple-dark);
  --accent-soft: rgb(133 91 251 / 0.16);
  --accent-wash: rgb(133 91 251 / 0.07);
  --on-accent: #ffffff;
  --ember: var(--k-purple);

  /* ---- the three that mean something ---------------------------------- */
  --live: var(--k-green);
  --live-ink: var(--k-green-deep);
  --confirm: #a86a12;
  --stop: #d42a45;
  --coral: #ff6b6b;

  --live-soft: color-mix(in srgb, var(--live) 14%, transparent);
  --confirm-soft: color-mix(in srgb, var(--confirm) 12%, transparent);
  --stop-soft: color-mix(in srgb, var(--stop) 11%, transparent);
  --live-line: color-mix(in srgb, var(--live) 28%, transparent);
  --confirm-line: color-mix(in srgb, var(--confirm) 28%, transparent);
  --stop-line: color-mix(in srgb, var(--stop) 28%, transparent);

  --on-stop: #ffffff;
  --focus-ring: color-mix(in srgb, var(--accent) 45%, transparent);
  --glass: rgb(255 255 255 / 0.82);
  --scrim: rgb(16 17 20 / 0.38);
  --code-literal: var(--k-green-deep);

  /* ---- type ------------------------------------------------------------
     Geist as the primary typeface for UI, headings, navigation, labels,
     inputs, cards, and dialogs. Geist Mono exclusively where monospaced
     typography has a functional reason (code, terminal, logs, IDs, tokens). */
  --font-display: 'Geist', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-body: 'Geist', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-serif: 'Geist', system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-sans: var(--font-body);
  --font-mono: 'Geist Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;

  --font-weight-medium: 500;

  /* Deliberate letter spacing: subtle negative tracking on larger display
     headings, neutral tracking on body text. */
  --track-hero: -0.025em;
  --track-display: -0.02em;
  --track-title: -0.01em;
  --track-body: 0;

  /* ---- radii -----------------------------------------------------------
     Kraken's ladder exactly: 3 / 6 / 8 / 10 / 12 / 16. Twelve is the ceiling
     for anything pressable — the design system is explicit that pill buttons
     are wrong for it. `--r-pill` stays for real capsules only: toggle tracks,
     avatars, tag chips, the scroll thumb. */
  --r-xs: 6px;
  --r-sm: 8px;
  --r-md: 10px;
  --r-lg: 12px;
  --r-xl: 16px;
  --r-2xl: 20px;
  --r-pill: 9999px;

  /* The older alias set, kept pointed at the same ladder so the two can never
     disagree about what "medium" means. */
  --radius-sm: var(--r-sm);
  --radius-md: var(--r-lg);
  --radius-lg: var(--r-xl);
  --radius-xl: var(--r-2xl);

  /* ---- spacing --------------------------------------------------------- */
  --space-3xs: 2px;
  --space-2xs: 4px;
  --space-xs: 6px;
  --space-sm: 8px;
  --space-md: 12px;
  --space-lg: 16px;
  --space-xl: 20px;
  --space-2xl: 24px;
  --space-3xl: 32px;
  --space-4xl: 40px;
  --space-5xl: 56px;

  /* ---- type scale (scales dynamically with --text-scale) -------------- */
  --text-scale: 1;
  --text-3xs: calc(11px * var(--text-scale, 1));
  --text-2xs: calc(12px * var(--text-scale, 1));
  --text-xs: calc(13px * var(--text-scale, 1));
  --text-sm: calc(14px * var(--text-scale, 1));
  --text-md: calc(15px * var(--text-scale, 1));
  --text-lg: calc(16px * var(--text-scale, 1));
  --text-xl: calc(18px * var(--text-scale, 1));
  --text-2xl: calc(22px * var(--text-scale, 1));
  --text-3xl: calc(28px * var(--text-scale, 1));
  --text-4xl: calc(36px * var(--text-scale, 1));
  --text-5xl: calc(48px * var(--text-scale, 1));

  --leading-tight: 1.2;
  --leading-normal: 1.38;
  --leading-relaxed: 1.6;

  /* Breakpoint contract for new/touched CSS, from DESIGN-kraken.md §8:
     375 / 425 / 640 / 768 / 1024 / 1280 / 1536. Older ad hoc widths
     (860/820/720/620/560/980) are being retired as each view is touched. */

  /* ---- motion ----------------------------------------------------------
     The built-in easings are too weak to read as intentional; these are the
     stronger variants from the animation rules this project follows. */
  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);
  --ease-spring: cubic-bezier(0.34, 1.4, 0.64, 1);

  --press: 120ms;
  --pop: 160ms;
  --menu: 180ms;
  --modal: 240ms;

  /* ---- elevation -------------------------------------------------------
     Kraken's two shadows are whispers: a card on the page is separated by its
     hairline, and these only soften the edge. `--lift` is the exception and
     is reserved for things that genuinely float over the page — menus,
     popovers, modals, toasts — where a hairline alone reads as a seam in the
     page rather than as a layer above it. */
  --shadow-micro: 0 1px 4px rgb(16 24 40 / 0.04);
  --shadow-subtle: 0 4px 24px rgb(0 0 0 / 0.03);
  --lift: 0 1px 4px rgb(16 24 40 / 0.05), 0 16px 40px -12px rgb(16 17 20 / 0.14);
  --focus: 0 0 0 2px var(--canvas), 0 0 0 4px var(--focus-ring);
  --bar-h: 52px;
}

/* ------------------------------------------------------------------ night

   The same shell with the lights off, re-chosen rather than inverted. An
   inverted light theme gives you grey-on-grey and a page that glares.

   The grounds are cool, matching Kraken's blue-grey neutrals — a warm ground
   under a violet accent is the tell that the dark theme was picked from a
   different system.

   Kraken Purple at #7132f5 is a light-ground colour: on near-black it lands
   at roughly 3:1 and reads as a bruise. The accent lifts to #855bfb (the base
   of Kraken's own 16% subtle fill, so it is still on-scale) for fills, and
   text-weight purple lifts further to #a88bfd, which clears 6.5:1. Green and
   coral lift for the same reason.

   `--tint` flips from near-black to white, and with it every hover, every
   card ground and every divider in the file, because they are all mixed from
   it.

   Written as one set of declarations repeated twice — once for the explicit
   choice, once for a machine set to dark that has not been asked — so the two
   can never disagree about what dark means. */

/* =========================================================================
   PALETTES / THEMES: Graphite, Ink, Nocturne, Paper, Sand, Dark, Light
   ========================================================================= */

/* ---- Graphite: pristine neutral dark charcoal (zero blue tint) -------- */
:root[data-theme='graphite'],
:root[data-theme='dark'] {
  --canvas: #141414;
  --canvas-deep: #0e0e0e;
  --raised: #1c1c1e;
  --surface: #1f1f1f;
  --surface-2: #232323;
  --surface-3: #181818;

  --tint: 255 255 255;
  --shade: 0 0 0;

  --hairline: rgba(255, 255, 255, 0.08);
  --hairline-strong: rgba(255, 255, 255, 0.14);

  --text: #fcfcfd;
  --text-dim: #d4d4d8;
  --text-faint: #a1a1aa;

  --accent: #a855f7;
  --accent-hover: #b975f9;
  --accent-line: #a855f7;
  --accent-soft: rgba(168, 85, 247, 0.16);
  --accent-wash: rgba(168, 85, 247, 0.07);
  --on-accent: #ffffff;
  --ember: #d8b4fe;

  --live: #2fc888;
  --live-ink: #6fe0ae;
  --confirm: #e9b451;
  --stop: #ff6b7d;

  --live-soft: color-mix(in srgb, var(--live) 14%, transparent);
  --confirm-soft: color-mix(in srgb, var(--confirm) 12%, transparent);
  --stop-soft: color-mix(in srgb, var(--stop) 12%, transparent);
  --live-line: color-mix(in srgb, var(--live) 28%, transparent);
  --confirm-line: color-mix(in srgb, var(--confirm) 28%, transparent);
  --stop-line: color-mix(in srgb, var(--stop) 28%, transparent);

  --on-stop: #1b0c0e;
  --glass: rgba(20, 20, 20, 0.85);
  --scrim: rgba(0, 0, 0, 0.65);
  --code-literal: #7fdcae;

  --shadow-micro: none;
  --shadow-subtle: none;
  --lift: 0 4px 24px rgba(0, 0, 0, 0.55);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    --canvas: #141414;
    --canvas-deep: #0e0e0e;
    --raised: #1c1c1e;
