/* ------------------------------------------------------------- 3x3 Animated Matrix */
.matrix-loader {
  display: inline-grid;
  grid-template-columns: repeat(3, 3.5px);
  grid-template-rows: repeat(3, 3.5px);
  gap: 2px;
  width: 15px;
  height: 15px;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
  flex: none;
}
.matrix-dot {
  width: 3.5px;
  height: 3.5px;
  border-radius: 0.8px;
  background: var(--text);
  animation: matrixWave 1.2s ease-in-out infinite;
}
@keyframes matrixWave {
  0%, 100% {
    opacity: 0.22;
    transform: scale(0.85);
    background: rgb(var(--tint) / 0.35);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
    background: var(--text);
  }
}
.matrix-loader--writing .matrix-dot {
  animation-name: matrixWritingWave;
}
@keyframes matrixWritingWave {
  0%, 100% {
    opacity: 0.22;
    transform: scale(0.85);
    background: rgb(var(--tint) / 0.35);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
    background: var(--text);
  }
}

