  transition: all 180ms cubic-bezier(0.16, 1, 0.3, 1);
  flex: none;
}

.pm-switch.is-on {
  background: #2fc888;
  border-color: #2fc888;
  box-shadow: 0 0 8px rgba(47, 200, 136, 0.35);
}

.pm-switch.is-disabled {
