  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
  transition: transform 180ms cubic-bezier(0.16, 1, 0.3, 1);
}

.pm-switch.is-on .pm-switch-thumb {
  transform: translateX(12px);
}


/* Subview Drill-down inside PlusMenu */
.pm-subview {
  display: flex;
