  transition: color 120ms ease;
}

.pm-flyout-close:hover {
  color: var(--text);
}

.pm-flyout-desc {
  font-size: 11.5px;
  color: var(--text-dim);
  line-height: 1.4;
  margin: 0;
}

.pm-flyout-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.pm-input {
  width: 100%;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text);
