  color: var(--text-dim);
  padding: 10px 8px;
  text-align: center;
}

/* ------------------------------------------- skills and connectors, one page

   Two tabs over one page, because they are the same kind of thing: something
   the agent is given. What is added sits above what could be added, so the
   catalogue is where the thing it adds is managed rather than in an overlay of
   its own. */

.cap-head {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-bottom: 20px;
}
.cap-head h1 {
  font-family: var(--font-display);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.03em;
}
.cap-head .btn { margin-left: auto; flex: none; }

/* Below this the title wraps to two lines and the pill sits in the notch it
   leaves, which reads as a collision rather than as a layout. Stacked, the
   title is a title and the action is an action. */
@media (max-width: 620px) {
  .cap-head { flex-direction: column; align-items: stretch; gap: var(--space-md); }
  .cap-head h1 { font-size: var(--text-3xl); }
  .cap-head .btn { margin-left: 0; align-self: flex-start; }
}

/* The same wrap, for every other page title row. */
@media (max-width: 620px) {
  .vheader-actions { flex-wrap: wrap; }
}

/* Two columns of one thing each: an icon and a name. */
.cat-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 8px;
}

.cat-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  color: var(--text-dim);
  text-align: left;
  transition: background var(--press) var(--ease-out), border-color var(--press) var(--ease-out),
              color var(--press) var(--ease-out);
}
.cat-row:hover:not(:disabled) { background: var(--surface); border-color: var(--hairline-strong); color: var(--text); }
.cat-row:disabled { opacity: 0.5; }
.cat-row-name { flex: 1; min-width: 0; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.cat-row-add { flex: none; opacity: 0; transition: opacity var(--press) var(--ease-out); }
.cat-row:hover .cat-row-add, .cat-row:focus-visible .cat-row-add { opacity: 0.7; }

.cat-more {
  display: block;
  margin: 14px auto 0;
  padding: 6px 14px;
  font-size: 12.5px;
  color: var(--text-faint);
}
.cat-more:hover { color: var(--text); }

.cap-note {
  margin: -4px 0 10px;
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--text-faint);
  max-width: 68ch;
}

.cap-bar {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--hairline);
}

.cap-tabs { display: flex; gap: 2px; }

.cap-tab {
  display: flex;
  align-items: center;
  padding: 8px 18px;
  border: 1px solid transparent;
  border-radius: 99px;
  font-size: 13.5px;
  color: var(--text-faint);
  transition: color var(--press) var(--ease-out);
  position: relative;
  z-index: 1;
}
.cap-tab:hover { color: var(--text-dim); }
.cap-tab.active { border-color: transparent; color: var(--text); font-weight: 500; }
.cap-tab-active-pill {
  position: absolute;
  inset: 0;
  border-radius: 99px;
  background: var(--surface);
  border: 1px solid var(--hairline-strong);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  z-index: -1;
}
[data-theme="light"] .cap-tab-active-pill {
  background: var(--raised);
  box-shadow: var(--shadow-micro);
}
.cap-tab-label {
  position: relative;
  z-index: 2;
}

.cap-search {
  flex: 1;
  min-width: 200px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  color: var(--text-faint);
}
.cap-search:focus-within { border-color: var(--hairline-strong); }
.cap-search input {
  flex: 1;
  min-width: 0;
  padding: 8px 0;
  border: none;
  background: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 13px;
  outline: none;
}

.cap-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}
.cap-filter { display: flex; gap: 2px; margin-left: 4px; }
.cap-count {
  margin-left: auto;
  font-size: var(--text-2xs);
  color: var(--text-faint);
}

.cap-section-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 10px;
  font-size: var(--text-xs);
  color: var(--text-faint);
}
.cap-section-head span:last-child { margin-left: auto; }

/* The same section head, when the section folds. Full-width so the whole line
   is the hit target, not just the word. */
.cap-section-head--toggle {
  width: 100%;
  padding: 6px 0;
  text-align: left;
  transition: color var(--press) var(--ease-out);
}
.cap-section-head--toggle:hover { color: var(--text-dim); }
.cap-section-tail { margin-left: auto; }

.disclosure {
  flex: none;
  color: var(--text-faint);
  transition: transform var(--pop) var(--ease-out);
}
.disclosure.is-open { transform: rotate(90deg); }

/* A field plus the buttons that act on it. `.field-row` is a two-column grid,
   which stretched Apply across half the page and pushed the delete button onto
   a line of its own. */
.conn-profile-row {
  display: flex;
  align-items: flex-end;
  gap: var(--space-sm);
  margin-bottom: var(--space-md);
}
.conn-profile-row .field { flex: 1 1 auto; min-width: 0; max-width: 420px; }
.conn-profile-row .btn { flex: none; }

/* Collapsed, this is one line; it still has to read as its own band rather
   than as a caption on the section below it. */
.conn-profiles { margin-top: 0; margin-bottom: var(--space-2xl); }

@media (max-width: 560px) {
  .conn-profile-row { flex-wrap: wrap; }
  .conn-profile-row .field { flex-basis: 100%; max-width: none; }
}

.cap-cat { margin-top: 26px; }

/* The three fields a skill actually is. */
.cap-composer {
  display: grid;
  gap: 14px;
  margin-bottom: 20px;
  padding: 16px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-lg);
  background: var(--raised);
}

.cap-composer-head {
  display: flex;
  align-items: center;
  font-size: var(--text-xs);
  color: var(--text-faint);
}
.cap-composer-head .icon-btn { margin-left: auto; }
.cap-composer-foot { display: flex; gap: 8px; }
.cap-composer textarea { resize: vertical; line-height: 1.6; }

.field-note { font-size: var(--text-2xs); color: var(--text-faint); }

/* ---------------------------------------------------------- automations

   Beta, and it says so everywhere it appears. A feature that is honest about
   being unfinished can ship; one that is quietly unfinished cannot. */

.beta {
  display: inline-block;
  margin-left: 8px;
  padding: 2px 6px;
  border: 1px solid var(--confirm-line);
  border-radius: var(--r-pill);
  background: var(--confirm-soft);
  font-size: var(--text-xs);
  color: var(--confirm);
  vertical-align: middle;
}

/* --------------------------------------------------------- automations

   Tabs: Automations | Runs
   Run history chart, automation table, template grid, modals. */

.auto-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.auto-header-tabs {
  display: flex;
  gap: 4px;
}

.auto-header-tab {
  padding: 8px 16px;
  border-radius: var(--r-pill);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-dim);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}
.auto-header-tab:hover { color: var(--text); background: var(--hover); }
.auto-header-tab.is-active {
  color: var(--text);
  background: var(--raised);
  border: 1px solid var(--hairline);
}

/* -- Scheduler Banner ------------------------------------------------ */

.auto-scheduler-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  margin-bottom: 20px;
  font-size: 13px;
  color: var(--text-dim);
}
.auto-scheduler-banner--warn {
  background: var(--stop-soft);
  color: var(--stop);
  border-color: rgba(var(--stop-rgb), 0.2);
}
.auto-scheduler-banner-left {
  display: flex;
  align-items: center;
  gap: 8px;
}
.auto-scheduler-banner-right {
  display: flex;
  align-items: center;
  gap: 12px;
}
.auto-scheduler-tz {
  display: flex;
  align-items: center;
  gap: 4px;
}
.auto-scheduler-count {
  font-weight: 500;
  color: var(--text);
}

/* -- Stats Cards ----------------------------------------------------- */

.auto-stats-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  margin-bottom: 20px;
}

.auto-stats-card {
  padding: 16px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auto-stats-card-value {
  font-size: 24px;
  font-weight: 600;
  color: var(--text);
}
.auto-stats-card-value.is-good { color: var(--live); }
.auto-stats-card-value.is-warn { color: #f59e0b; }
.auto-stats-card-value.is-bad { color: var(--stop); }

.auto-stats-card-label {
  font-size: 12px;
  color: var(--text-faint);
}

/* -- Actions / Grants Editor ----------------------------------------- */

.auto-actions-hint {
  font-size: 12px;
  color: var(--text-faint);
  margin-bottom: 12px;
  line-height: 1.4;
}

.auto-actions-group {
  margin-bottom: 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  overflow: hidden;
}

.auto-actions-group-label {
  padding: 8px 12px;
  background: var(--canvas);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-dim);
  border-bottom: 1px solid var(--hairline);
}

.auto-actions-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--surface);
  border-bottom: 1px solid var(--hairline);
  cursor: pointer;
  transition: background 0.15s;
}
.auto-actions-item:last-child { border-bottom: none; }
.auto-actions-item:hover { background: var(--hover); }
.auto-actions-item.is-unavailable {
  opacity: 0.6;
  cursor: not-allowed;
}

.auto-actions-item input[type="checkbox"] {
  accent-color: var(--brand);
}

.auto-actions-item-label {
  font-size: 13px;
  color: var(--text);
  flex: 1;
}

.auto-actions-item-warn {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--stop);
  background: var(--stop-soft);
  padding: 2px 6px;
  border-radius: var(--r-sm);
}

.auto-actions-item-detail {
  font-size: 11px;
  color: var(--text-faint);
}

/* -- Run Detail Modal ------------------------------------------------ */

.auto-modal-head-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.auto-run-detail-error {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 12px;
  background: var(--stop-soft);
  color: var(--stop);
  border-radius: var(--r-md);
  font-size: 13px;
  margin-bottom: 20px;
  line-height: 1.4;
}

.auto-run-detail-meta {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin-bottom: 24px;
  padding: 16px;
  background: var(--canvas);
  border-radius: var(--r-md);
  border: 1px solid var(--hairline);
}

.auto-run-detail-meta-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auto-run-detail-meta-label {
  font-size: 11px;
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.auto-run-detail-meta-value {
  font-size: 13px;
  color: var(--text);
  font-weight: 500;
}

.auto-run-detail-section {
  margin-bottom: 24px;
}

.auto-run-detail-section-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 12px;
}

.auto-run-detail-steps {
  display: flex;
  flex-direction: column;
  gap: 1px;
  background: var(--hairline);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  overflow: hidden;
}

.auto-run-detail-step {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px;
  background: var(--surface);
}

.auto-run-detail-step-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  flex: none;
  margin-top: 2px;
}
.auto-run-detail-step.is-ok .auto-run-detail-step-icon {
  background: var(--live-soft);
  color: var(--live);
}
.auto-run-detail-step.is-fail .auto-run-detail-step-icon {
  background: var(--stop-soft);
  color: var(--stop);
}

.auto-run-detail-step-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.auto-run-detail-step-name {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
}

.auto-run-detail-step-detail {
  font-size: 12px;
  color: var(--text-dim);
  line-height: 1.4;
  word-break: break-word;
}

.auto-run-detail-step-duration {
  font-size: 11px;
  color: var(--text-faint);
  white-space: nowrap;
}

.auto-run-detail-result {
  margin: 0;
  padding: 16px;
  background: var(--canvas);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text);
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

/* -- Modified Existing Classes --------------------------------------- */

.auto-table-desc {
  display: block;
  font-size: 12px;
  color: var(--text-faint);
  margin-top: 2px;
  font-weight: normal;
}

.auto-runs-row--clickable {
  width: 100%;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
  padding: 12px 16px;
  font: inherit;
}
.auto-runs-row--clickable:hover {
  background: var(--hover);
}

.auto-run-item--clickable {
  display: flex;
  align-items: flex-start;
  width: 100%;
  padding: 12px;
  background: none;
  border: none;
  border-bottom: 1px solid var(--hairline);
  text-align: left;
  font: inherit;
  cursor: pointer;
  gap: 12px;
}
.auto-run-item--clickable:last-child {
  border-bottom: none;
}
.auto-run-item--clickable:hover {
  background: var(--hover);
}
.auto-run-arrow {
  color: var(--text-faint);
  margin-top: 2px;
}
.auto-modal-tz {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-faint);
  margin-left: auto;
}
.auto-modal-warnings {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 20px;
}
.auto-modal-warning {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--stop);
  background: var(--stop-soft);
  padding: 8px 12px;
  border-radius: var(--r-sm);
}

.auto-template-warning {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--stop);
  background: var(--stop-soft);
  padding: 2px 6px;
  border-radius: var(--r-sm);
  margin-top: 8px;
}
.auto-template-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 8px;
}
.auto-template-tag {
  font-size: 10px;
  padding: 2px 6px;
  border-radius: var(--r-sm);
  background: var(--canvas);
  border: 1px solid var(--hairline);
  color: var(--text-dim);
}

/* -- Run History Chart ----------------------------------------------- */

.run-history-card {
  padding: 20px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  margin-bottom: 20px;
}

.run-history-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.run-history-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  margin-right: 8px;
}

.run-history-subtitle {
  font-size: 12px;
  color: var(--text-faint);
}

.run-history-legend {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 12px;
  color: var(--text-dim);
}

.run-history-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}
.run-history-legend-item--muted { color: var(--text-faint); }

.run-history-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.run-history-dot--success { background: var(--live); }
.run-history-dot--failed { background: var(--stop); }

.run-history-total {
  color: var(--text-faint);
  margin-left: 4px;
}

.run-history-chart {
  overflow-x: auto;
  padding-bottom: 12px;
}

.run-history-svg {
  display: block;
}

.run-history-date-label {
  font-size: 9px;
  fill: var(--text-faint);
  font-family: var(--font-mono);
}

/* -- Automation Table ------------------------------------------------ */

.auto-table {
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  overflow: hidden;
  margin-bottom: 24px;
}

.auto-table-head {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 0.8fr 48px;
  gap: 12px;
  padding: 10px 16px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: 1px solid var(--hairline);
  background: var(--canvas);
}

.auto-table-row {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr 0.8fr 48px;
  gap: 12px;
  padding: 12px 16px;
  align-items: center;
  border-bottom: 1px solid var(--hairline);
  transition: background 0.1s ease;
}
.auto-table-row:last-child { border-bottom: none; }
.auto-table-row:hover { background: var(--hover); }
.auto-table-row.is-off { opacity: 0.6; }

.auto-table-cell {
  font-size: 13px;
  color: var(--text-dim);
  min-width: 0;
}

.auto-table-cell--name { font-weight: 500; color: var(--text); }

.auto-table-name-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  cursor: pointer;
  text-align: left;
}
.auto-table-name-btn:hover { color: var(--brand); }
.auto-table-icon { color: var(--text-faint); flex: none; }

.auto-table-cell--next { font-size: 12px; }
.auto-table-cell--schedule { font-size: 12px; }

.auto-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  padding: 2px 8px;
  border-radius: var(--r-pill);
  background: var(--canvas);
  color: var(--text-dim);
}
.auto-status-badge--running { color: var(--brand); background: var(--brand-soft); }
.auto-status-badge--ok { color: var(--live); background: var(--live-soft); }
.auto-status-badge--error { color: var(--stop); background: var(--stop-soft); }
.auto-status-badge--blocked { color: var(--confirm); background: var(--confirm-soft); }

.auto-actions-menu-wrapper { position: relative; }

.auto-actions-menu {
  position: absolute;
  right: 0;
  top: 100%;
  min-width: 140px;
  padding: 4px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--surface);
  box-shadow: 0 8px 24px rgba(0,0,0,0.2);
  z-index: 100;
}
.auto-actions-menu button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 10px;
  border: none;
  background: none;
  font-size: 13px;
  color: var(--text-dim);
  border-radius: var(--r-sm);
  cursor: pointer;
  text-align: left;
}
.auto-actions-menu button:hover { background: var(--hover); color: var(--text); }
.auto-actions-menu button.danger { color: var(--stop); }
.auto-actions-menu button.danger:hover { background: var(--stop-soft); }

/* -- Templates ------------------------------------------------------- */

.auto-templates { margin-top: 8px; }

.auto-templates-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.auto-templates-head h3 {
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
}

.auto-template-filters {
  display: flex;
  gap: 4px;
}

.auto-template-filter {
  padding: 4px 12px;
  border-radius: var(--r-pill);
  font-size: 12px;
  color: var(--text-dim);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}
.auto-template-filter:hover { color: var(--text); background: var(--hover); }
.auto-template-filter.is-active {
  color: var(--text);
  background: var(--raised);
  border: 1px solid var(--hairline);
}

.auto-template-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
}

.auto-template-card {
  padding: 16px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  transition: border-color 0.15s ease;
}
.auto-template-card:hover { border-color: var(--brand); }

.auto-template-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 10px;
}

.auto-template-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: var(--r-md);
  color: white;
}
.auto-template-icon--news { background: var(--brand); }
.auto-template-icon--productivity { background: var(--live); }
.auto-template-icon--finance { background: #f59e0b; }
.auto-template-icon--research { background: #8b5cf6; }
.auto-template-icon--lifestyle { background: #ec4899; }

.auto-template-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 4px;
}

.auto-template-desc {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.auto-template-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-faint);
}

/* -- Modals ---------------------------------------------------------- */

.auto-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 20px;
}

.auto-modal {
  width: 100%;
  max-width: 480px;
  max-height: 80vh;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-xl);
  box-shadow: 0 24px 48px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.auto-modal--wide { max-width: 560px; }

.auto-modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 1px solid var(--hairline);
}
.auto-modal-head h2 {
  font-size: 16px;
  font-weight: 600;
  color: var(--text);
}

.auto-modal-head-actions { display: flex; gap: 4px; }

.auto-modal-tabs {
  display: flex;
  gap: 4px;
}

.auto-modal-tab {
  padding: 4px 12px;
  border-radius: var(--r-pill);
  font-size: 13px;
  color: var(--text-dim);
  background: transparent;
  border: none;
  cursor: pointer;
}
.auto-modal-tab:hover { color: var(--text); }
.auto-modal-tab.is-active {
  color: var(--text);
  background: var(--raised);
  border: 1px solid var(--hairline);
}

.auto-modal-body {
  padding: 20px;
  overflow-y: auto;
  flex: 1;
}

.auto-modal-body--runs {
  padding: 12px 20px;
}

.auto-modal-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--text-dim);
  margin-bottom: 16px;
}

.auto-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--text-faint);
}
.auto-status-dot.is-active { background: var(--live); }

.auto-modal-section {
  margin-bottom: 16px;
}

.auto-modal-label {
  display: block;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-dim);
  margin-bottom: 6px;
}

.auto-schedule-row {
  display: flex;
  gap: 8px;
  align-items: center;
}

.auto-schedule-type,
.auto-schedule-value,
.auto-schedule-day {
  padding: 6px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas);
  font-size: 13px;
  color: var(--text);
}

.auto-schedule-time {
  padding: 6px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas);
  font-size: 13px;
  color: var(--text);
}

.auto-notification-select {
  width: 100%;
  padding: 6px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: var(--canvas);
  font-size: 13px;
  color: var(--text);
}

.auto-modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 20px;
  border-top: 1px solid var(--hairline);
}

.auto-modal-foot-left,
.auto-modal-foot-right {
  display: flex;
  gap: 8px;
}

/* -- Runs Tab -------------------------------------------------------- */

.auto-runs-tab { }

.auto-runs-table {
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  overflow: hidden;
}

.auto-runs-table-head {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 12px;
  padding: 10px 16px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  border-bottom: 1px solid var(--hairline);
  background: var(--canvas);
}

.auto-runs-row {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 12px;
  padding: 10px 16px;
  align-items: center;
  border-bottom: 1px solid var(--hairline);
  font-size: 13px;
}
.auto-runs-row:last-child { border-bottom: none; }

.auto-runs-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-dim);
}
.auto-runs-status--success { color: var(--live); }
.auto-runs-status--failed { color: var(--stop); }
.auto-runs-status--running { color: var(--brand); }

.auto-runs-summary {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 300px;
}

.auto-runs-auto-name {
  color: var(--text-dim);
  font-size: 12px;
}

.auto-runs-duration {
  color: var(--text-dim);
  font-size: 12px;
}

.auto-runs-time {
  color: var(--text-faint);
  font-size: 12px;
  font-family: var(--font-mono);
}

.auto-runs-loading,
.auto-runs-empty {
  padding: 40px;
  text-align: center;
  color: var(--text-faint);
  font-size: 13px;
}

.auto-runs-list {
  display: flex;
  flex-direction: column;
}

.auto-run-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 0;
  border-bottom: 1px solid var(--hairline);
}
.auto-run-item:last-child { border-bottom: none; }

.auto-run-status {
  flex: none;
  width: 20px;
  height: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  font-size: 10px;
}
.auto-run-status--success { color: var(--live); background: var(--live-soft); }
.auto-run-status--failed { color: var(--stop); background: var(--stop-soft); }
.auto-run-status--running { color: var(--brand); background: var(--brand-soft); }

.auto-run-info { flex: 1; min-width: 0; }

.auto-run-summary {
  display: block;
  font-size: 13px;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.auto-run-meta {
  display: block;
  font-size: 11px;
  color: var(--text-faint);
  margin-top: 2px;
}

@media (max-width: 720px) {
  .auto-table-head,
  .auto-table-row {
    grid-template-columns: 1fr 48px;
  }
  .auto-table-cell--schedule,
  .auto-table-cell--next,
  .auto-table-cell--status {
    display: none;
  }
  .auto-template-grid {
    grid-template-columns: 1fr;
  }
  .auto-runs-table-head,
  .auto-runs-row {
    grid-template-columns: 1fr;
  }
  .auto-runs-auto-name,
  .auto-runs-time {
    display: none;
  }
}

/* --------------------------------------------------------- pinned messages

   A pin is a bookmark in a transcript that scrolls, and nothing more: it is not
   sent to the model, does not change what is recalled, and does not reorder
   history. The strip is what makes it worth having -- a pin you cannot get back
   to is a mark on a page nobody turns to. */

.pin-strip {
  flex: none;
  border-bottom: 1px solid var(--hairline);
  background: var(--canvas-deep);
}

.pin-strip-head {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 24px;
  font-size: var(--text-xs);
  color: var(--text-faint);
}
.pin-strip-head:hover { color: var(--text-dim); }
.pin-strip-caret { margin-left: auto; transition: transform var(--press) var(--ease-out); }
.pin-strip.open .pin-strip-caret { transform: rotate(90deg); }

.pin-strip-list {
  display: flex;
  gap: 6px;
  padding: 0 24px 10px;
  overflow-x: auto;
  scrollbar-width: none;
}
.pin-strip-list::-webkit-scrollbar { display: none; }

.pin-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: 340px;
  padding: 6px 8px 6px 10px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-pill);
  background: var(--raised);
  font-size: 12px;
  color: var(--text-dim);
  white-space: nowrap;
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.pin-chip:hover { background: var(--surface); color: var(--text); }
.pin-chip-who {
  font-size: var(--text-xs);
  color: var(--text-faint);
  flex: none;
}
.pin-chip-text { overflow: hidden; text-overflow: ellipsis; }
.pin-chip-off { color: var(--text-faint); line-height: 0; flex: none; }
.pin-chip-off:hover { color: var(--text); }

.msg-pin.is-pinned { color: var(--confirm); }

/* A pinned message says so without a badge: the mark is already in its header,
   and the rule down the margin is what you look for when scrolling back. */
.msg.is-pinned { border-left: 2px solid var(--confirm-line); padding-left: 12px; }

/* Where a jump from the strip lands. Background only, so nothing moves. */
.stream-item.is-flash { animation: pin-flash 1.2s var(--ease-out); border-radius: var(--r-md); }
@keyframes pin-flash {
  from { background: var(--confirm-soft); }
  to { background: transparent; }
}

/* ------------------------------------------------- catalogue cards and rows

   These were the directory overlay's, and they are the same cards now that the
   catalogue lives on the page that manages what it adds. */

.dir-install {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 8px 12px;
  margin-bottom: 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--canvas-deep);
  color: var(--text-faint);
}
.dir-install:focus-within { border-color: var(--hairline-strong); background: var(--canvas); }

.dir-install input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: none;
  color: var(--text);
  font-family: var(--font-body);
  font-size: 13.5px;
}

.dir-install { margin-bottom: 18px; }

.dir-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(316px, 1fr));
  gap: 12px;
}

/* One tile per thing that can be added: mark, name, who publishes it, what it
   does, and the single button that adds it. */
.dcard {
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 14px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: rgb(var(--tint) / 0.018);
  transition: border-color var(--press) var(--ease-out), background var(--press) var(--ease-out);
}
.dcard:hover { border-color: var(--hairline-strong); background: rgb(var(--tint) / 0.035); }

.dcard-top { display: flex; align-items: flex-start; gap: 11px; }
.dcard-heading { flex: 1; min-width: 0; display: grid; gap: 2px; }
.dcard-title { font-size: 14px; font-weight: 500; color: var(--text); }
.dcard-sub { font-size: 11.5px; color: var(--text-faint); }

.dcard-desc {
  margin: 0;
  font-size: 12.5px;
  line-height: 1.55;
  color: var(--text-dim);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.dcard-badges { display: flex; flex-wrap: wrap; gap: 6px; }

.dcard-act {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  flex: none;
  border: 1px solid var(--hairline);
  border-radius: var(--r-pill);
  color: var(--text-dim);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out),
              border-color var(--press) var(--ease-out);
}
.dcard-act:hover:not(:disabled) { background: rgb(var(--tint) / 0.08); color: var(--text); border-color: var(--hairline-strong); }
.dcard-act:disabled { opacity: 0.5; cursor: default; }
.dcard-act--done { color: var(--live); border-color: var(--live-line); }

.dcard-gear-wrap { position: relative; flex: none; }

.dcard-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 5;
  width: 160px;
  padding: 5px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-lg);
  background: var(--raised);
  box-shadow: var(--lift);
}

/* the coloured tile a service mark sits on */
.svc {
  display: grid;
  place-items: center;
  border-radius: var(--r-md);
  flex: none;
  overflow: hidden;
}
.svc--generic {
  background: rgb(var(--tint) / 0.07);
  color: var(--text-dim);
  font-family: var(--font-display);
  font-weight: 600;
}

/* Every tile is the same neutral surface now, so a row of them reads as one
   family rather than as fifteen brand colours competing for the same list.
   The mark inside carries the brand; the tile carries the layout. */
.svc--brand, .svc--primitive {
  background: rgb(var(--tint) / 0.055);
  border: 1px solid var(--hairline);
}
.svc--primitive { color: var(--text-dim); }

/* The published path data, painted in `color` through a mask. An `<img>` would
   be the brand's own black on a black console; a mask keeps the geometry and
   hands the colour back. */
.svc-mark {
  display: block;
  background: currentColor;
  -webkit-mask: var(--svc-mask) center / contain no-repeat;
  mask: var(--svc-mask) center / contain no-repeat;
}

.dir-empty { grid-column: 1 / -1; padding: 30px 10px; text-align: center; color: var(--text-faint); font-size: 13px; }
.dir-empty--quiet { padding: 6px 10px; text-align: left; font-size: var(--text-2xs); }

/* ------------------------------------------------------------- settings */

.settings {
  width: min(920px, calc(100vw - 40px));
  height: min(680px, calc(100vh - 80px));
  display: flex;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-xl);
  background: var(--raised);
  box-shadow: var(--lift);
  overflow: hidden;
  animation: modal-in var(--modal) var(--ease-out);
}

/* The scrollable panel sits on a ground one step below the sheet the dialog
   is drawn from, the way a system settings pane recedes behind its list.
   The scroll therefore happens on the recessed ground rather than on the
   sheet's own edge, and a card scrolling past the header reads as passing
   under it rather than being clipped by it. */
.set-content { flex: 1; min-width: 0; display: flex; flex-direction: column; background: var(--canvas-deep); }

.set-nav {
  width: 210px;
  flex: none;
  display: flex;
  flex-direction: column;
  padding: 14px 10px 0;
  border-right: 1px solid var(--hairline);
  overflow-y: auto;
}

/* The nav's own name, in the same quiet voice the cards use for theirs. */
.set-nav > .set-nav-group:first-child { padding-top: 4px; }

.set-nav-group {
  padding: 16px 11px 5px;
  font-size: var(--text-3xs);
  font-weight: 500;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: var(--text-faint);
}

.set-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 11px;
  border-radius: var(--r-sm);
  font-size: var(--text-xs);
  color: var(--text-dim);
  text-align: left;
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.set-nav-item:hover { background: rgb(var(--tint) / 0.05); color: var(--text); }

/* The active item is ink on the raised sheet -- the filled treatment the
   modes get -- rather than a tint, so it carries at a glance and stays
   legible with the label hidden on narrow screens. */
.set-nav-item.active { background: var(--accent); color: var(--on-accent); }

.set-nav-label { flex: 1; min-width: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* These leave the dialog for a full view rather than selecting a panel inside
   it, and the caret is the only thing that says so before it happens. */
.set-nav-item--away .set-nav-away { margin-left: auto; opacity: 0.4; }
.set-nav-item--away:hover .set-nav-away { opacity: 0.8; }

/* The build's own name and version, pinned to the foot of the nav. Mono at
   metadata size: this is a fact about the machine, not a heading. */
.set-nav-foot {
  margin-top: auto;
  padding: 12px 11px 12px;
  border-top: 1px solid var(--hairline);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  color: var(--text-faint);
  white-space: nowrap;
}

.set-head {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 20px;
  border-bottom: 1px solid var(--hairline);
  /* The header stays the raised sheet the nav is drawn on, so the recessed
     panel ground begins below it rather than behind the title. */
  background: var(--raised);
}
.set-title { font-family: var(--font-serif); font-size: var(--text-lg); font-weight: 500; letter-spacing: -0.01em; }
.set-head .icon-btn { margin-left: auto; }

/* The scroll and the padding live on the frame, not the panel, so the keyed
   entrance below has one element to animate and any panel is just cards. */
.set-panel-frame { flex: 1; min-height: 0; overflow-y: auto; padding: 20px 22px 26px; }
.set-panel { min-height: 100%; }

/* Keyed by section, so this runs on every switch: a fresh panel rises a
   step and settles, faster than the dialog's own entrance so the two read
   as object-then-content rather than two doors opening at once. Off for
   anyone who asked the system for stillness. */
@keyframes set-panel-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.set-panel-frame { animation: set-panel-in var(--menu) var(--ease-out); }
@media (prefers-reduced-motion: reduce) {
  .set-panel-frame { animation: none; }
}

.set-panel h3 {
  margin: 22px 0 8px;
  font-size: var(--text-xs);
  font-weight: 400;
  color: var(--text-faint);
}
.set-panel h3:first-child { margin-top: 0; }

.set-note { margin: 0 0 12px; font-size: 12.5px; line-height: 1.6; color: var(--text-faint); }

.set-rows { display: grid; gap: 1px; margin-bottom: 6px; }

.set-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 12px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: rgb(var(--tint) / 0.015);
  font-size: 13px;
  color: var(--text);
}
.set-row > span:first-child { flex: 1; min-width: 0; }
.set-row > span:last-child:not(:first-child) { color: var(--text-dim); font-size: 12.5px; }
.set-row-tail { display: flex; align-items: center; gap: 8px; }
.set-sub { display: block; margin-top: 2px; font-size: 11.5px; color: var(--text-faint); }
/* A row whose control is a form rather than a switch: the two fields and the
   button need the full width, so the row stops being a line and becomes a
   block instead of squeezing three inputs into a tail. */
.set-row--stack { flex-direction: column; align-items: stretch; }
.lib-relay-form { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
.lib-relay-form .lib-input { flex: 1; min-width: 200px; }
.set-ok { color: var(--live); }
.set-bad { color: var(--stop); }

/* The add-a-provider form, inline in the panel rather than in a modal: it is
   a continuation of the list above it, and a dialog over a dialog would put
   the thing you were reading behind the thing you are filling in. It draws
   as a card like its neighbours, one step warmer than the panel ground --
   an active piece of work rather than another row to read. */
.set-subpanel {
  padding: 16px;
  margin-bottom: 22px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--raised);
  box-shadow: var(--lift);
}
.set-subpanel h3 { margin: 0 0 8px; font-size: var(--text-3xs); font-weight: 500; letter-spacing: 0.07em; text-transform: uppercase; color: var(--text-faint); }
.set-subpanel .set-note { margin-bottom: 12px; }
.set-subpanel .set-inline { margin-bottom: 0; }

.set-inline { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; flex-wrap: wrap; }
.set-inline input, .set-inline select {
  flex: 1;
  min-width: 160px;
  padding: 7px 11px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-sm);
  background: var(--canvas-deep);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 13px;
  outline: none;
}

.set-links { display: flex; gap: 8px; margin-top: 14px; flex-wrap: wrap; }
.set-empty { padding: 14px 16px; font-size: var(--text-xs); color: var(--text-faint); }

.set-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.set-table th {
  padding: 6px 10px;
  text-align: left;
  font-weight: 400;
  font-size: var(--text-xs);
  color: var(--text-faint);
  border-bottom: 1px solid var(--hairline);
}
.set-table td { padding: 10px; border-bottom: 1px solid var(--hairline); color: var(--text-dim); }
.set-table td:first-child { color: var(--text); }
.set-table-actions-inner { display: flex; gap: 6px; justify-content: flex-end; align-items: center; }

/* ------------------------------------------------- composer, second pass */

.composer { padding: 6px; }

/* On the front page the composer is the subject, not a footer. It gets real
   height so the page has an object in the middle of it rather than a strip,
   and the control row sits on its own rule -- the field above is a document,
   the row below is a panel, and they should not read as one surface.

   `min-height` on the wrapper rather than the textarea: the textarea grows
   itself as you type, and giving it the floor would fight that logic. */
.composer-wrap--hero .composer { padding: 8px; }

.composer-wrap--hero .composer textarea {
  min-height: 92px;
  padding: 14px 14px 10px;
  font-size: 16px;
}

.composer-wrap--hero .composer-bar {
  margin-top: 2px;
  padding-top: 10px;
  border-top: 1px solid var(--hairline);
}

/* The field and its measuring mirror have to agree on every property that
   moves a glyph, or the caret lands in the wrong place. They are declared
   together for exactly that reason -- editing one without the other is the
   way this breaks. */
.composer textarea,
.composer .skiper106-mirror {
  width: 100%;
  padding: 14px 16px 2px;
  border: none;
  font-family: var(--font-body);
  font-size: 15px;
  line-height: 1.6;
  letter-spacing: normal;
}

.composer textarea {
  min-height: 48px;
  outline: none;
  background: transparent;
  color: var(--text);
  resize: none;
}
.composer textarea::placeholder { color: var(--text-faint); }
.composer textarea:focus-visible { box-shadow: none; }

/* The count of live connectors, riding on the + chip. Mono and tabular,
   because it is a number that changes under you. */
.composer-chip-count {
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--text-dim);
}
.composer-chip.active .composer-chip-count { color: var(--text); }

.composer-bar { display: flex; align-items: center; gap: 8px; padding: 4px 8px 6px; }
.composer-bar-right { margin-left: auto; display: flex; align-items: center; gap: 8px; }

.composer-modes {
  display: flex;
  gap: 2px;
  padding: 2px;
  border-radius: var(--r-md);
  background: rgb(var(--tint) / 0.05);
}

/* Which mode the next message runs in is a real state, so the active one is
   filled -- ink on paper, the primary treatment -- rather than tinted. */
.mode {
  padding: 4px 12px;
  border-radius: var(--r-sm);
  font-size: var(--text-xs);
  color: var(--text-faint);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.mode.active { background: var(--accent); color: var(--on-accent); }

/* A model id is machine metadata, not a label someone wrote, so it is set in
   the mono face at metadata size -- the same treatment file paths and tool
   names get everywhere else in the interface. */
.composer-model {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 9px;
  border-radius: var(--r-md);
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  color: var(--text-faint);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.composer-model:hover, .composer-model.active { background: rgb(var(--tint) / 0.06); color: var(--text-dim); }

/* A model id is arbitrary-length text next to a fixed-width send button, so it
   is the thing that gives. Without this the name wrapped to three lines and
   pushed Send off the edge of the composer on a phone. */
.composer-model {
  min-width: 0;
  max-width: 22ch;
  white-space: nowrap;
  overflow: hidden;
}
.composer-model > svg { flex: none; }

/* Below this the four controls stop fitting on one line together. The modes
   take their own row rather than being scrolled or truncated: which mode the
   next message runs in is not something to make someone hunt for. */
@media (max-width: 520px) {
  .composer-bar {
    display: grid;
    grid-template-columns: auto 1fr auto;
    grid-template-areas: 'modes modes modes' 'plus . right';
    gap: var(--space-xs) var(--space-sm);
  }
  .composer-modes { grid-area: modes; justify-content: stretch; }
  .composer-modes .mode { flex: 1; text-align: center; padding: 6px 4px; }
  .composer-chip { grid-area: plus; justify-self: start; }
  .composer-bar-right { grid-area: right; margin-left: 0; }
  .composer-model { max-width: min(38vw, 18ch); }
}

.composer-files { display: flex; flex-wrap: wrap; gap: 6px; padding: 10px 12px 2px; }

.file-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  border: 1px solid var(--hairline);
  border-radius: 99px;
  background: rgb(var(--tint) / 0.03);
  font-size: 12px;
  color: var(--text-dim);
}
.file-chip-size { font-size: var(--text-2xs); color: var(--text-faint); }
.file-chip button { color: var(--text-faint); line-height: 0; }
.file-chip button:hover { color: var(--stop); }

.hero-mark { color: var(--stop); margin-right: 8px; }
.hero-stack .hero-hints { margin-top: 18px; }

.chat-main { flex: 1; min-width: 0; display: flex; flex-direction: column; min-height: 0; position: relative; }
.chat-banner { margin: 8px 26px 0; }
/* The dismiss affordance on a health banner. Ghost until hovered so it never
   competes with the banner's primary action, but always reachable. */
.chat-banner-dismiss {
  display: inline-flex; align-items: center; justify-content: center;
  width: 24px; height: 24px; margin-left: 4px; padding: 0;
  border: none; border-radius: var(--r-sm);
  background: transparent; color: var(--text-faint);
  cursor: pointer; flex: none;
}
.chat-banner-dismiss:hover { background: rgb(var(--tint) / 0.08); color: var(--text); }
.chat-banner-dismiss:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

/* A line at the top of the transcript saying why it is empty.

   An open conversation holding no messages, and one whose messages could not
   be fetched, used to render exactly like no conversation at all -- the
   landing hero. Opening a row from the history column and being shown the
   front page reads as navigation that failed, so each of those two states now
   says which one it is, inside the transcript rather than instead of it. */
.chat-note {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin: 0 0 var(--space-md);
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  background: rgb(var(--tint) / 0.03);
  color: var(--text-dim);
  font-size: var(--text-xs);
  line-height: var(--leading-normal);
}
.chat-note > svg { flex: none; color: var(--text-faint); }
.chat-note strong { color: var(--text); font-weight: 500; }
.chat-note .btn { margin-left: auto; flex: none; }
.chat-note--bad {
  border-color: var(--stop-line);
  background: var(--stop-soft);
  color: var(--text);
}
.chat-note--bad > svg { color: var(--stop); }

/* A heading with an action to its right (Providers · Ping all). */
.set-head-row {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
}
.set-head-row h3 { margin-bottom: 6px; }

/* One role assignment: label + hint above, provider/model controls below. */
.set-role-row {
  display: grid; gap: 6px;
  padding: 12px 0; border-bottom: 1px solid var(--hairline);
}
.set-role-row:last-child { border-bottom: none; }
.set-role-head { display: flex; flex-direction: column; gap: 2px; }
.set-role-controls { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.set-role-controls select, .set-role-controls input {
  flex: 1; min-width: 150px;
  padding: 7px 11px;
  border: 1px solid var(--hairline); border-radius: var(--r-sm);
  background: var(--canvas-deep); color: var(--text);
  font-family: var(--font-body); font-size: 13px; outline: none;
}
.set-role-controls select:focus, .set-role-controls input:focus { border-color: var(--accent); }

/* ------------------------------------------------------ settings, this pass

   The panel takes the shape of the system settings panels it sits beside in
   a person's memory: inset groups on a raised sheet, one card per concern,
   hairline dividers between rows inside a card rather than borders around
   each one. A row that draws its own box reads as a control; a row divided
   from its neighbours reads as an item in a list, which is what these are.

   The headings step back to become eyebrows: a card is named once, above
   it, in the quietest type in the system -- uppercase, letter-spaced, faint
   -- so the list under it is what the eye lands on. */

.set-card {
  padding: 0;
  margin-bottom: 32px;
  border: none;
  background: transparent;
}
.set-rows {
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: var(--canvas-deep);
  overflow: hidden;
}
.set-panel .set-card > h3:first-child,
.set-card > .set-head-row:first-child { margin: 14px 16px 8px; }

/* Rows inside a card lose their own boxes and gain dividers. The first and
   last keep the card's rounding, and the stray 1px grid gap that used to
   show the canvas through between rows is gone with it. */
.set-card .set-rows { gap: 0; margin-bottom: 0; }
.set-card .set-row,
.set-card .set-role-row {
  border: none;
  border-bottom: 1px solid var(--hairline);
  border-radius: 0;
  background: transparent;
  padding: 10px 16px;
}
.set-card .set-rows .set-row:last-child,
.set-card .set-role-row:last-child { border-bottom: none; }

/* The eyebrow: a card's name, in the quietest voice. */
.set-panel > h3,
.set-panel .set-card-label,
.set-card-label {
  margin: 0 0 12px 4px;
  font-size: 13px;
  font-weight: 400;
  color: var(--text-dim);
}

/* Prose that introduces a card sits inside its padding, so it reads as
   spoken by the card rather than floating above it. */
.set-card > .set-note { padding: 0 16px 10px; }

/* Inline forms and their inputs sit inside the card's padding too; the
   rule's own bottom margin stays so stacked rows keep their rhythm. */
.set-card .set-inline { padding: 0 16px; }

/* A caption pinned to the foot of a card, for the thing that is true of
   everything in it ("the adapter is resolved fresh every turn"). */
.set-card-foot {
  padding: 9px 16px 4px;
  font-size: var(--text-2xs);
  line-height: 1.5;
  color: var(--text-faint);
  border-top: 1px solid var(--hairline);
}

/* ------------------------------------------------------------- the switch

   A pill track and a travelling knob: on is filled with the live green, off
   is a recessed well. The 4px system radius is deliberately broken here and
   only here -- a switch's roundness is what makes it read as a switch, the
   one shape in the interface that carries its own affordance. Green over
   ink-hairline, never a tint fill, because a switch that is half-there is
   a switch nobody can trust at a glance. */

.switch {
  position: relative;
  flex: none;
  width: 32px;
  height: 18px;
  padding: 0;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-pill, 9999px);
  background: var(--surface-3);
  cursor: pointer;
  transition: background-color var(--pop) var(--ease-out),
              border-color var(--pop) var(--ease-out);
}
.switch:disabled { opacity: 0.45; cursor: default; }

.switch-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ffffff;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.25);
  transition: transform var(--pop) var(--ease-out),
              background-color var(--pop) var(--ease-out);
}

.switch.is-on,
.switch.on {
  border-color: var(--live);
  background: var(--live);
}
.switch.is-on .switch-knob,
.switch.on .switch-knob {
  transform: translateX(14px);
  background: #ffffff;
}

.switch:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--canvas), 0 0 0 4px var(--focus-ring);
}

/* A number that came off the wire, set so its digits hold still while it
   changes under you. */
.set-ms {
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
  color: var(--text-dim);
}
.badge--ok .set-ms, .set-ms--live { color: var(--live); }


/* -------------------------------------------- the backdrop, below 860px

   The drawer itself is drawn with the workbench, because below this width the
   marks and the history slide in together as one object rather than as two
   columns. What is left here is what sits behind it. */

@media (max-width: 859.98px) {
  .rail-scrim {
    position: fixed;
    inset: 0;
    z-index: 40;
    width: 100%;
    border: none;
    background: var(--scrim);
    backdrop-filter: blur(2px);
    animation: fade-in var(--menu) var(--ease-out);
    cursor: default;
  }
  .rail-scrim:active { transform: none; }

  .set-nav { width: 56px; }
  /* Labels go, icons stay: the rail is still navigable with one hand, and
     the pinned version line stays meaningful because it is the one string
     short enough not to ellipsize at this width. */
  .set-nav .set-nav-label { display: none; }
  .set-nav-group { text-align: center; padding-inline: 0; }
  .set-nav-item { justify-content: center; padding: 8px 0; }
  .set-nav-item--away .set-nav-away { display: none; }
  .set-nav-foot { font-size: 0; }
  .set-nav-foot::first-letter { font-size: var(--text-3xs); }
}

/* A drawer that slides is a drawer that moves; anyone who asked for stillness
   gets it appearing and disappearing instead, which is still legible. */
@media (max-width: 859.98px) and (prefers-reduced-motion: reduce) {
  .wb--compact .wb-rail,
  .wb--compact .wb-list { transition: none; }
}

/* A submenu of a submenu opens beside its parent, not on top of it. */
.menu-flyout--nested { left: calc(100% + 6px); top: 0; bottom: auto; }
.menu--right .menu-flyout--nested { left: auto; right: calc(100% + 6px); }

/* ------------------------------------------------------------ connectors */

.view-inner--wide { max-width: 1120px; }

.conn-section-title {
  margin-bottom: 10px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-dim);
}

.conn-popular { margin-bottom: 22px; }

.conn-popular-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 10px;
}

.conn-pop {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 11px 13px;
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  background: rgb(var(--tint) / 0.018);
}
.conn-pop:hover { border-color: var(--hairline-strong); }
.conn-pop-name { flex: 1; min-width: 0; font-size: 13.5px; }

.conn-tabs { display: flex; align-items: center; gap: 4px; margin-bottom: 12px; }

.conn-tab {
  padding: 5px 13px;
  border-radius: 99px;
  font-size: 12.5px;
  color: var(--text-faint);
  transition: background var(--press) var(--ease-out), color var(--press) var(--ease-out);
}
.conn-tab:hover { color: var(--text-dim); }
.conn-tab.active { background: rgb(var(--tint) / 0.09); color: var(--text); }
.conn-count { margin-left: auto; font-size: var(--text-2xs); color: var(--text-faint); }

.conn-table { width: 100%; table-layout: fixed; border-collapse: collapse; font-size: 13px; }
.conn-table th:nth-child(2), .conn-table td:nth-child(2) { width: 130px; }
.conn-table th:nth-child(3), .conn-table td:nth-child(3) { width: 190px; }
.conn-table th:nth-child(4), .conn-table td:nth-child(4) { width: 240px; }

.conn-table th {
  padding: 10px 14px;
  text-align: left;
  font-weight: 400;
  font-size: var(--text-xs);
  color: var(--text-faint);
  border-bottom: 1px solid var(--hairline);
}

.conn-table td { padding: 11px 14px; border-bottom: 1px solid var(--hairline); vertical-align: middle; }
.conn-table tr:last-child td { border-bottom: none; }
.conn-table tr.is-open td { background: rgb(var(--tint) / 0.02); }

.conn-name { display: flex; align-items: center; gap: 11px; color: var(--text); min-width: 0; }
.conn-name > span { min-width: 0; }
.conn-target {
  display: block;
  margin-top: 2px;
  font-size: 10.5px;
  color: var(--text-faint);
  max-width: 320px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.conn-type { color: var(--text-dim); font-size: 11.5px; }
.conn-status { display: inline-flex; align-items: center; gap: 7px; color: var(--text-dim); }
.conn-status--live { color: var(--live); }
.conn-status--error { color: var(--stop); }
.conn-status--off { color: var(--text-faint); }
.conn-error {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin-top: 3px;
  font-size: 11px;
  line-height: 1.45;
  color: var(--stop);
}
.conn-actions-inner {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
  align-items: center;
  flex-wrap: wrap;
}
.conn-actions .btn { white-space: nowrap; }
.conn-table tbody tr:hover td { background: rgb(var(--tint) / 0.022); }
.conn-empty { padding: 26px 14px; text-align: center; color: var(--text-faint); }

.conn-setup-row td { padding: 0 14px 16px; }
.conn-setup { display: grid; gap: 14px; padding-top: 4px; }
.conn-setup-block { overflow: hidden; margin-bottom: 24px; }
.conn-setup-title {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 0 16px 0;
  font-size: 14px;
  font-weight: 600;
  color: var(--text);
}
.conn-setup-note { margin: 10px 14px 0; font-size: 12px; line-height: 1.6; color: var(--text-faint); }
.conn-foot { margin-top: 16px; font-size: 12px; color: var(--text-faint); }

.conn-setup-steps {
  margin: 0 0 16px;
  padding: 16px;
  border-radius: var(--r-md);
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1.7;
  color: var(--text-dim);
  white-space: pre-wrap;
  overflow-x: auto;
}
.conn-setup-block > .field-row { padding: 0 0 16px; }
.conn-setup-block > div:last-child { padding: 0; }
.conn-check {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 12px 14px 0;
  font-size: var(--text-xs);
  color: var(--text-dim);
}
.conn-check input { accent-color: var(--confirm); }

/* A connector as a row you open, rather than a row of four controls.
   The list answers "is it running"; opening it answers everything else. */
.conn-list { display: flex; flex-direction: column; }
.conn-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 13px 15px;
  border: none;
  border-bottom: 1px solid var(--hairline);
  background: none;
  text-align: left;
  color: var(--text);
  cursor: pointer;
  transition: background var(--press) var(--ease-out);
}
.conn-list .conn-row:last-child { border-bottom: none; }
.conn-row:hover { background: rgb(var(--tint) / 0.022); }
.conn-row-text { flex: 1; min-width: 0; display: grid; gap: 2px; }
.conn-row-name { font-size: 14px; }
.conn-row-sub {
  font-size: 11.5px;
  color: var(--text-faint);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.conn-row-chevron { flex: none; color: var(--text-faint); opacity: 0.6; }
.conn-row .conn-status { flex: none; font-size: 12px; }

/* One connector, opened. */
.conn-detail {
  position: relative;
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  padding: 30px 20px 80px;
  display: flex;
  flex-direction: column;
  gap: 40px;
}

/* 1. Back Button */
.conn-back {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: var(--text-dim);
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 6px 12px;
  margin-left: -12px;
  border-radius: 99px;
  transition: color 0.2s, background 0.2s;
}
.conn-back:hover {
  color: var(--text);
  background: rgba(var(--tint) / 0.05);
}

/* Header Row (Icon, Title, Actions) */
.conn-detail-header-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 8px;
}
.conn-detail-title-col {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
}
.conn-detail-app-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
}
.conn-detail-title-col h2 {
  font-size: var(--text-2xl);
  font-weight: 700;
  letter-spacing: var(--track-title);
  color: var(--text);
  margin: 0;
  line-height: 1.2;
}
.conn-detail-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.conn-detail-desc {
  font-size: 14px;
  color: var(--text-dim);
  margin: 0 0 24px;
  line-height: 1.5;
}

/* 2. Clean Hero Area */
.conn-detail-hero-box {
  position: relative;
  width: 100%;
  border-radius: var(--r-xl, 16px);
  padding: 32px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 24px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  overflow: hidden;
}

/* 3. Floating Prompt Pills */
.plugin-prompt-pill {
  display: flex;
  align-items: center;
  max-width: calc(100% - 4px);
  width: 100%;
  background: var(--canvas);
  border: 1px solid var(--hairline);
  border-radius: var(--r-pill, 9999px);
  padding: 10px 16px;
  text-align: left;
  font-size: 13.5px;
  line-height: 20px;
  color: var(--text);
  cursor: pointer;
  gap: 12px;
  transition: border-color 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
  text-decoration: none;
  z-index: 1;
}
@media (min-width: 640px) {
  .plugin-prompt-pill {
    max-width: 556px;
  }
}
.plugin-prompt-pill:hover {
  background: var(--surface-2);
  border-color: var(--hairline-strong);
}
.plugin-prompt-pill-text {
  flex: 1;
  min-width: 0;
  word-wrap: break-word;
}
.plugin-prompt-pill-text strong {
  font-weight: 600;
  margin-right: 4px;
}
.plugin-prompt-pill-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: var(--r-pill);
  background: var(--raised);
  color: var(--text);
  box-shadow: var(--shadow-micro);
}

/* 4. Sections */
.conn-detail-section {
  margin-bottom: 32px;
}
.conn-detail-section > p {
  font-size: 13px;
  color: var(--text-dim);
  line-height: 1.5;
  margin: 0 0 24px;
}
.conn-detail-section h3 {
  font-size: var(--text-sm);
  font-weight: 600;
  color: var(--text);
  margin: 0 0 16px;
}

/* 5. Apps List inside Details */
.conn-detail-apps {
  display: flex;
  flex-direction: column;
}
.conn-detail-app-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px 0;
  border-bottom: 1px solid var(--hairline);
}
.conn-detail-app-row:last-child {
  border-bottom: none;
}
.conn-detail-app-row-icon {
  width: 32px;
  height: 32px;
  border-radius: 6px;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
}
.conn-detail-app-row-name {
  font-size: var(--text-sm);
  color: var(--text);
  flex: 1;
}

/* 6. Information Table */
.conn-info-table {
  width: 100%;
  border-collapse: collapse;
}
.conn-info-table tr {
  border-bottom: 1px solid var(--hairline);
}
.conn-info-table tr:last-child {
  border-bottom: none;
}
.conn-info-table td {
  padding: 16px 0;
  font-size: 13px;
  vertical-align: top;
}
.conn-info-label {
  width: 120px;
  color: var(--text-dim);
}
.conn-info-val {
  color: var(--text);
}
.conn-info-val a {
  color: var(--text);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  text-decoration: none;
}
.conn-info-val a:hover {
  text-decoration: underline;
}

/* 7. Footer Disclaimers */
.conn-detail-footer {
  font-size: 12px;
  color: var(--text-dim);
  line-height: 1.5;
  border-top: 1px solid var(--hairline);
  padding-top: 24px;
}
.conn-detail-footer a {
  color: var(--text);
