/* Skiper106 Smooth Caret Input */
.skiper106-wrap {
  flex: 1;
  min-width: 0;
}

.skiper106-container {
  position: relative;
  display: flex;
  align-items: center;
}

.skiper106-input {
  width: 100%;
  border: none;
  background: transparent;
  color: var(--text);
  font-family: inherit;
  font-size: 13px;
  outline: none;
  padding: 2px 0;
}

.skiper106-input::placeholder {
  color: var(--text-faint);
}

.skiper106-measure {
  pointer-events: none;
  visibility: hidden;
  position: absolute;
  top: 0;
  left: 0;
  white-space: pre;
  font-family: inherit;
  font-size: 13px;
}

/* Centred with a margin rather than a translate: the component drives this
   element's `transform` from motion values, so anything written here under
   that property is overwritten on the first frame. */
.skiper106-caret {
  pointer-events: none;
  position: absolute;
  top: 50%;
  left: 0;
  width: 2px;
  height: 14px;
  margin-top: -7px;
  background: var(--ember);
  border-radius: 1px;
}

/* ---- skiper 106: the multi-line variant --------------------------------
   The mirror is the measurement. It is a copy of the textarea's layout holding
   the text up to the caret, so the marker span inside it lands exactly where
   the real caret is -- including after a wrap, which is the case the prefix-
   width trick in the single-line version cannot answer. */

.skiper106-wrap--area,
.skiper106-container--area {
  display: block;
  width: 100%;
}

.skiper106-container--area { position: relative; }

.skiper106-textarea {
  display: block;
  width: 100%;
}

/* Only while the synthetic one is on screen. Reduced motion and coarse
   pointers keep the real caret and never get this class. */
.skiper106-textarea--synthetic-caret,
.skiper106-input--synthetic-caret { caret-color: transparent; }

.skiper106-mirror {
  pointer-events: none;
  position: absolute;
  top: 0;
  left: 0;
  visibility: hidden;
  white-space: pre-wrap;
  overflow-wrap: break-word;
  word-break: break-word;
}

.skiper106-caret--area {
  top: 0;
  margin-top: 0;
  transform-origin: top left;
}

/* Scroll area & Skiper87 */
.sb-scroll-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 8px 0 16px;
}

.skiper87-scroll-area {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--hairline) 60%, transparent) transparent;
}

.skiper87-scroll-area::-webkit-scrollbar {
  width: 4px;
}

.skiper87-scroll-area::-webkit-scrollbar-thumb {
  background: color-mix(in srgb, var(--hairline) 60%, transparent);
  border-radius: var(--radius-md);
}

/* Skiper40 Nav Items */
.sb-places-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 12px 16px;
  border-bottom: 1px solid var(--hairline);
}

/* ---- skiper 40: animated links -----------------------------------------
   The component ships these class names and no stylesheet, so this is where
   they are defined. Two treatments, both built on a pseudo-element rule that
   grows from one edge -- no layout shift, no colour wash, and the rule is the
   only thing that moves. Ember carries the hover, which is the one job the
   accent has in this system. */

.skiper40-link {
  position: relative;
  display: inline-block;
  padding: 1px 0;
  color: var(--text);
  font-size: inherit;
  line-height: inherit;
  background: none;
  border: none;
  cursor: pointer;
  transition: color var(--menu) var(--ease-out);
}

.skiper40-link::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: -1px;
  height: 1px;
  width: 100%;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: right center;
  transition: transform var(--menu) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .skiper40-link:hover { color: var(--ember); }
  .skiper40-link:hover::after {
    transform: scaleX(1);
    transform-origin: left center;
  }
}

.skiper40-link:focus-visible { color: var(--ember); outline: none; }
.skiper40-link:focus-visible::after { transform: scaleX(1); transform-origin: left center; }

/* 000 is the plain rule. 004 keeps the rule sitting there at rest and wipes it
   through instead, for links that need to look like links before they are
   pointed at. */
.skiper40-link-004::after {
  transform: scaleX(1);
  transform-origin: left center;
  background: var(--hairline-strong);
}

@media (hover: hover) and (pointer: fine) {
  .skiper40-link-004:hover::after { background: var(--ember); }
}

@media (prefers-reduced-motion: reduce) {
  .skiper40-link::after { transition: none; }
}

.skiper-nav-item {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  height: 34px;
  padding: 0 10px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text);
  opacity: 1;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  letter-spacing: -0.01em;
  cursor: pointer;
  text-align: left;
  transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), background 150ms ease;
}

.skiper-nav-item:hover {
  color: var(--text);
  opacity: 1;
  background: var(--surface-2);
}

.skiper-nav-item.is-active {
  color: var(--text);
  opacity: 1;
  font-weight: 550;
  background: var(--surface-2);
}

/* A fill, not a chip: the border made the active row 2px taller than its
   neighbours and nudged the label, which reads as a wobble when you arrow
   down the list. */
.skiper-nav-active-bg {
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: var(--surface-2);
  z-index: 0;
}

.skiper-nav-content {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  width: 100%;
  gap: 10px;
}

.sb-place-icon {
  display: grid;
  place-items: center;
  color: var(--text);
  opacity: 1;
  flex: none;
  transition: color 150ms ease, transform 150ms ease;
}

.skiper-nav-item:hover .sb-place-icon {
  color: var(--text);
  opacity: 1;
}

.skiper-nav-item.is-active .sb-place-icon {
  color: var(--accent-hover, #c084fc);
  opacity: 1;
}

.sb-place-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sb-beta-pill {
  font-family: var(--font-mono);
  font-size: 9.5px;
  font-weight: 500;
  padding: 2px 5px;
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--ember) 12%, transparent);
  color: var(--ember);
  border: 1px solid color-mix(in srgb, var(--ember) 25%, transparent);
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.sb-shortcut-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: auto;
  flex: none;
  opacity: 0;
  transition: opacity var(--pop) var(--ease-out);
}
.sb-shortcut-badge kbd {
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  font-weight: 500;
  line-height: 1;
  color: var(--text-faint);
  padding: 2px 4px;
  border-radius: 3px;
  background: rgb(var(--tint) / 0.05);
}

/* The chord is a reminder, not a label. Showing all six at rest turns the
   navigation into a two-column table you have to read past to find the word
   you want; it appears on the row under the pointer, on the row that has
   keyboard focus, and on the row you are already on. */
.sb-place-item:hover .sb-shortcut-badge,
.sb-place-item:focus-visible .sb-shortcut-badge,
.sb-place-item.is-active .sb-shortcut-badge,
.sb-place-item[aria-current] .sb-shortcut-badge { opacity: 1; }

/* Sections (STARRED & RECENTS) */
.sb-section {
  margin-top: 16px;
