  transition: opacity 150ms ease, background 150ms ease;
}

.sb-section:hover .sb-section-more {
  opacity: 1;
}

.sb-section-more:hover {
  color: var(--text);
  background: var(--surface-2);
}

.sb-section-body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 4px 0;
}

/* Only while the section's height is actually moving. Clipping it always is
   what cut the row menu in half on any conversation near the bottom of a
   section -- usually taking Delete with it. */
.sb-section-body.is-collapsing { overflow: hidden; }

.sb-empty-starred,
.sb-empty-recents {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  font-size: 12px;
  color: var(--text-dim);
}

.sb-empty-starred-icon {
  color: var(--text-dim);
  opacity: 0.8;
}

/* Bucket Headers for Recents */
.sb-bucket-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sb-bucket-header {
  padding: 14px 10px 4px;
  font-size: 11.5px;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-dim);
  opacity: 1;
  user-select: none;
}

.sb-bucket-group:first-child .sb-bucket-header {
  padding-top: 4px;
}

/* Conversation Items */
.sb-conv-item {
  position: relative;
  display: flex;
  align-items: center;
  height: 36px;
  border-radius: 8px;
  color: var(--text-sub);
  font-weight: 450;
  transition: color 150ms cubic-bezier(0.4, 0, 0.2, 1), background-color 150ms ease;
  margin-bottom: 2px;
}

.sb-conv-item:hover {
  color: var(--text);
}

.sb-conv-item:not(.is-active):hover {
  background: rgba(255, 255, 255, 0.05);
}

[data-theme="light"] .sb-conv-item:not(.is-active):hover {
  background: rgba(0, 0, 0, 0.04);
}

.sb-conv-active-bg {
  position: absolute;
  inset: 0;
  border-radius: 8px;
  background: #202124;
  border: none;
  box-shadow: none;
  z-index: 0;
}

[data-theme="light"] .sb-conv-active-bg {
  background: rgba(0, 0, 0, 0.07);
}

.sb-conv-item.is-active {
  color: #ffffff;
  font-weight: 450;
}

[data-theme="light"] .sb-conv-item.is-active {
  color: #111827;
}

/* Remove olden vertical accent stripe on active item */
.sb-conv-item.is-active::before {
  content: none !important;
  display: none !important;
}

.sb-conv-item.is-active .sb-conv-icon {
  color: #f59e0b;
}

.sb-conv-btn {
  position: relative;
  z-index: 1;
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  height: 100%;
  background: transparent;
  border: none;
  color: inherit;
  font-family: inherit;
  font-size: 13.5px;
  letter-spacing: -0.01em;
  text-align: left;
  cursor: pointer;
}

.sb-conv-icon {
  display: grid;
  place-items: center;
  color: var(--text-dim);
  flex: none;
  transition: color 150ms ease;
}

.sb-conv-icon--pinned {
  color: #f59e0b !important;
}

.sb-conv-item:hover .sb-conv-icon {
  color: var(--text);
}

.sb-conv-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: inherit;
  opacity: 0.85;
  font-weight: 450;
}

.sb-conv-item:hover .sb-conv-title {
  opacity: 1;
}

.sb-conv-item.is-active .sb-conv-title {
  color: #ffffff;
  opacity: 1;
  font-weight: 450;
}

[data-theme="light"] .sb-conv-item.is-active .sb-conv-title {
  color: #111827;
}

.sb-conv-actions {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
}

.sb-conv-more-btn {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  margin-right: 4px;
  border-radius: var(--radius-md);
  color: var(--text-faint);
  background: transparent;
  border: none;
  cursor: pointer;
  opacity: 0;
  transition: opacity 150ms ease, background 150ms ease;
}

.sb-conv-item:hover .sb-conv-more-btn,
.sb-conv-item.menu-open .sb-conv-more-btn {
  opacity: 1;
}

.sb-conv-more-btn:hover {
  color: var(--text);
  background: var(--surface-2);
}

.sb-conv-menu {
  position: absolute;
  top: calc(100% - 2px);
  right: 4px;
  z-index: 45;
  width: 170px;
  padding: 4px;
  border: 1px solid var(--hairline-strong);
  border-radius: var(--r-xl);
  background: var(--raised);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.12);
  animation: menu-in-down var(--menu) var(--ease-out) both;
}

/* Opened upward, for a row with no room under it. */
.sb-conv-menu.is-up {
  top: auto;
  bottom: calc(100% - 2px);
}

.sb-conv-menu button {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border-radius: var(--radius-md);
  border: none;
  background: transparent;
  color: var(--text-dim);
  font-size: var(--text-xs);
  text-align: left;
  cursor: pointer;
}

.sb-conv-menu button:hover {
  background: var(--surface-2);
  color: var(--text);
}

.sb-conv-menu button.danger:hover {
  background: var(--stop-soft);
  color: var(--stop);
}

.sb-conv-menu .kbd {
  margin-left: auto;
}

.sb-rename-wrap {
  padding: 4px 8px;
  width: 100%;
}

.sb-rename-input {
  width: 100%;
  padding: 5px 8px;
  border: 1px solid var(--text);
  border-radius: var(--radius-md);
  background: var(--canvas);
  color: var(--text);
  font-size: 13px;
}

/* Footer (User Profile Card & Interactive Popover) */
.sb-footer {
  display: flex;
  align-items: center;
  height: 60px;
  padding: 8px 10px;
  border-top: 1px solid var(--hairline);
  margin-top: auto;
  background: var(--canvas-deep);
  flex: none;
  position: relative;
}

.sb-user-card {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 6px 8px;
  border-radius: 12px;
  background: transparent;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease, opacity 0.15s ease, filter 0.15s ease;
  user-select: none;
  cursor: pointer;
}

.sb-user-card:hover,
.sb-user-card.is-active {
  background: rgb(var(--tint) / 0.06);
}

.sb-user-avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--r-sm, 8px);
  background: var(--surface-3);
  border: 1px solid var(--hairline-strong);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 13px;
  flex-shrink: 0;
}

.sb-user-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}

.sb-user-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.sb-user-email {
  font-size: 11px;
  color: var(--text-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.3;
}

.sb-user-actions {
  display: flex;
  align-items: center;
}

.sb-user-chevron {
  color: var(--text-faint);
  transition: transform 0.2s var(--ease-out);
}

.sb-user-chevron.is-open {
  transform: rotate(180deg);
}

/* User Popover Menu - Solid Opaque High Contrast */
.sb-user-popover,
.user-menu-popover-content,
[data-slot="dropdown-menu-content"] {
  background: var(--raised) !important;
  color: var(--text) !important;
  border: 1px solid var(--hairline-strong) !important;
  border-radius: var(--r-lg) !important;
  padding: 6px !important;
  /* A menu is one of the few things that genuinely floats over the page, so
     it is one of the few things that keeps a shadow. */
  box-shadow: var(--lift) !important;
  z-index: 1000 !important;
  opacity: 1 !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.user-menu-name-input {
  background: var(--surface) !important;
  color: var(--text) !important;
  border-color: var(--hairline-strong) !important;
}

.sb-user-popover-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 8px 6px;
}

.sb-user-popover-avatar {
  width: 32px;
  height: 32px;
  border-radius: var(--r-sm, 8px);
  background: var(--surface-3);
  border: 1px solid var(--hairline-strong);
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 13px;
  flex-shrink: 0;
}

.sb-user-popover-details {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.sb-user-popover-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sb-user-popover-email {
  font-size: 11px;
  color: var(--text-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sb-user-popover-divider {
  height: 1px;
  background: var(--hairline);
  margin: 4px 0;
}

.sb-user-popover-item {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 7px 10px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.14s var(--ease-out);
  text-align: left;
}

.sb-user-popover-item:hover {
  background: var(--surface-hover);
  color: var(--text);
}

.sb-user-popover-kbd {
  margin-left: auto;
  font-size: 10px;
  font-family: var(--font-mono);
  color: var(--text-faint);
  padding: 1px 4px;
  border-radius: 4px;
  background: var(--surface-2);
  border: 1px solid var(--hairline);
}

.sb-user-name-editor {
  padding: 6px 8px;
}

.sb-user-editor-label {
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-faint);
  margin-bottom: 5px;
}

.sb-user-editor-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sb-user-name-input {
  flex: 1;
  min-width: 0;
  padding: 4px 8px;
  font-size: 12px;
  background: var(--canvas);
  border: 1px solid var(--accent);
  border-radius: 6px;
  color: var(--text);
  outline: none;
  box-shadow: 0 0 0 2px var(--focus-ring);
}

.sb-user-save-btn {
  padding: 4px 10px;
  font-size: 11px;
  font-weight: 500;
  background: var(--accent);
  color: #ffffff;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: opacity 0.14s;
}

.sb-user-save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.sb-user-cancel-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: 6px;
  border: 1px solid var(--hairline);
  background: transparent;
  color: var(--text-faint);
  cursor: pointer;
}

.sb-user-popover-theme-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px;
}

.sb-user-popover-theme-label {
  font-size: 12px;
  color: var(--text-dim);
  font-weight: 500;
}


/* Skiper26 Theme Toggle Button */
.skiper26-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: var(--r-pill);
  border: 1px solid var(--hairline);
  background: var(--surface);
  color: var(--text);
  font-size: 12px;
  font-weight: 400;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, box-shadow 150ms ease, transform 150ms ease, opacity 150ms ease, filter 150ms ease;
}

.skiper26-toggle-btn:hover {
  background: var(--surface-2);
  border-color: var(--text-faint);
}

.skiper26-icon-wrap {
  display: grid;
  place-items: center;
}

.skiper26-label {
  font-size: 11.5px;
}

/* Workbench bar left controls (Screenshot 2) */
.wb-bar-left-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-right: var(--space-md);
}

.wb-bar-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  margin-right: 4px;
}

/* ---------------------------------------------------------- the work */

.wb-main {
  flex: 1 1 0%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--canvas-deep);
  position: relative;
  overflow: hidden;
}

.wb-main > .main {
  flex: 1;
  min-height: 0;
  background: var(--canvas-deep);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

.wb-bar-hover-trigger {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 10px;
  z-index: 100;
}

.wb-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
  flex: none;
  height: 48px;
  padding: 0 16px;
  gap: 12px;
  background: transparent;
  border-bottom: none;
  z-index: 10;
  transition: transform 0.28s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.2s ease, background 0.2s ease;
}

.wb-bar--autohide {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  transform: translateY(-100%);
  opacity: 0;
  pointer-events: none;
  background: var(--canvas-deep);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.wb-bar-hover-trigger:hover + .wb-bar--autohide,
.wb-bar--autohide:hover {
  transform: translateY(0);
  opacity: 1;
  pointer-events: auto;
}

.wb-bar-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1 1 0;
  min-width: 0;
}

.wb-bar-toggle-group {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  animation: wbFadeIn 0.22s var(--ease-out) 0.1s both;
}

@keyframes wbFadeIn {
  from { opacity: 0; transform: translateX(-4px); }
  to { opacity: 1; transform: translateX(0); }
}

.wb-bar-user-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.wb-bar-user-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 4px 4px;
  border-radius: 8px;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--text-dim);
  font-size: 12.5px;
  font-weight: 500;
  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease, opacity 0.15s ease, filter 0.15s ease;
}

.wb-bar-user-btn:hover {
  background: rgb(var(--tint) / 0.08);
  color: var(--text);
}

.wb-bar-user-name {
  max-width: 110px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Apple-style Refined Search Bar */
.wb-search-bar {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: 320px;
  height: 32px;
  padding: 0 10px;
  background: rgba(var(--tint) / 0.05);
  border: 1px solid var(--hairline);
  border-radius: 8px;
  color: var(--text-dim);
  cursor: pointer;
  transition: background-color 0.16s var(--ease-out), border-color 0.16s var(--ease-out), color 0.16s var(--ease-out), box-shadow 0.16s var(--ease-out), transform 0.16s var(--ease-out), opacity 0.16s var(--ease-out), filter 0.16s var(--ease-out);
  user-select: none;
  font-family: var(--font-body);
}

.wb-search-bar:hover {
  background: rgba(var(--tint) / 0.08);
  border-color: var(--hairline-strong);
  color: var(--text);
}

.wb-search-icon {
  color: var(--text-dim);
  flex-shrink: 0;
}

.wb-search-placeholder {
  font-size: 12.5px;
  color: var(--text-dim);
  flex: 1;
  text-align: left;
  letter-spacing: -0.01em;
}

.wb-search-kbd {
  font-size: 10.5px;
  font-family: var(--font-mono);
  color: var(--text-faint);
  padding: 1px 5px;
  border-radius: 5px;
  background: rgba(var(--tint) / 0.06);
  border: 1px solid var(--hairline);
  line-height: 1.3;
}

.wb-bar-center {
  position: static;
  transform: none;
  display: flex;
  justify-content: center;
  align-items: center;
  flex: 2 1 auto;
  max-width: 420px;
  min-width: 0;
  z-index: 2;
}

.wb-bar-brand-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.wb-bar-brand-right {
  margin-left: 8px;
  padding-left: 8px;
  border-left: 1px solid var(--hairline);
}

.wb-bar-brand-text {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 13.5px;
  letter-spacing: -0.01em;
  color: var(--text);
}

/* Center Segmented Pill Switcher (Image 1) */
.wb-segmented-pill {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  padding: 3px;
  background: rgb(var(--tint) / 0.06);
  border-radius: 9999px;
  border: 1px solid rgb(var(--tint) / 0.05);
  gap: 2px;
  z-index: 1;
}

.wb-segment-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px 14px;
  border-radius: 9999px;
  border: none;
  background: transparent;
  color: var(--text-dim);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.16s var(--ease-out), border-color 0.16s var(--ease-out), color 0.16s var(--ease-out), box-shadow 0.16s var(--ease-out), transform 0.16s var(--ease-out), opacity 0.16s var(--ease-out), filter 0.16s var(--ease-out);
  user-select: none;
}

.wb-segment-item:hover {
  color: var(--text);
}

.wb-segment-item.is-active {
  background: var(--surface-2);
  color: var(--text);
  font-weight: 600;
}

.wb-bar-actions {
  margin-left: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 1 1 0;
  min-width: 0;
  z-index: 2;
}

.wb-search-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: 9999px;
  color: var(--text-dim);
  font-size: 13px;
  cursor: pointer;
  transition: background-color 0.16s var(--ease-out), border-color 0.16s var(--ease-out), color 0.16s var(--ease-out), box-shadow 0.16s var(--ease-out), transform 0.16s var(--ease-out), opacity 0.16s var(--ease-out), filter 0.16s var(--ease-out);
  min-width: 175px;
  max-width: 230px;
}

.wb-search-pill:hover {
  border-color: var(--hairline-strong);
  background: var(--surface-2);
  color: var(--text);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
}

.wb-search-pill-icon {
  color: var(--text-faint);
  flex-shrink: 0;
}

.wb-search-pill-placeholder {
  flex: 1;
  text-align: left;
  font-size: 12px;
  color: var(--text-dim);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wb-search-pill-kbd {
  font-size: 10px;
  font-family: var(--font-mono);
  font-weight: 500;
  color: var(--text-faint);
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--surface-3);
  border: 1px solid var(--hairline);
  line-height: 1.2;
}

.wb-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: transparent;
  border: none;
  color: var(--text-dim);
  cursor: pointer;
  transition: background-color 0.15s var(--ease-out), border-color 0.15s var(--ease-out), color 0.15s var(--ease-out), box-shadow 0.15s var(--ease-out), transform 0.15s var(--ease-out), opacity 0.15s var(--ease-out), filter 0.15s var(--ease-out);
}

.wb-icon-btn:hover {
  background: rgb(var(--tint) / 0.06);
  color: var(--text);
  transform: translateY(-1px);
}

.wb-icon-btn:active {
  transform: scale(0.96);
}

.wb-icon-btn.is-active {
  background: rgb(var(--tint) / 0.09);
  color: var(--text);
}

.wb-status-dot-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: none;
  cursor: pointer;
}

.wb-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.wb-status-dot.is-error {
  background: var(--danger);
}

.wb-status-dot.is-degraded {
  background: var(--confirm);
}


.wb-warn {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: 5px 11px;
  border: 1px solid var(--confirm-line);
  border-radius: var(--r-pill);
  background: var(--confirm-soft);
  color: var(--confirm);
  font-size: var(--text-xs);
  font-weight: 500;
}
.wb-warn i { width: 6px; height: 6px; border-radius: var(--r-pill); background: currentColor; }

.icon-btn.is-on { background: rgb(var(--tint) / 0.08); color: var(--text); }

/* ------------------------------------------------------- the machinery */

.wb-panel {
  grid-column: 4;
  /* Set from the store, so a width dragged today is the width tomorrow. */
  width: var(--panel-w, 372px);
  display: flex;
  flex-direction: column;
  min-height: 0;
  border-left: 1px solid var(--hairline);
  background: var(--canvas);
  position: relative;
}
/* Nothing to show and nothing to reserve. The column is `auto`, so a hidden
   panel takes the working column's width with it. */
.wb-panel:empty { display: none; }
.wb-panel:not(:has(.wb-panel-inner)) { display: none !important; }
.wb--panel-hidden .wb-panel { display: none; }

/* Filling the window. The panel leaves the grid and covers the working area
   instead of widening its column -- widening it would re-measure the grid and
   reflow the conversation underneath, which is exactly the shudder this is
   meant to avoid. */
.wb--panel-full .wb-panel {
  position: fixed;
  inset: 0;
  z-index: 60;
  width: auto;
  border-left: none;
  animation: panel-full-in 220ms var(--ease-out);
}

@keyframes panel-full-in {
  from { opacity: 0; transform: scale(0.995); }
  to { opacity: 1; transform: none; }
}

.wb--panel-full .wb-panel-inner { max-width: 1100px; margin: 0 auto; width: 100%; }

/* The edge you pull. Four pixels wide with a twelve-pixel grab area either
   side of it -- a one-pixel border is a target nobody can hit. */
.panel-resizer {
  position: absolute;
  top: 0;
  left: -6px;
  width: 12px;
  height: 100%;
  z-index: 5;
  cursor: col-resize;
  touch-action: none;
  background: none;
  border: none;
}

.panel-resizer::after {
  content: '';
  position: absolute;
  top: 0;
  left: 5px;
  width: 2px;
  height: 100%;
  background: var(--ember);
  opacity: 0;
  transition: opacity var(--menu) var(--ease-out);
}

@media (hover: hover) and (pointer: fine) {
  .panel-resizer:hover::after { opacity: 0.5; }
}
.panel-resizer.is-dragging::after,
.panel-resizer:focus-visible::after { opacity: 1; }
.panel-resizer:focus-visible { outline: none; }

@media (prefers-reduced-motion: reduce) {
  .wb--panel-full .wb-panel { animation: none; }
  .panel-resizer::after { transition: none; }
}

/* The inner wrapper is what animates. The column itself keeps its layout
   box so the grid never re-measures mid-entrance; a translate on the child
   is the whole entrance, which is why the column's neighbours do not shift. */
.wb-panel-inner {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  height: 100%;
}

.wb-panel-head {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  flex: none;
  min-height: var(--bar-h);
  padding: var(--space-xs) var(--space-md) var(--space-xs) var(--space-lg);
  border-bottom: 1px solid var(--hairline);
}

/* Eyebrow over title: which view owns this panel. Two lines make the head a
   small hierarchy rather than a flat label -- the editorial move, and the
   reason the title can stay display-weight without shouting. */
.wb-panel-heading { display: grid; gap: 1px; min-width: 0; }
.wb-panel-eyebrow {
  font-size: var(--text-3xs);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.wb-panel-title {
  font-family: var(--font-display);
  font-size: var(--text-md);
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--text);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.wb-panel-count {
  padding: 1px 8px;
  border-radius: var(--r-pill);
  background: rgb(var(--tint) / 0.06);
  color: var(--text-dim);
  font-size: var(--text-2xs);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  transition: transform var(--press) var(--ease-out);
}
.wb-panel-head .icon-btn { margin-left: auto; }

/* The artifact view is one object that fills the panel and scrolls inside
   itself, rather than a stack of blocks that scroll together, so it opts out of
   the body's own scroll and top alignment. */
.wb-panel-body:has(.artifact) {
  overflow: hidden;
  align-content: stretch;
  /* Same reasoning as the chat chain: without this the source view's
     `white-space: pre` made the panel's contents wider than the panel, and the
     head, tabs and footer -- siblings in the same column -- grew with it. That
     is the "clicking Code moves the entire thing" report: 339px to 423px inside
     a panel that never left 372px. */
  min-width: 0;
}

.wb-panel-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: grid;
  align-content: start;
  gap: var(--space-md);
  padding: var(--space-xl) var(--space-lg) var(--space-2xl);
  /* An arriving panel's contents are animated by GSAP (motion.js); this is
     the pre-JS floor so a no-JS flash is a settled panel, never a pile of
     invisible children. */
  opacity: 1;
}

/* A hairline-guided scroll: the body tells you it continues without a
   chrome-y scrollbar shadow. Space is cheaper than decoration. */
.wb-panel-body::-webkit-scrollbar { width: 8px; }
.wb-panel-body::-webkit-scrollbar-thumb {
  background: rgb(var(--tint) / 0.08);
  border-radius: var(--r-pill);
  border: 2px solid transparent;
  background-clip: content-box;
}

.wb-panel-empty {
  padding: var(--space-xl) var(--space-xs);
  color: var(--text-faint);
  font-size: var(--text-xs);
  line-height: var(--leading-relaxed);
  /* The empty state is a statement, not an apology: it names what will fill
     this space, so the panel reads as waiting rather than broken. */
  border: 1px dashed var(--hairline);
  border-radius: var(--r-md);
  text-align: left;
}

.wb-panel-foot {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex: none;
  padding: 10px var(--space-lg);
  border-top: 1px solid var(--hairline);
  color: var(--text-faint);
  font-size: var(--text-2xs);
  font-variant-numeric: tabular-nums;
}
.wb-panel-foot .mono { margin-left: auto; color: var(--text-dim); }

/* A tool card in the panel has a column of its own to live in, so it drops the
   width games it was playing in the middle of a transcript. */
.wb-panel-body .tool-card { margin: 0; }
.wb-panel-body .reasoning { margin: 0; }

/* The Mail panel: the same slot, different contents. Everything here is
   display-only, so the styles follow the panel's own idiom -- small type,
   hairlines between the sections -- rather than inventing a second panel
   look. The sender's name is the one display-weight element in the body:
   a thread panel is about a person, and the hierarchy should say so. */
.mail-panel-who { display: grid; gap: 3px; }
.mail-panel-who .mail-panel-sub:first-child {
  font-family: var(--font-display);
  font-size: var(--text-lg);
  font-weight: 600;
  letter-spacing: -0.01em;
  text-transform: none;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mail-panel-sub {
  font-size: var(--text-2xs);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-faint);
  margin-top: var(--space-lg);
}
.mail-panel-address { font-size: var(--text-xs); color: var(--text-dim); }
.mail-panel-meta { font-size: var(--text-2xs); color: var(--text-faint); }
.mail-panel-history { display: grid; gap: 4px; }
.mail-panel-lib { display: grid; gap: 4px; }
.mail-panel-lib-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-xs);
  color: var(--text-dim);
  min-width: 0;
  padding: var(--space-3xs) 0;
}
.mail-panel-lib-item span:first-of-type {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mail-panel-lib-item .mail-when { margin-left: auto; flex: none; color: var(--text-faint); }

/* The unread badge on the mailbox rail. A count, not a pulse: it is the same
   number Gmail states about the label, and it goes away when read. Uses the
   stop palette because "unread mail" is the one count worth noticing, and a
   neutral badge reads as decoration. */
.mail-unread-badge {
  margin-left: auto;
  flex: none;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: var(--r-pill, 9px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-2xs);
  font-weight: 600;
  color: var(--stop);
  border: 1px solid var(--stop-line);
  background: var(--stop-soft);
}

/* -------------------------------------------------------- narrower windows

   Dropped from the outside in. The machinery goes first, because it is the one
   column that is about how an answer was made rather than what it says. The
   history goes next. The marks are last, and on a phone they fold into the
   drawer with it. */

@media (max-width: 1279.98px) {
  .wb-panel { display: none; }
}

@media (max-width: 1023.98px) {
  .wb-list { width: 240px; }
}

@media (max-width: 859.98px) {
  .wb { grid-template-columns: minmax(0, 1fr); }

  .wb-rail,
  .wb-list {
    position: fixed;
    top: 0;
    bottom: 0;
    z-index: 70;
    transform: translate3d(-100%, 0, 0);
    transition: transform var(--modal) var(--ease-drawer);
  }
  .wb-sidebar {
    position: fixed;
    top: 0;
    bottom: 0;
    left: 0;
    width: min(290px, 85vw);
    z-index: 70;
    transform: translate3d(-100%, 0, 0);
    transition: transform var(--modal) var(--ease-drawer);
    box-shadow: var(--lift);
  }

  .wb--drawer .wb-sidebar { transform: translate3d(0, 0, 0); }
  .wb--compact .wb-sidebar.is-hidden { display: none; }

  .wb-main { grid-column: 1; border-radius: 0; }
  .wb-bar { padding-inline: var(--space-sm) var(--space-sm); }
  .wb-where { font-size: var(--text-sm); }
}


/* ---- library: thumbnails, tags, what was mentioned ----
 *
 * A saved reel has a still, a summary and a short list of the things it named.
 * The list is the point of the feature -- a restaurant, a grinder, a book -- so
 * it reads as content rather than as metadata: the type is the quiet part and
 * the name is the loud one. */

.lib-thumb {
  display: block;
  width: 52px;
  height: 52px;
  object-fit: cover;
  border-radius: var(--r-sm);
  border: 1px solid rgba(149, 105, 254, 0.22);
  background: rgba(47, 10, 82, 0.2);
}

.lib-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2xs);
  margin-top: var(--space-sm);
}

.lib-tag {
  padding: 2px var(--space-xs);
  border: 1px solid var(--lib-border);
  border-radius: var(--r-sm);
  background: var(--lib-elevated);
  font-family: var(--font-mono);
  font-size: var(--text-3xs);
  letter-spacing: 0.04em;
  color: var(--lib-ash);
}

.lib-resources {
  list-style: none;
  margin: var(--space-xs) 0 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  font-size: var(--text-xs);
  color: var(--text-dim);
}

.lib-resources li {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.lib-resource-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 8px;
  border-radius: var(--r-md);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-1));
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--hairline));
  color: var(--text);
  font-size: 11px;
  font-weight: 500;
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--press) var(--ease-out), border-color var(--press) var(--ease-out), color var(--press) var(--ease-out), box-shadow var(--press) var(--ease-out), transform var(--press) var(--ease-out), opacity var(--press) var(--ease-out), filter var(--press) var(--ease-out);
}

.lib-resource-link:hover {
  background: color-mix(in srgb, var(--accent) 20%, var(--surface-1));
  border-color: var(--accent);
  color: var(--accent);
  text-decoration: none;
  transform: translateY(-1px);
}

.lib-resource-link:active {
  transform: scale(0.98);
}

.lib-resource-domain {
  font-size: 9px;
  color: var(--text-faint);
  letter-spacing: 0.04em;
  padding: 1px 4px;
  border-radius: 4px;
  background: color-mix(in srgb, var(--text) 6%, transparent);
}

.lib-resource-arrow {
  font-size: 10px;
  color: var(--text-faint);
  transition: transform var(--press) var(--ease-out);
}

.lib-resource-link:hover .lib-resource-arrow {
  transform: translate(1px, -1px);
  color: var(--accent);
}

.lib-resource-kind {
  display: inline-block;
  padding: 2px 6px;
  border-radius: var(--r-md);
  background: var(--surface-2);
  border: 1px solid var(--hairline);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-faint);
}

.lib-resource-detail { color: var(--text-faint); font-size: 11px; }


/* ------------------------------------------------------- touch targets

   Last in the file on purpose. These override sizes chosen for a cursor, and
   several of those (`.task-check`, `.btn--small`) are declared hundreds of
   lines below where this block first sat — so it lost on source order and the
   17px tick box stayed 17px on a phone. Nothing is allowed to come after. */

@media (pointer: coarse) {
  .icon-btn { min-width: 40px; min-height: 40px; }

  /* Three controls that had a size chosen for a cursor. The box grows; the
     mark inside does not, so the row still looks the way it was drawn. */
  .wb-conv-more { min-width: 38px; min-height: 38px; }
  .btn--small { min-height: 38px; padding-block: 8px; }

  /* A 17px tick box is a miss on a phone. 30px is the size a list checkbox is
     on both mobile platforms, and the extended hit area below takes it past 44
     without making the mark itself look heavy. */
  .task-check {
    position: relative;
    width: 30px;
    height: 30px;
    margin-top: 0;
    border-radius: var(--r-pill);
  }
  .task-check::after {
    content: '';
    position: absolute;
    inset: -7px;
  }
}

/* --- Add Content Modal (Recall-style Screenshot 3) --- */
