.md-image-single .md-image-thumb-wrap {
  width: 100%;
  aspect-ratio: 16 / 10;
  height: auto;
  max-height: 340px;
}

.md-image-gallery--count-2 {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.md-image-gallery--count-2 .md-image-thumb-wrap {
  width: 100%;
  aspect-ratio: 16 / 10;
  height: auto;
  max-height: 240px;
}

.md-image-gallery--count-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.md-image-gallery--count-3 .md-image-thumb-wrap {
  width: 100%;
  aspect-ratio: 16 / 10;
  height: auto;
  max-height: 220px;
}

@media (max-width: 640px) {
  .md-image-gallery {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }
}

@media (max-width: 420px) {
  .md-image-gallery {
    grid-template-columns: minmax(0, 1fr);
    gap: 8px;
  }
}

.md-image-card {
