  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.86);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px;
  animation: md-lightbox-fade-in 0.18s ease-out;
}

@keyframes md-lightbox-fade-in {
  from { opacity: 0; transform: scale(0.98); }
  to { opacity: 1; transform: scale(1); }
}

.md-lightbox-content {
  position: relative;
  max-width: 90vw;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.md-lightbox-img {
  max-width: 100%;
  max-height: 75vh;
  object-fit: contain;
  border-radius: 12px;
  box-shadow: 0 16px 52px rgba(0, 0, 0, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.md-lightbox-caption {
  margin-top: 12px;
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: #e2e8f0;
}

.md-lightbox-caption a {
  color: #38bdf8;
  text-decoration: none;
  font-weight: 500;
}

.md-lightbox-caption a:hover {
  text-decoration: underline;
}

.md-lightbox-close {
  position: absolute;
  top: -40px;
  right: 0;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 50%;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}

.md-lightbox-close:hover {
  background: rgba(255, 255, 255, 0.22);
  transform: scale(1.08);
}

.md-image-fallback {
  display: inline-flex;
  font-size: 12px;
  color: var(--text-dim, #64748b);
  background: var(--surface-2, rgba(255, 255, 255, 0.04));
  border: 1px solid var(--hairline, rgba(255, 255, 255, 0.08));
  padding: 2px 8px;
  border-radius: 4px;
}

/* =========================================================================
   RICH DOCUMENT EDITOR, FLOATING SELECTION BUBBLE, AND SOURCES DRAWER
   (Matching Reference Images 1, 2, 3, 4, 5)
   ========================================================================= */

/* Floating Selection Bubble (Image 4 & Image 5) */
.floating-selection-bubble {
  position: fixed;
  z-index: 999999;
  display: flex;
  align-items: center;
  border-radius: 8px;
  background: #18181b;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6), 0 2px 6px rgba(0, 0, 0, 0.4);
  color: #f8fafc;
  user-select: none;
  animation: bubblePopIn 0.16s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform, opacity;
}

@keyframes bubblePopIn {
  from {
    opacity: 0;
    transform: translate3d(0, 6px, 0) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0) scale(1);
  }
}

.selection-toolbar-inner {
  display: flex;
  align-items: center;
  padding: 3px 6px;
  gap: 2px;
}

.bubble-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 28px;
  padding: 0 8px;
  background: transparent;
  border: none;
  border-radius: 5px;
  color: #e2e8f0;
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.12s ease;
  white-space: nowrap;
}

.bubble-btn:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.bubble-ask-btn {
  font-weight: 500;
}

.bubble-refer-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #fff;
  font-weight: 500;
}

.bubble-refer-btn:hover {
  background: color-mix(in srgb, var(--accent, #873FFF) 24%, transparent);
}

/* Quoted / Referenced text banner in composer */
.composer-quote-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 8px 12px;
  background: color-mix(in srgb, var(--accent, #873FFF) 8%, var(--raised));
  border: 1px solid color-mix(in srgb, var(--accent, #873FFF) 28%, var(--hairline));
  border-left: 3px solid var(--accent, #873FFF);
  border-radius: 10px;
  margin-bottom: 2px;
  animation: quoteBannerIn 0.16s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes quoteBannerIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.composer-quote-main {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.composer-quote-header {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--accent, #873FFF);
}

.composer-quote-icon {
  opacity: 0.9;
}

.composer-quote-snippet {
  font-size: 12.5px;
  line-height: 1.4;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  word-break: break-word;
  white-space: normal;
}

.composer-quote-remove {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: transparent;
  border: none;
  color: var(--text-dim);
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.12s ease;
}

.composer-quote-remove:hover {
  background: color-mix(in srgb, var(--text) 10%, transparent);
  color: var(--text);
}

.bubble-shortcut-tag {
  font-size: 11px;
  color: #94a3b8;
  font-family: var(--font-mono, monospace);
  font-weight: 400;
  margin-left: 2px;
}

.bubble-divider {
  width: 1px;
  height: 16px;
  background: rgba(255, 255, 255, 0.14);
  margin: 0 4px;
}

.bubble-icon-btn {
  width: 28px;
  padding: 0;
}

.bubble-typography-symbol {
  font-size: 13px;
  line-height: 1;
}

.bubble-dropdown-anchor {
  position: relative;
}

.bubble-select-btn {
  padding: 0 8px;
  gap: 5px;
  color: #cbd5e1;
}

.bubble-select-btn.is-active {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}

.bubble-dropdown-menu {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  min-width: 220px;
  background: #18181b;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 8px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.7);
  padding: 4px;
  z-index: 10001;
  display: flex;
  flex-direction: column;
  gap: 1px;
  animation: dropdownPop 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform, opacity;
}

.bubble-dropdown-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 6px 10px;
  background: transparent;
  border: none;
  border-radius: 5px;
  color: #cbd5e1;
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  transition: all 0.1s ease;
}

.bubble-dropdown-item:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.bubble-dropdown-item.is-selected {
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
  font-weight: 600;
}

.dropdown-item-shortcut {
  font-size: 10.5px;
  color: #64748b;
