}

/* Slash Commands Popover (Image 2) */
.slash-commands-popover {
  position: absolute;
  z-index: 50;
  width: 160px;
  background: #18181b;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 8px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.65);
  padding: 4px;
  display: flex;
  flex-direction: column;
  gap: 1px;
  animation: dropdownPop 0.15s cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform, opacity;
}

.slash-cmd-item {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 6px 10px;
  background: transparent;
  border: none;
  border-radius: 5px;
  color: #cbd5e1;
  font-size: 12px;
  text-align: left;
