}

.sources-card-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  overflow-y: auto;
}

.source-activity-card {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 11px 13px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.08);
  text-decoration: none;
