  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  overflow: hidden;
  flex-shrink: 0;
}

.source-card-favicon {
  width: 14px;
  height: 14px;
  object-fit: contain;
}

.source-fallback-badge {
